window.__D("text/torat-chaim/c020",{"p":[[2300540976,"לרצון מתלבשים בשכל וטעם הגלוי (כנ\"ל בענין השוחד ואהבת [ה]אב לבנו וכה\"ג) אלא שיוכל לפשוט את לבוש השכל מהיפוך להיפוך כנ\"ל. אלא בהכרח צ\"ל שיש ב' מדרגות בחכ' שברצון (הנק' ח\"ס) א' פנימי' שבו שא\"א לבוא לגילוי שכל כלל והוא למעלה ג\"כ מהתחלקות החו\"ג דרצון עד שיוכל להטות מרצון לרצון היפוכו (כמו יה\"ר מלפניך שיכבשו<sup data-n=\"6312\">818</sup> כו'), והיינו בבחי' כת\"ר שבכת\"ר שע\"ז א' ג\"כ והחכ' שהוא <sup data-n=\"6313\">819</sup>חכ' מאין ממש שנק' רצון פשוט ועצמי ממש שאין טעם לרצון כלל אפי' טעם כמוס ונעלם כו' ע\"כ יכול להחליף מרצון לרצון כו' (וכמו ענין סליחת העוונות לעוברי רצונו כו' וכענין והי' על מצחו תמיד לרצון שנק' רעדכ\"ר כו' וד\"ל). והב' בחי' חיצוניות דחכ' שברצון שהוא מקור לתולדות והתהוות המדות שברצון לחו\"ג ממש שלא יוחלף כלל והן המתלבשים בשכל וטעם גלוי שבא מהעלם כח השכל לגילוי (שז\"ש והחכ' מאי\"ן תמצא בבחי' י\"ש כו') והיינו ענין מה שאו\"א מלבישים לזרועות דא\"א דאבא מלביש לחסד דא\"א שהוא ענין קו הימין חח\"נ ואימא מלביש לגבו' דא\"א וכמ\"ש אני בינה לי גבו'<sup data-n=\"6314\">821</sup> כו' כידוע והוא שרש קו השמאל בג\"ה<sup data-n=\"6315\">820</sup> (וזהו ענין הגדול הגבור והנורא שהוא בחי' חג\"ת דא\"א<sup data-n=\"6316\">822</sup> כידוע). אך לפ\"ז בא בחי' הטיי' הרצון שנק' חו\"ב דא\"א בחו\"ב דאצי' בדרך השתלשלו' מיש ליש כמו השתלשלו' דחו\"ב [ב]מדות שבלב דבחי' מדות אוי\"ר שבשכל והשגה במוח בינה באים ונמשכים להתהוות תולדות המדות שבלב שאין כל חדש בעיקר מציאות[ן] רק שיצאו מן ההעלם לגילוי לבד שנק' יש מיש כידוע וכמו ממדות אהוי\"ר שבלב יוצאים לגילוי במחשבה והרהור וממח' לדבור כו', כך הוא בהמשכת חו\"ג דרצון בחו\"ב <span data-k=\"pg\">קסה</span> ּ והוא מה שהרצון נוטה לחסד הרי יצאו מהעלם לגילוי בשכל להטות בשכלו ג\"כ כלפי חסד כו' שזהו כשאר השתלשלו' עו\"ע ולא מאי\"ן ליש הנק' דילוג כו', וא\"כ איך יובן ענין ויוציאנו ה' אלקינו משם שהוא [מ]בחי' עורף דאחוריי' דכת\"ר המונע הלידה כו' ביד חזקה כו' שהן בחי' ב' זרועות דחו\"ג דא\"א כו', מאחר שהמדות דחו\"ג הללו מלובשים בחו\"ב בדרך גילוי מן ההעלם לבד מהיכן יהי' בחי' ההבדלה בין פנימי' הרצון לחיצוני' הרצון שבו (כי חו\"ג באים בנו\"ה תחלה ונו\"ה דא\"א מתלבשים באו\"א כפי סדר התלבשות הפרצופי' כידוע). אלא צ\"ל שיש ב' מדריגות בזה א' כשבא הרצון שנק' כת\"ר [בהשתלשלות מחו\"ב שבו למדות דחו\"ג ואז המדות הן רק לפ\"ע הטעם כמוס שברצון ובאים] בהתלבשות בחו\"ב בגילוי כנ\"ל. והב' בבחי' הגבה[ת] והתנשאות המדות דרצון למעלה מעלה גם מטעם כמוס לרצון כו', שזהו בחי' כת\"ר שבכת\"ר הנ\"ל שאין טעם לרצון כלל אפי' טעם כמוס [כו'] וכענין שתוק [כך] כו'. והיינו מ\"ש קח\"ם על זרועותיו כמו וינטלם וינשאם [כו'] וכן ואשא אתכם<sup data-n=\"6317\">823</sup> על כנפי נשרים כו' וכה\"ג שהוא",[["6312","818","<b>יה\"ר מלפניך שיכבשו</b>: נסמן לעיל פ' שמות כט, ב."],["6313","819","<b>חכ'</b>: ביד: ח\"ס מאין כו'."],["6314","821","<b>אני בינה לי גבו'</b>: נסמן לעיל פט, ב."],["6315","820","<b>קו הימין חח\"נ. . בג\"ה</b>: נסמן לעיל פ' וארא פד, ד."],["6316","822","<b>הגדול. . חג\"ת דא\"א</b>: ראה גם מאמרי אדה\"א ויקרא ח\"א ע' ריז. לקמן פ' בשלח רד, ד."],["6317","823","<b>ואשא אתכם</b>: יתרו יט, ד."]]],[2300540981,"למעלה מהתחלקות הרצון כו'. ואמנם הרי גם בעצם נקודת פנימי' הרצון יש ימין ושמאל עד\"מ [מאהבת חיי נפשו ואינו רוצה למות כו' וכן באהבת נפשו לבנו יחידו ותכלית שנאה לשונאו שהן ב' קוין דחו\"ג אבל הן בבחי'] עצמיות דיחידה כו' שלעולם לא יהופך מזה לזה כלל והוא עיקר ומקור ההבדלה בין פנימי' הרצון לחיצוני' הרצון דבבחי' פנימי' הרצון אין שם נטי' כלל בחו\"ג שבו כו'. וזהו ויוציאנו ה' אלקינו דוקא שהוא בבחי' פנימי' דחו\"ב<sup data-n=\"6318\">824</sup> דא\"א כמו שהוא בעצמו' הרצון והיינו ביד חזקה וזרוע נטויה שהן ב' זרועות דא\"א כמו שהן למעלה מעלה גם מטעם כמוס לרצון כו', וע\"כ הי' הכח מהם להוציא את בנ\"י ממצרים שהוא ע\"י בחי' ההבדלה בין פנימיות לחיצוני' שבו הנק' עורף כו' שיוכל להיות בחי' הלידה, דהיינו בחי' קטנות המדות דאוי\"ר הכלולים במיצר מ\"י דבינה שיכול[ים] לבא לבחי' גילוי אור גדול בלתי מניעה ועיכוב כלל מבחי' העורף דפרעה כו' מצד שנתעלו למעלה מעלה בחי' פנימי' הכת\"ר שבכת\"ר (שהוא בחי' חו\"ג דע\"י דחסד דע\"י מלובש בגלגלתא דא\"א וגבורה דע\"י במו\"ס דא\"א). וע\"כ האיר ה' פניו לישראל [דוקא] בימין מקרבת ושמאל דוחה למצרים בשעה א' כמ\"ש נגוף ורפוא<sup data-n=\"6319\">825</sup> כו' וכמ\"ש לקחת לו גוי [מקרב גוי] כו', והיינו [ענין] ב' מדות דחו\"ג שבפנימיות ועצמות דא\"ס ב\"ה בא[מרו] אנכי ולא יהי' לך שזהו ימין מקרבת להיות גילוי אור העצמות ע\"י מ\"ע ומל\"ת<sup data-n=\"6320\">826</sup> דוחה לרחק השנאוי והתעוב שהן שס\"ה ל\"ת כו', והוא שרש גדלות המוחי' דז\"א בתו\"מ ברמ\"ח אברים כו'. וע\"כ אפילו כולנו חכמים<sup data-n=\"6321\">827</sup> ויודעים את התורה מצוה לספר ביצ\"מ לפי שיצ\"מ הי' עיקר<sup data-n=\"6322\">828</sup> יד החזקה כו' שהוא שרש הראשון לבחי' גדלות המוחי' דז\"א בתו\"מ וכמ\"ש מימינו אש דת למו<sup data-n=\"6323\">829</sup> שכלול מחו\"ג דעצמות המאציל ממש וד\"ל.\n<b>והנה</b> לכאורה יש סתירה לענין הנ\"ל מה שאו\"א מלבישים לזרועות דא\"א, שהרי לפעמים א' בע\"ח דאור אבא יונק<sup data-n=\"6324\">830</sup> ממזל הח' ונוצר ואור אימא ממזל הי\"ג ונקה וב' מזלות [הללו] דא\"א הן ממו\"ס שנמשך מהן תוס' מוחי' לאו\"א, כמו הכל תלוי במזל אפי' ס\"ת בהיכל<sup data-n=\"6325\">831</sup> שהוא יחוד או\"א [כנקודה דחכ' בהיכל בינה גם זה תלוי במזל דא\"א כו' וכענין מזל מחכים<sup data-n=\"6326\">832</sup> כו'. ופי' יונק, יניקה זאת היא מרחוק ובהעלם דרך שערות] שהוא כמו ונוצ\"ר חסד אותיות צנו\"ר<sup data-n=\"6327\">833</sup> כו' כידוע. וזהו סותר לענין ההלבשה דאו\"א<sup data-n=\"6328\">834</sup> שהלבוש הוא בקירוב יותר ולזרועות היינו <span data-k=\"pg\">332</span> ּ המדות חו\"ג דא\"א כו'. אך הנה תחלה יש להבין ענין ובחי' יניקה זאת שהוא עד\"מ ולד היונק מחלב אמו שהוא <sup data-n=\"6329\">835</sup>בחי' שלימה במהות בפ\"ע נבדל מאמו שכבר נתהווה מציאותו רק שיניקת החלב הוא לחיות מזונו לבד, ולא יתהווה עיקר מציאת",[["6318","824","<b>דחו\"ב</b>: ביד: דח\"ס."],["6319","825","<b>נגוף ורפוא</b>: ראה לעיל פז, א. וש\"נ."],["6320","826","<b>ומל\"ת</b>: ביד: ושמאל."],["6321","827","<b>אפילו כולנו חכמים</b>: ע\"פ הגש\"פ (עבדים היינו)."],["6322","828","<b>עיקר</b>: ביד: ע\"י."],["6323","829","<b>מימינו אש דת למו </b>[ביד: כו']: ברכה לג, ב."],["6324","830","<b>דאור אבא יונק</b>: נסמן לעיל פ' שמות לו, א."],["6325","831","<b>הכל. . ס\"ת בהיכל</b>: נסמן לעיל פ' שמות יא, א."],["6326","832","<b>מזל מחכים</b>: שבת קנו, א. וראה לקמן קלב, ד."],["6327","833","<b>ונוצ\"ר חסד אותיות צנו\"ר</b>: נסמן לעיל פ' שמות יב, ב."],["6328","834","<b>דאו\"א</b>: יד ניתוסף: לזרועות דא\"א."],["6329","835","<b>בחי'</b>: ביד: ברי'."]]],[2300540986,"חיות נפשו וגופו מן החלב [רק] שהחלב הוא מזון לנפשו וגידול[ו] באברי[ו], וגם עצם הנפש שבו בשכל ומדות (בחומר שלהם) מתגדל כל ימי היניקה כידוע (כמו שבעיבור אוכל מה שאמו אוכלת דרך טיבורו ופיו סתום שמזה מתגדלים אבריו בט\"ח כו'). וכך הוא ענין אור אבא יונק ממזל הח' כו' שהחכמה כבר [נמצאת] במציאות שלימה במהות בפ\"ע כמ\"ש והחכמה מאי\"ן תמצא במציאת דבר בפ\"ע, רק שע\"י היניקה מן המזל שהוא מזל ונוצר כו' מקבל יניקה וחיות נוסף על עצם מהותו כמו מזון ממש, שעי\"ז [י]תחזק כח ואור החכ' כמ\"ש מזל מחכים בח\"ס<sup data-n=\"6330\">836</sup> חכמה מכח המשכיל בריבוי גדול כמו מזל מעשיר<sup data-n=\"6331\">837</sup> שימצא תוס' ברכה במעשה ידיו כו', והוא ענין גידול אור החכמה בכל פרטי כחותי'<sup data-n=\"6332\">838</sup> כולד הגדל [מ]יניק[ת] חלב אמו. ודוגמא לזה הוא מה שאנו רואים שיגדל אור וכח השכל בתינוק לפי שניו וימיו מעט מעט כמ\"ש אך בצל\"ם יתהלך איש צ\"ל דצל\"ם הוא בחי' [ה]מקיף דחכמה ובינה<sup data-n=\"6333\">839</sup> שנמשך מן העלם כח המשכיל שיוכל להשכיל שכל וחכמה בכל הענינים אם בענין המושכלות ולימודי' אם בעניני מדותיו לשפוט בדעת שלימה לחו\"ג כו', כ\"ז נכנס בכלי מוחו מעט מעט מדי יום ויום לפ\"ע גידולו בימים ושנים עד שיזקין כמ\"ש ימים ידברו<sup data-n=\"6334\">840</sup> ורוב שנים יודיעו חכמה (וכנ\"ל בענין גדלות ראשון דאימא וגדלות שני דאבא כו'). וכך הוא גם בעיקר גידול מהות אור החכמה עצמה כאשר נמצא במציאות מאין ליש כמ\"ש והחכ' מאין תמצא במציאות ממש כנ\"ל שהוא עדיין בבחי' הקטנות בחומר ההיולי ונגדל מעט מעט מבחי' מזל ונוצר חסד דא\"א כמ\"ש דאבא יונ\"ק ממזל הח' כו' כמו מזל מחכים שמחכים לחכמה<sup data-n=\"6335\">841</sup> מן ההעלם לגילוי בתוס' וריבוי גדול וכמו וה' נתן חכ' לשלמה<sup data-n=\"6336\">842</sup> [ו]כמו יהיב חכמתא<sup data-n=\"6337\">843</sup> כו' וד\"ל.\n<b>והנה</b> גידול זה דחכ' מבחי' המזל דונוצר כו' (ע\"ד שא' הכל תלוי במזל אפי' ס\"ת בהיכל כו') זהו בא בבחי' הדילוג בהעלם גדול בערך נבדל ורחוק מאד כו', ולא [כ]שאר השתלשלות עו\"ע כלל, ולא אפי' בהשתלשלו' דמאין ליש כמו כח<sup data-n=\"6338\">844</sup> השכל הבא מכח המשכיל [מן] ההעלם לגילוי שיש יחוס וקירוב הערך בזה לפ\"ע כח כלי המקבל ולפ\"ע כח המשפיע שהוא כח השכל ההיולי, כמו התלמיד שכלי מוחו מוכן לקבל אור שכל עמוק ונעלם ביותר, וכן חכם עצמו הבא על איזה שכל וחכ' שנמשך מכח החכמה שבו שמוליד שכל חדש מן ההעלם לגילוי דודאי יש קצת ערך לשכל זה הגלוי בעצם כח המשכיל והולידו כו' אע\"פ שנק' מאין ליש ולא יש מיש כו'. ותחלה יש להבין ההפרש שבין מיש ליש לאין ליש כידוע בענין השתלשלו' השכל ומדות ומו\"ד, שגם שאין מהות המדות ממהות שכל כלל",[["6330","836","<b>בח\"ס</b>: שם: שע\"י המזל יחכים בתוס'."],["6331","837","<b>מזל מעשיר</b>: שבת קנו, א."],["6332","838","<b>כחותי'</b>: ביד: כוחות שבה."],["6333","839","<b>צ\"ל דצל\"ם. . ובינה</b>: ראה גם שער האמונה ט, א."],["6334","840","<b>ימים ידברו</b>: איוב לב, ז."],["6335","841","<b>לחכמה</b>: ביד: לחכם."],["6336","842","<b>וה' נתן חכ' לשלמה</b>: מלכים-א ה, כו."],["6337","843","<b>יהיב חכמתא </b>[ב ניתוסף: לחכימין]: נסמן לעיל קיב, ב."],["6338","844","<b>כח</b>: ביד: ליתא."]]],[2300540991,"עכ\"ז ודאי היו המדות כלולים בשכל עצמו ונק' מדות שבשכל, כמו התפעלות אוי\"ר שבשכל שבמוח אע\"פ שהן התפעלות שכליי' שנק' דו\"ר שכליי' או שכל המטה כלפי חו\"ג <span data-k=\"pg\">קסו</span> ּ שכלולים בהעלם בתוך השגת השכל עצמו ולא ניכרים במציאות מהות מדות כלל רק התפעלות שכליי' לבד, מ\"מ בחי' מדות הן עכ\"פ רק שכלולים בשכל ויוצאים אח\"כ מן ההעלם לגילוי לבד שאין כח<sup data-n=\"6339\">845</sup> כלל בעיקר מציאותן כשבאים ללב שנעשים במהות התפעלות מדות אהוי\"ר שבלב דזהו הנק' יש מיש שאם לא הי' מציאות מדות כלל בשכל עצמו לא הי' התהוות מדות הללו בלב כלל. ויובן זה יותר במו\"ד שנולדים זה מזה באותיות הדבור בקול גשמי מתהוים [מ]אותיות המח' שחושב תחלה מה שידבר, הרי אין התהוות הדבור מציאות חדש שלא הי' כלל תחלה שהרי אותיות הדבור הללו הי' כבר במחשבה ממש כמו שהן עתה בגילוי רק שהיו כלולים בהעלם במחשבה ונק' דבור שבמח' כידוע רק שיוצאים מהעלם המח' לגילוי הדבור כשחושב מה שידבר, ואם לא הי' בחי' דבור במח' לא הי' נמצא אותיות התורה<sup data-n=\"6340\">846</sup> מן המח' כלל, וזהו הנק' יש מיש כידוע (וכן מבחי' עשי' שבדבור נמשך המעשה בפו\"מ והוא הציווי לעשות ו[כ]עקימת שפתי[ו] דהוי מעשה<sup data-n=\"6341\">847</sup> שבדבור כמ\"ש במ\"א, רק שהמעשה נבדל מן הדבור יותר מהבדל הדבור מן המח' כו'). וכן המעשה בפו\"מ שנמשך מכח התנועה ההיולי שה[ח]י מניע כל תנועה אין זה רק גילוי ההעלם שבודאי יש מציאות תנועה זו בכח המניע עצמו תחלה רק שיוצא מן ההעלם לגילוי התנועה לבד כו'. וכך יובן באותיות המח' עצמה שנמשך<sup data-n=\"6342\">848</sup> מן השכל או המדות שבלב דגם שנראים בתולדות החדשה<sup data-n=\"6343\">849</sup> במהות נבדל בפ\"ע מן השכל או המדות שבלב, עכ\"ז ודאי מוכרח שהי' מציאות המח' עצמה<sup data-n=\"6344\">850</sup> כלולה בהעלם בתכלית במדות או בשכל ולא ניכר במציאות מחשבה והרהור כלל ואח\"כ יצאו לגילוי אותיות המח' והרהור, כמו שאנו רואים מיד שישכיל אדם איזה שכל יתהווה אותיות מח' לחשוב ולהרהר כו'<sup data-n=\"6345\">851</sup> (או להיפוך שיתחיל לחשוב ולהרהר באיזה מושכל עד שישכילנו וישיגנו היטב, וכן אותיות מחשבה שחושב באיזה ענין ודבר מה [שהן] יוצאים מהעלם כמו<sup data-n=\"6346\">852</sup> המח' שבנפש כמו גילוי התנועה מהעלם כח המניע כו'), או כמו מיד שיתפעל באוי\"ר בלב מתהווה הרהור אותיות במח' בדבר האהוב בלבו או ירא ממנו, שבודאי היו אותיות המח' הללו כלולים בהעלם תחלה במדות שבלב או בשכל שבמוח, ואין זה אלא<sup data-n=\"6347\">853</sup> גילוי הרהור המח' שנתפשט ויצא מן העלמה באור האהוי\"ר שבלב לגילוי מהות אותיות מח' ממש כו', וא\"ל לא היו מתהוים מציאות אותיות המח' אלה כלל (ונת'<sup data-n=\"6348\">854</sup> במ\"א שהמח' היא באה מאין ליש<sup data-n=\"6349\">855</sup> ולא יש מיש, לפי שמהות המח' לא הי' תחלה כלל במציאות מח' כשהיתה כלולה בשכל או",[["6339","845","<b>כח</b>: ביד: כל חדש."],["6340","846","<b>התורה</b>: שם: הדיבור."],["6341","847","<b>ו[כ]עקימת שפתי[ו] דהוי מעשה</b>: נסמן לעיל פ' שמות ה, א."],["6342","848","<b>שנמשך</b>: ביד: שנמצאת."],["6343","849","<b>בתולדות החדשה</b>: שם: כתולדה חדשה."],["6344","850","<b>עצמה</b>: שם: ליתא."],["6345","851","<b>כו'</b>: שם: בו."],["6346","852","<b>כמו</b>: שם: כח."],["6347","853","<b>אלא</b>: שם: רק."],["6348","854","<b>ונת'</b>: שם: ומבואר."],["6349","855","<b>שהמח'. . מאין ליש</b>: ראה מאמרי אדה\"ז תקס\"ג ח\"א ע' שיב. ח\"ב ע' תר. לקו\"ת ר\"פ בלק. מאמרי אדה\"א במדבר ח\"ה ע' א'תתמט. וש\"נ. לקמן פ' בשלח קלט, ד. קמו, א."]]],[2300540996,"במדות, וכ\"ש כמו שהיא בנפש שנק' כח המח' לחשוב ולהרהר בשכל או להרהר בדבר האהוב עד שיתפעל באהבה או ביראה בלב שיולד מהרהור במוח דוקא כו', אך עכ\"ז אין זה התהוות מציאות חדשה לגמרי רק ה[י]א [באה] מן כח הנעלם לגילוי (כמו רוח ממללא שהוא כח של הדבור ש[ר]ש כל כ\"ב אותיות הנגל[ים] בכח והעלם ונק' רוח ממללא נפש המדברת ויוצאי' לגילוי מן ההעלם לבד בה' מוצאות הפה כו', וכך הוא בכח המח' שבנפש כו').\n<b>ונמצא</b> מובן מכ\"ז עכ\"פ שגם בחי' התהוות יש מאין נק' גם הוא מן ההעלם לגילוי דהיינו <span data-k=\"pg\">334</span> ּ כמו כל עלול הנמשך מן העילה שלו שהי' כלול תחלה ממש במהות[ו] [ב]עילה שלו כמו מהות המדות בשכל ומח' במדות ודבור במחשבה כו' כנ\"ל, רק אח\"כ יוצא מן ההעלם לגילוי שזהו עיקר ענין ההשתל' כשלשלת<sup data-n=\"6350\">856</sup> ממש שטבעת התחתונה קשורה בתוך העליונה כו', וא\"כ [י]ובן מזה שגם בהתהוות מציאות החכ' מלמעלה מן החכ' כמ\"ש והחכמה מאי\"ן תמצא כמו המשכיל ומוליד שכל חדש כנ\"ל מאחר שנק' בשם מציאות שכל אין זה מציא[ה] חדשה לגמרי שלא הי' כלל, כי ודאי הי' שכל זה עצמו כלול תחלה בהעלם כח המשכילו ומולידו כו' רק שלא הי' ניכר במציאות שכל כמו שהוא עתה ויצא אח\"כ מהעלמו לגילוי מציאות השכלה. וראי' לזה ממה שישכיל שכל לזכות או לחוב שהן ב' הפכים ויש לכ\"א מקור מוצא הממשיך אותו מן ההעלם לגילוי כמו ב\"ש אומרים כו', או שלש<sup data-n=\"6351\">857</sup> חכמים משכילים בחכ' א' זה כח שכלו מטה כך וזה כך כו', וכמו שיש חכמים להרע או להטיב כו', רק שהמקור הממשיך ונובע הוא נק' כח שכל זה הנעלם כמעיין הנובע מן ההעלם (וכמו כח המח' וכח הדבור <sup data-n=\"6352\">858</sup>כו' ), שאם לא יש מציאות חכ' בלמעלה מן החכמה כלל איך יתהוה מציאות חכמה, כמו שאם לא הי' מציאות המדות בשכל לא הי' מתהוים מציאות מדות וכן המו\"ד כנ\"ל וד\"ל. (וראי' לזה ממה שאנו רואים בענין התהוות הטעם לרצון דודאי אין טעם לרצון כלל, כי טבע עצם הרצון למעלה מן הטעם, ומאין נולד מציאות השכל והטעם לרצון, אין זה אלא שזה הטעם כלול תחלה ברצון עצמו בביטול והתכללות בהעלם תחלה ויצא אח\"כ לגילוי מן ההעלם. וכך גם ברצון עצמו שנתהווה מלמעלה מן הרצון הי' כלול תחלה בעצמות הנפש שמשם מקור כל התהוות רצון רק שהי' בהעלם ויצא אח\"כ לגילוי מן ההעלם<sup data-n=\"6353\">859</sup>. וכך הוא ענין התהוות התענוג מלמעלה מן התענוג כו' (ולפי<sup data-n=\"6354\">860</sup> כל הנ\"ל<sup data-n=\"6355\">861</sup> פי' והחכ' מאין תמצא היינו מאין והעלם לגילוי יש במציאות כנ\"ל במדות ומו\"ד וכה\"ג שנק' יש מיש לבד כנ\"ל, וא\"כ הרי אין הפרש כלל בין מיש ליש ובין מאין ליש<sup data-n=\"6356\">862</sup> דשניהם אינו אלא",[["6350","856","<b>ההשתל' כשלשלת</b>: נסמן לעיל פ' שמות כד, ב."],["6351","857","<b>שלש</b>: ביד: שני."],["6352","858","<b>כו'</b>: ב: ליתא. יד: כנ\"ל."],["6353","859","<b>מן ההעלם</b>: שם: מהות רצון כו'."],["6354","860","<b>כו' (ולפי</b>: שם: כו'). ולפי."],["6355","861","<b>הנ\"ל</b>: שם: זה."],["6356","862","<b>מיש. . ליש</b>: שם: יש מיש ליש מאין."]]],[2300541001,"בבחי' העלם וגילוי כפי כל הנ\"ל. ובאמת הרי פי' יש מאין הוא מאין ממש שהוא ענין חידוש המציאות דוקא וכפי [פי'] הפשוט דהחכ' מאין תמצא כלומר מהיכן שלא נודע מקורה כלל וכלל וכמו המציא[ה] שלא נודע ממי יצא[ה] כו' וכאלו אין לה מקור כלל וכלל מקרא<sup data-n=\"6357\">863</sup> סיפא דקרא ואי[ז]ה מקום בינה כנ\"ל<sup data-n=\"6358\">864</sup> וד\"ל.\n<b>אך</b> הנה באמת יש הפרש [גדול] בזה דכל מה שנמשך אח\"כ למדות וממדות למוד\"מ<sup data-n=\"6359\">865</sup> כנ\"ל נק' יש מיש אבל התהוות [ה]חכ' מלמעלה מן החכמה הוא יש מאין ממש כפי' הפשוט דהחכמה מאין תמצא הנ\"ל, כי הגם שבהכרח לומר שיש מציאות החכ' בלמעלה מן החכ' דאל\"כ מהיכן הי' נמצא מציאת החכמה כנ\"ל אך אין זה כמו שנמצא מציאות המדות בחכ' בהעלם תחלה או [המח'] במדות כו'. דהנה אנו רואים שנמצא מציאות המדות בשכל במהותן ומציאותן כמו שהן ממש במציאותן במקומן בלב למטה בגילוי במורגש דהיינו בחי' התפעלות אוי\"ר ממש במוח רק שהן כלולים בהעלם <span data-k=\"pg\">קסז</span> ּ השכל שבמוח בלתי מורגש[ים] כ\"כ [כ]הרגש התפעלות אוי\"ר שבלב (גם יוכל להיות הרגש התפעלות שכלולים בחו\"ב<sup data-n=\"6360\">866</sup> יותר ממדות שבלב כידוע בענין דו\"ר שכליים בהתפעלות ההשגה [ה]אלקי' בתפלה וגם בבחי' הקטנות דאוי\"ר שיחייב השכל רק שאינן ניכרים [כלל] כו'), וגם בעומק המושכל לעצמו יש מדות [ד]חו\"ג בהעלם ואח\"כ יוצאים [ל]גילוי להטות בשכל לחסד או לדין <sup data-n=\"6361\">867</sup>וגם מי שטבע כח שכלו מטה תמיד לדין או לחסד כו' הרי יש בו<sup data-n=\"6362\">868</sup> בעצם כח השכל מבחי' המדות חו\"ג כו'). וכן המח' במדות שבלב הרי יש מהות המח' שחושב באותיות המחשבה שנק' הרהור הלב<sup data-n=\"6363\">869</sup> במדות אוי\"ר שבלב ונק' הרהור הלב [רק] שהוא בהעלם בלב ויוצא לגילוי במח' שבמוח וכפי אופן הרהור הלב כך הוא אופן הרהור המח' במוח (ויש להיפוך שמהרהר במוח תחלה ויצא<sup data-n=\"6364\">870</sup> להתגלות בלב, ובפרט היראה שהתחלתה במוח ומסתיים בלב והאהבה התחלתה בהרהור הלב<sup data-n=\"6365\">871</sup> ומושך את המח' להרהר במוח לפי שהאהבה היא המשכת הלב והיראה באה במוח תחלה כו'). והוא<sup data-n=\"6366\">872</sup> מן החלומות שהן מעין הרהורי לב<sup data-n=\"6367\">873</sup> דוקא לפי שהחלומות הן בדמיונות שבמח' שנמשכים אחר הרהורי לבו כו'). וכמו\"כ מן המח' אל הדבור הרי אותיות הדבור עצמן המה כלולים במח' תחלה כשחושב לדבר רק שבאים בגילוי אותיות הדבור (וכן במעשה שעושה כפי הציור שחשב לעשות כן ידבר ויעשה). אבל בבחי' התכללות השכל בלמעלה מן השכל הרי א\"א לומר שאותיות<sup data-n=\"6368\">874</sup> גילוי אור השכל וסברא ממש כמו שהוא במהות[ה] כך [הוא] נמצא בכח השכל הנק' משכיל, וגם לא בבחי' [ה]העלם והתכללות כמדות בשכל ומח' במדות הנ\"ל, שהרי בכח המשכיל ההיולי לא יתכן שם לומר שיש בו ממהות וסוג שכל וסברא רק הוא כח המשכיל כל שכל",[["6357","863","<b>וכלל מקרא</b>: שם: וכך מורה."],["6358","864","<b>כנ\"ל</b>: שם: ליתא."],["6359","865","<b>למוד\"מ</b>: שם: למו\"ד."],["6360","866","<b>שכלולים בחו\"ב</b>: יב: שכליים לחו\"ג."],["6361","867","<b>וגם</b>: אוצ\"ל (וגם."],["6362","868","<b>בו</b>: ביד: ליתא."],["6363","869","<b>הלב</b>: שם: ליתא."],["6364","870","<b>ויצא</b>: שם: ויב[ו]א."],["6365","871","<b>היראה שהתחלתה במוח. . והאהבה. . הלב</b>: ראה גם ש\"א ה, ב ובהערה 39."],["6366","872","<b>והוא</b>: ביד: וראי'. ואוצ\"ל: (וראי'."],["6367","873","<b>החלומות. . הרהורי לב</b>: נסמן לעיל פ' שמות לח, א."],["6368","874","<b>שאותיות</b>: ביד: שאותו."]]],[2300541006,"וחכ' [ו]הוא עצמו מושלל מכל מציאות שכל בפרט רק כולל כל מיני שכליי' שיש בכחו לחדש ולהוליד, כענין כח המוליד שבנפש האדם להוליד ולד טרם שנמשך כחו להוליד, או כמו כח הצומח ההיולי שיש בכחו להצמיח כל צמח כו' (והיינו מ\"ש מאין ליש<sup data-n=\"6369\">875</sup>, הגם שהצמיחה והתולדה טבעי' היא בהכרח שיוליד בדומה לו ממש ודרך<sup data-n=\"6370\">876</sup> יחוס וערך לנולד ונצמח עם כח המוליד ומצמיח, זהו בשעה שנמשך כחו להוליד [ולהצמיח מרוחניות אל הגשמיות, וגם זה אינו כמו כח השכל ההיולי כאשר נמשך כחו להוליד] שכל חדש כנ\"ל ששכל זה הי' בכח השכל המולידו בהעלם ויצא לגילוי כנ\"ל, וגם נק' יש מאי\"ן היינו רק מבחי' אי\"ן והעלם לגילוי יש כנ\"ל, אבל מאי\"ן ממש שלא הי' תחלה במציאות שלו כלל אפי' בהעלם [זהו] כמו בבחי' התולדה והצמיחה מכח הצומח גם בשעה שנמשך כחו להצמיח ולהוליד, וכ\"ש טרם שנמשך כחו להצמיח ולהוליד שכלול בו כח זה להצמיח ולהוליד שהוא בבחי' אין ממש מושלל מהיות גם מקור משפיע מהעלם לגילוי, והוא כמו עצם כח המשכיל ההיולי טרם שנמשך ממנו כח להוליד שכל, הגם שבהכרח שיוליד שכל דוקא ולא דבר אחר זולתו, עכ\"ז א\"א לומר בו שיש [בו] ממהות וסוג שכל כמו שא\"א לומר בעשב הצומח [מכח הצומח] הרוחני שיש בכח הצומח ההיולי ממהות עשב, וכה\"ג בולד הנמשך מכח <span data-k=\"pg\">336</span> ּ המוליד שבטיפה א\"א לומר שיש [מ]סוג וערך הולד בכח המוליד ההיולי [רק בכח הנמשך להוליד שם יש בהעלם גדול כל כחות איברי הולד] כידוע. וגם זה שנמשך מכח הצומח וכח המוליד להצמיח ולהוליד יש בו חילוקים שונים, דתולדות החי יותר הוא בבחי' יש מאי\"ן מכח הצומח להצמיח, ותולדות המדבר למעלה מן החי כו'. וזה נראה גם באדם שכלול מדצח\"מ בגידול אברי[ו] ושערו וצפרני[ו] עד גידול המוחי' שבו כמשי\"ת).\n<b>ואמנם</b> גם זה שהתהוות שכל מכח המשכיל ההיולי נק' יש מאי\"ן ממש כנ\"ל אין לו ערך [א'] עם התהוות התולדה מכח המוליד להיות בא בבחי' הגשמה יותר זה מורה על היות בא מן העצמיות יותר שהרי יוליד נפש שלימה בר שכל בדומה לו ולא שכל לבד רק כל ציור קומת אדם משא\"כ [מ]כח המשכיל ההיולי לא נמשך רק שכל כו', וגם זה אינו בהכרח שא\"כ היו הכל חכמים כמו שמכח הצומח יצמיח בהכרח עשבים כו', אלא ה[ו]א כמו כח הדבור שנק' רוח ממל[ל]א נפש המדברת שי[ו]צא מכח ההיולי הזה לדבר בצירופי אותיות וכן כח המחשבה לחשוב כו', וטרם שבא ונמשך כח הדבור כלול הוא בעצם הנפש ממש, וא\"א לומר שיש מציאות דבור בכח הדבור שכלול בנפש שנק' רוח ממללא וכן בכח המח' שכלולה בעצם הנפש א\"א לומר שיש שם מהות וסוג מח' שהרי הנפש הוא אור פשוט לגמרי (אך ורק בשעה שנמשך כח המח' ודבור הכלולים ממו\"ד בהעלם), עדיין",[["6369","875","<b>מ\"ש מאין ליש</b>: שם: יש מאי\"ן ממש. ואוצ\"ל: ממש)."],["6370","876","<b>ממש ודרך</b>: שם: ויש."]]],[2300541011,"אין בנפש מו\"ד אפי' בהעלם רק שבכלי הגוף באים בגילוי מציאות מח' במוח ודבור בפה, א\"כ הרי לא בא [זה] בדרך העלם וגילוי כלל כמו בשכל ומדות המשתלשל[י'] מזה לזה כנ\"ל, רק בחי' המשכה זו באה בדרך דילוג וריחוק גדול מאד, כך הוא מכח המשכיל ההיולי מתהווה השכל שנק' מאי\"ן ליש [הוא מאי\"ן ממש] כי כח המשכיל הזה ההיולי כלול בעצם הנפש ונק' נפש השכלי'<sup data-n=\"6371\">877</sup> ע\"ש כח השכל הכלול בה כידוע כמו שנק' נפש המדברת<sup data-n=\"6372\">878</sup> כו', וכל הכחות הכלולים בנפש הן פשוטים בתכלית וע\"כ כאשר מתגלה כחן בכלי הגוף כשכל ומח' במוח הוא בא בדרך דילוג גדול שלא בבחי' עו\"ע כלל שהעלול הי' כלול תחלה בעילתו ו[ב]מציאות חכ' ומו\"ד וכה\"ג א\"א לומר שהיו כלולים תחלה כנ\"ל (משא\"כ התהוות השכל השופע שנק' מקור המשפיע מן ההעלם לגילוי לבד שהי' השכל כלול בהעלם במקור זה המשכילו ומולידו כו').\n<b>ונמצא</b> יש כאן ד' חילוקי' א' כח המוליד<sup data-n=\"6373\">879</sup> ההיולי שכלול הוא בעצם הנפש, וב' כח השכל ההיולי, וג' כח המו\"ד<sup data-n=\"6374\">880</sup> ההיולי, וד' כח השכל ומו\"ד בשעה שנמשך לבא לגילוי כו' כנ\"ל). ואח\"כ<sup data-n=\"6375\">881</sup> יתורץ ענין ההפרש בין יש מיש ליש מאי\"ן דהגם שיש מאי\"ן גם הוא בא בדרך העלם וגילוי כנ\"ל זהו רק כמו [ב]כח השכל בשעה שמשפיע וממשיך השכל לגילוי כנ\"ל, ועכ\"ז נק' יש מאין לגבי התהוות המדות מן השכל והדבור מן המח' שהוא יש מיש ממש, וכן כח המו\"ד כשהן באים לגילוי נק' יש מאין, אבל לא נק' יש מאי\"ן ממש רק כמו התהוות השכל מכח המשכיל ההיולי ובפרט כמו התהוות התולדה מכח המוליד שבנפש שהוא מאי\"ן ממש כו'. אך עדיין יש להבין בכ\"ז דלפי המובן מכל הנ\"ל לכאורה אין הפרש בין חכ' למדות ומו\"ד רק מצד בחי' כח <sup data-n=\"6376\">882</sup>השכל המשכיל ההיולי שכלול הוא בעצם הנפש [ממש שא\"א לומר בו מציאות שכל גם בהעלם כנ\"ל, ומצד טעם זה הרי גם בשאר הכוחות זולת החכ' כשהם כלולים בעצם הנפש] כמו כח המדות <span data-k=\"pg\">קסח</span> ּ דחו\"ג כשהם כלולים בעצם הנפש ממש א\"א לומר שיש מציאות חו\"ג שם אפי' בהעלם כמו בכח השכל הכלול שם, וכן ג\"כ כח המו\"ד שהן כלולים בעצם הנפש ממש לא יתכן לומר בהם מציאות מו\"ד כלל. וא\"כ [מהו] ההפרש בכלל בין חכ' למדות ומו\"ד שהחכמה היא יש מאי\"ן ממש יותר מכח המדות ומו\"ד כו' והרי מצד [ה]השתלשלו' מזה לזה גם החכ' יש מיש כאשר נמשך מבחי'<sup data-n=\"6377\">883</sup> השכל להוליד שכל כמו המדות מן השכל ומו\"ד מן המדות כו'. ועוד יש להבין בעיקר הענין למה בכחות הכלולים בנפש<sup data-n=\"6378\">884</sup> לא יתכן שם לומר שישנם במציאות גם בהעלם יותר ממה שיש כח מציאות כל עלול בהתכללות בעילתו שיתכן בו",[["6371","877","<b>נפש השכלי'</b>: ראה זהר (רע\"מ) צו כט, ב. ת\"ז תס\"ט קד, א. ז\"ח (מדרש הנעלם) בראשית ו, ד. ט, א. אבן עזרא משלי יט, ב. בחיי בראשית א, יב. כז, כח. ועוד. פירוש המלות זרות לר\"ש אבן תיבון למו\"נ מערכת נפש. לעיל קא, ג. וש\"נ."],["6372","878","<b>נפש המדברת</b>: נסמן לעיל פא, ג."],["6373","879","<b>המוליד</b>: יד: המח'. וראה הערה הבאה."],["6374","880","<b>המו\"ד</b>: יד: המוליד. וראה הערה שלפנ\"ז."],["6375","881","<b>ואח\"כ</b>: ביד: ואחר כל זה."],["6376","882","<b>השכל</b>: שם: ליתא."],["6377","883","<b>מבחי'</b>: שם: מכח."],["6378","884","<b>בנפש</b>: ב: בעצם הנפש."]]],[2300541016,"לומר שישנו שם בהעלם דלכאורה כל הכחות נק' עלולים מן הנפש כשאר עו\"ע דמאי שנא כו' וד\"ל.\n<b>אך</b> יש להקדים לזה ענין א' והוא משארז\"ל<sup data-n=\"6379\">885</sup> מזל מחכים דאין זה מובן דלכאורה מה שייכות יש<sup data-n=\"6380\">886</sup> לחכמה עם המזל ודאי אם איש חכם הוא בטבע כלי מוח החכמה יחכים מצד עצם כח חכמתו ולימודו היטב <sup data-n=\"6381\">887</sup>היטב ביגיעה רבה ולמה יהי' תלוי תוס' וריבוי כח החכ' במזל דוקא, דאין החכ' דומה לברכה במעשה ידיו בגשמיו' שא' מזל מעשיר מצד שיוכל להיות הפסק<sup data-n=\"6382\">888</sup> וכליון במעשה ידיו או מניעת ריוח גם ביגיעתו ביותר ובהתחכמות יתירה וכמ\"ש לא לחכמים לחם<sup data-n=\"6383\">889</sup>, ואע\"פ שא' והחכמה תחיה בעליה<sup data-n=\"6384\">890</sup> לא הכרחי' הוא כידוע, משא\"כ הלימוד של החכ' במושכלות אם כלי מוחו מוכשר לכך למה לא [י]תחכם בלא מזל כו', ובפירוש גזר אומר יהיב חכ' לחכימין כו' ששייך בזה ענין ברכה מלמעלה דוקא כמו וה' נתן חכ' לשלמה וכן בלב כל חכם לב נתתי חכמה<sup data-n=\"6385\">891</sup> כו'. אך הענין הוא דמזל זה המחכים הוא כמו מזל המעשיר וכמו מזל מצמיח עשב וכמא' אין לך עשב<sup data-n=\"6386\">892</sup> שאין לו מזל כו', דגם ש[ה]עשב [י]צמיח מכח הצומח שבארץ ע\"פ טבע כח הצומח שמצמיח כל צמח אבל המזל הוא הנותן כח להגדיל גידול הצמיחה מכח הצמיחה עצמה<sup data-n=\"6387\">893</sup> וכמ\"ש מכה ואו' לו גדל כו', והוא כללות ענין הברכה בצמח תבואות שדה שיוסיף ברכה בכח הצומח להיות התפשטות רב מכח הצומח להצמיח במילוי וריבוי גדול, ולהיפך כאשר אצ\"ל<sup data-n=\"6388\">894</sup> הצלחה וברכה בהעדר התפשטות לא יצמח כו'. וכך הוא בענין מזל מחכים שהוא הכח הניתן ממזל העליון להיות תוס' כח רב בכח המשכיל ההיולי להצמיח ולהוליד חכמות והשכלות רב[ות] בכל מיני חכמה שיתן כח השכל בהן, שזהו ענין כח הברכה בגופו ומהותו של כח השכל ממש שירבה כחו ויגדל ביותר [וכמו מזל מעשיר] שנותן כח רב להצליח במעשה ידיו, ואעפ\"י שכלי כח שכלו מוכן יותר מכלי שכל של זולתו יוכל להיות שלא יהי' חכם כ\"כ כחבירו שניתן הברכה של החכמה בכלי כח שכלו מצד מזלו דוקא כמו שזה יצליח במעשה ידיו יותר מזולתו מצד מזלו דוקא כו' (וזהו שהמלאך גוזר ואומר<sup data-n=\"6389\">895</sup> על הטפה אם יהי' חכם או טפש<sup data-n=\"6390\">896</sup> עשיר או עני גבור או חלש כו' שזהו בחי' המזל הרוחני שבא ושופע על התולדה בהיותו בבטן אם יהי' חכם להשכיל בכח שכלו הרבה או להיפך שלא יוצלח לכל חכמה כלל כמו אם יהי' עשיר או עני כו'), והוא ענין הגידול של התינוק מנעוריו באופן ריבוי וגידול [כח] שכל[ו] זה כך וזה כך וכמ\"ש <span data-k=\"pg\">338</span> ּ אך בצלם יתהלך איש כנ\"ל, ויש אשר אינו מ[ו]צלח לחכמה גם ע\"י יגיעה רבה והוא מצד קוטן כח [כלי] שכלו ביותר כמו התינוק בקטנותו וחסירי הדעת בטבע תולדה, ויש שיהי' מסוגל לחכמה זאת ולא",[["6379","885","<b>משארז\"ל</b>: ביד: מה שא'."],["6380","886","<b>יש</b>: ביד: ליתא."],["6381","887","<b>היטב</b>: שם: ליתא."],["6382","888","<b>הפסק</b>: שם: הפסד."],["6383","889","<b>לא לחכמים לחם</b>: קהלת ט, יא."],["6384","890","<b>והחכמה תחיה בעליה</b>: נסמן לעיל פ' שמות ב, ב."],["6385","891","<b>בלב. . נתתי חכמה</b>: נסמן לעיל פ' וארא פג, ב."],["6386","892","<b>אין לך עשב</b>: נסמן לעיל ס, ב."],["6387","893","<b>הצמיחה עצמה</b>: ביד: הצומח עצמו."],["6388","894","<b>כאשר אצ\"ל</b>: ביד: כשאין."],["6389","895","<b>ואומר</b>: שם: ליתא."],["6390","896","<b>הטפה. . חכם או טפש</b>: ראה נדה טז, ב."]]],[2300541021,"לחכמה אחרת כמו לרפואה ולא לתכונה, ויש בעניני מו\"מ יש לו חכמה רבה ועמוקה ולא בלימוד[ים] כלל כו', ויש ששכלו מסוגל לחכמת האומנות דוקא וגם בזה יש כמה חילוקים גם במלאכה זו ולא<sup data-n=\"6391\">897</sup> במלאכה אחרת כו', וכ\"ז הוא רק כמה מיני גידול של החכמה אם בגידול [ד]קטנות אם בגידול [ד]גדלות כמו כי האדם עץ השדה יש עץ קטן וגדול כו' וכמה מינים שונים כו'. וכך הוא למעלה במקור כל שפע דחכמה הבאה למטה שנמשך [מ]מקור <sup data-n=\"6392\">898</sup>כל החכמה להיות כמה מיני חכ' שונ[ות] כמו חכמת הרפואה וחכמת התכונה וגם חכמת האומנות כו' כמ\"ש במ\"א שזה כענין ל\"ב נ\"ח שפי' נתי' הוא חלק הפרטי [ב]המשכת צנור שפע פרטי' להיות מציאות חכ' שלימה מיוחדת [כ]חכמת הרפואה וכה\"ג כו'. נמצא אחר<sup data-n=\"6393\">899</sup> הקדמה זאת יובן פי' הפשוט דהחכ' מאין תמצא כלומר שלא נודע מהיכן היא נמצא[ת כמציאה] זו שלא נודע ממי נפלה כך לא נודע מאין בא[ה] מציאות החכ' בעולם והוא מפני שהחכ' בעצם מקורה היא בבחי' אין ממש והוא מבחי' מזל העליון [ד]מזל מחכים כו' וכמו יהיב חכ' כו', וענין המזל שהוא הנותן כח גידול ועצם כח השכל הרי הוא בא בבחי' דילוג וריחוק גדול ממקור כח החכ' כו' וד\"ל.\n<b>ובזה</b> יובן ההפרש בין החכ' לשאר הכחות הנמצאים מעצם הנפש שהחכ' היא באה מלמעלה לעשות גידול בכח השכל שבעצם הנפש שהוא מאין ממש כנ\"ל א\"כ לא יתכן לומר שיש מציאות שכל אפי' בהעלם בכח השכל הכלול בנפש כמו שא\"א לומר שיש מציאות העשב בכח הצומח [כו'] [כ]נ\"ל, אבל שאר כחות הכלולים בנפש כמדות ומו\"ד עכ\"פ יש מציאותן ממש בנפש בהעלם ויוצא[ים] רק לגילוי כמו במדות ה[ח]י [ב]תולדת[ן] בבטן הם כלולים בנפש[, וכן] מו\"ד ואין [ענין] גידולם אח\"כ בנערות וגדלות רק שיוצאים יותר לגילוי מן ההעלם, משא\"כ גידול החכ' הוא ע\"י המזל [דוקא] שהוא יש מאין ממש כמו התולד[ה] של הנפש בעצם בכח<sup data-n=\"6394\">900</sup> המוליד כו' (וכמו שא' בני חיי [ומזוני] במזלא תליא<sup data-n=\"6395\">901</sup> דוקא), אבל המו\"ד ומדות אינם תלוים במזל כלל והכל שוים בהם מצד שהן נטועים כבר בנפש כנ\"ל וד\"ל (ועכ\"ז גם בשארי כחות שבהכרח הם נמצאים בהעלם בנפש אינו נק' העלם כמו העלם המחשבה לגבי גילוי הדבור, רק שהן כלולים בכח ההיולי עדיין בלתי מציאות כלל ולא נק' עלולים מן הנפש כשאר עו\"ע שהעלול יש במציאות[ו] בעילתו כו', ויתורץ הקושיא הב' דלעיל). וזהו שא' חכם או טפש עשיר או עני שכ\"ז למעלה [מ]עצם הנפש והוא בשרש מקור חוצבם ממזל העליון משא\"כ המדות ודו\"מ<sup data-n=\"6396\">902</sup>",[["6391","897","<b>ולא</b>: ביד: וזה."],["6392","898","<b>כל</b>: ביד: כח."],["6393","899","<b>נמצא אחר</b>: שם: ואחר."],["6394","900","<b>בעצם בכח</b>: שם: עצמה מכח."],["6395","901","<b>בני. . תליא</b>: ראה מוע\"ק כח, א. הנסמן לקמן פ' תצוה שיט, ג."],["6396","902","<b>ודו\"מ</b>: ביד: ומו\"ד."]]],[2300541026,"וכה\"ג, וכן בני חיי ומזוני במזל[א] תליא מטעם זה להיות י\"ש מאי\"ן ממש וד\"ל (אך [ב]פרטי גידול האדם שכלול מדצח\"מ בגידול אבריו צומח שבחי [ו]שערו וצפרניו צומחי' ממש שזהו כגידול עץ השדה, אבל גידול <span data-k=\"pg\">קסט</span> ּ המוחי' שבו הוא יותר יש מאין כפי' הנ\"ל בענין החכמה מאין תמצא, דאל\"כ היו הכל חכמים [בשוה] מאחר שכל נפש אדם הוא מתהווה מבחי' פני אדם שבמרכב' כו' ולא כגידול הצומח וחי<sup data-n=\"6397\">903</sup> שהכל שוים רק חלוקי' [ל]מיני' שונים כמ\"ש במ\"א ע\"פ וייצר<sup data-n=\"6398\">904</sup> כו'), כי הגידול [ד]חכמה בא[ה] מבחי' אין דמזל העליון שמקבל מפני אדם בחילוק מדריגות מקטנות לגדלות כו'.\n<b>והנה</b> אחר כל הנ\"ל יובן בדוגמא למעלה [ב]בחי' אור הח\"ע דאצי' דגם שכבר נאצל מציאת החכמה דאצי' מעצמות המאציל אין זה דומה לשאר האורות הנאצלים שהיו כלולים בעצם המאציל כמו שלהבת הקשורה בגחלת<sup data-n=\"6399\">905</sup> [ו]כמ\"ש אפיק<sup data-n=\"6400\">906</sup> כו' כמשל כח[ות] הנפש הכלולים [בה] בהעלם עכ\"פ, אבל החכמה מאין [ממש] תמצא כמשל המציאה כו' [ו]כנ\"ל בנקודת<sup data-n=\"6401\">907</sup> כח השכל שבא ע\"י מזל מחכים כו' שהוא בא בבחי' דילוג וריחוק הערך כו' כי לא היתה כלולה במקור אף בהעלם רק מבחי' אי\"ן ממש נמצא[ת] במציאת ריבוי כח [כו'], וא\"כ זהו כיניקת הולד חלב אמו שבא לו החיות מבחי' העלם וריחוק להיות עי\"ז חיזוק חומר המוחי' כו' וגידולו אח\"כ בחכמה ברוב ימים כו'. וכך הוא <sup data-n=\"6402\">908</sup>ממש דאור אבא יונק ממזל הח' דונוצר אותיות צנור כו' שיונק זה היינו לעשות בו כח הגידול ע\"י המזל דונוצר חסד דא\"א כענין מזל מחכים הנ\"ל (כמו פתח ר' פלוני שפתח הצנור<sup data-n=\"6403\">909</sup> שהוא מז\"ל החכ' דמזל ל' מפעיל<sup data-n=\"6404\">910</sup> שמפעיל כל כח החכמה כו' כנ\"ל), והוא ענין היניקה מבחי' שערות דהיינו כמו הצנור שמתצמצם בו השפע בהעלם גדול וכגידי הארץ כו', וכידוע שהחלל שבשער[ה]<sup data-n=\"6405\">911</sup> צר ומצומצם מאד לפי שכל השפע מעליון לתחתון שלא בהדרגה דעו\"ע אלא דרך דילוג הוא בא ע\"י ריחוק והבדלה (כמ\"ש במ\"א בענין השלג וקרח<sup data-n=\"6406\">912</sup> כשימס והי' למים שתחלתו הי' מים ונגלד ונעשה קרח [א]ו שלג וימס ויהי' מים בסוף כך הוא ירידת השפע מהרוחני דמקור החכ' להיות מציאות חכמה בגילוי [כו']<sup data-n=\"6407\">913</sup>, והוא ענין צי[נ]ור דיניקת שער[ה] כמו השערה הגשמי' שאינה רק צומח שבחי והוא הנמשך ממותרי המוחי'<sup data-n=\"6408\">914</sup> ששרשו יותר מפנימי' המוחי' ע\"כ יוצא בבחי' מותרות כמ\"ש במ\"א. וכך בהמשכה זו דמזל ונוצר הגם שבא דרך ריחוק ודילוג כנ\"ל שרשו מבחי'<sup data-n=\"6409\">915</sup> מו\"ס [דא\"א] דוקא (וראי' מבן ט' שראוי להוליד<sup data-n=\"6410\">916</sup> מצד שיש בו",[["6397","903","<b>הצומח וחי</b>: ביד: החי ו(ה)צומח."],["6398","904","<b>ע\"פ וייצר</b>: בראשית ב, ז. ראה תו\"ח בראשית יח, ד ואילך ובהערה 1."],["6399","905","<b>שלהבת הקשורה בגחלת</b>: ס\"י פ\"א, מ\"ז."],["6400","906","<b>אפיק</b>: ראה ת\"ז בהקדמה (יז, א)."],["6401","907","<b>בנקודת</b>: ביד: בגידול."],["6402","908","<b>ממש</b>: שם: מ\"ש."],["6403","909","<b>פתח. . שפתח הצנור</b>: נסמן לעיל פ' שמות יב, ב."],["6404","910","<b>דמזל ל' מפעיל</b>: ראה גם שערי אורה (לר\"י גיקטלייא) שער ג-ד ע' לז. לקמן פ' ויקהל שפז, ב. מאמרי אדה\"א דברים ח\"ד ע' א'קסט. וש\"נ."],["6405","911","<b>החלל שבשער[ה]</b>: ראה גם מאמרי אדה\"א בראשית ע' רנג. וש\"נ."],["6406","912","<b>השלג וקרח</b>: ראה גם סידור סג, סע\"ב ואילך. מאמרי אדה\"א ויקרא ח\"ב ע' תצה. וש\"נ."],["6407","913","[כו']: אוצ\"ל: [כו'])."],["6408","914","<b>השערה. . ממותרי המוחי'</b>: ראה מאמרי אדה\"א ויקרא ח\"ב ע' תשעח. וש\"נ. נ\"ך ס\"ע קעו ואילך. וש\"נ. תו\"ח ח\"ש קכג, סע\"ג ואילך."],["6409","915","<b>מבחי'</b>: ביד: בפנימי'."],["6410","916","<b>מבן ט' שראוי להוליד</b>: ראה נדה לב, ב. לקמן פ' בשלח רא, א. תצוה שעח, ב. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקסט־ <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670221\" data-slug=\"torat-chaim\" data-id=\"2300670221\">תו\"ח לך פג, א</a>־ שעה\"י קלג, א ובהנסמן בהנ\"ל."]]],[2300541031,"מותר[י] מוחי' דוקא כמ\"ש במ\"א), וע\"כ [יש] ביכולתו לגדל עצם [מציא'] החכ' מאי\"ן לי\"ש [כו' ו]בחי' ח\"ס הוא מה שיש שכל כלול בלמעלה מן השכל (כטעם לרצון שכלול בעצם הרצון כנ\"ל), ובחי' שערות הוא בא בשרשו מלמעלה מח\"ס עצמו אעפ\"י שאינו אלא צומח שבחי וח\"ס הוא חי שבמדבר כנ\"ל בענין כח השכל השופע שנק' שכל הנעלם מכ\"ר<sup data-n=\"6411\">917</sup> [או] ח\"ס ה[ר]י הוא כלול בכח המשכיל ההיולי שנק' מדבר נפש השכלי' בעצם [בטרם] שנק' משפיע מהעלם לגילוי, ולפי\"ז פי' ד[ה]חכמה מאין קאי דוקא על עצם המשכיל ההיולי שלמעלה משכל הנעלם שנק' ח\"ס חכ' שבכתר. ובכ\"ז יובן [ג\"כ] מ\"ש הכל תלוי במזל אפי' ס\"ת בהיכל שהן ב' מזלות דונוצר ונקה שרש הראשון דחו\"ב דאצי' כענין מזל מחכים כנ\"ל וד\"ל.",[["6411","917","<b>שכל הנעלם מכ\"ר</b>: נסמן לעיל פ' שמות מז, ג."]]],[2300540065,"<b>פרשת בשלח</b>\n<span data-k=\"pg\">340</span> ּ<b>ויהי</b> בשלח פרעה<sup data-n=\"6412\">1</sup> את העם ולא נחם [אלקים]<sup data-n=\"6413\">2</sup> כו', כתיב קדש ישראל לה'<sup data-n=\"6414\">3</sup> ראשית תבואתו<sup data-n=\"6415\">4</sup> הרי נק' ישראל בשם תבואתו של הקב\"ה [ו]כמ\"ש וזרעתי' לי בארץ<sup data-n=\"6416\">5</sup> כו' כמו הזורע תבואת השדה שדרך האדם לזרוע קב כדי להוציא כמה כורין<sup data-n=\"6417\">6</sup> כו', [ו]כן בנש\"י דכתיב וזרעתי' לי בארץ וזרעתי את בנ\"י<sup data-n=\"6418\">7</sup> כו' היינו למצוא בהם תוס' ברכה מרובה על העיקר הזריעה בכפלי כפלים כו'. והוא ענין הזריעה של אור הזרוע לצ\"ע כו' בכל גלות ישראל באוה\"ע שילדו בנים ובנות תחת אותו השר כמ\"ש ויתהלכו מגוי אל גוי<sup data-n=\"6419\">8</sup> כו', וכמו בגלות מצרים שיצאו ס\"ר ניצוצין<sup data-n=\"6420\">9</sup> שהן הי' ניצוצות דקדושה שנפלו בנהר נילוס<sup data-n=\"6421\">10</sup> כו' (כמ\"ש אל תירא מרדה מצרימה<sup data-n=\"6422\">11</sup> כי לגוי גדול אשימך שם, שם דוקא ולא בארץ כנען וכמ\"ש במ\"א) (בפ' שמות<sup data-n=\"6423\">12</sup> [באריכות]) (וכמ\"ש בזהר ע\"פ ויברך יעקב את פרעה<sup data-n=\"6424\">14</sup> כו' וכמ\"ש וישב ישראל ויאחזו בה<sup data-n=\"6425\">15</sup> דילהון אתחזי<sup data-n=\"6426\">13</sup> כו'). וכך הוא בכל גלות דכתיב צדקת פרזונו צדקה עשה ה' עם ישראל שפזרן<sup data-n=\"6427\">16</sup> בין אוה\"ע להוסיף עליהם גרים שהן הנש\"י<sup data-n=\"6428\">17</sup> שנולדים בכל דור ודור כו'. וזהו עיקר מעלת קיבוץ גליות שאור הזרוע נתברך<sup data-n=\"6429\">18</sup> ונתקבץ עד שיאמרו בגוים הגדיל ה' לעשות עם אלה<sup data-n=\"6430\">19</sup> כו' וכמא\"ר<sup data-n=\"6431\">20</sup> למעלה בפ' שמות בענין ד' נהרות<sup data-n=\"6432\">21</sup> דג\"ע כו'). והנה כתיב הלוך",[["6412","1","<b>ויהי בשלח פרעה</b>: מיוסד על ד\"ה זה הנחת כ\"ק אדה\"א שנדפסה במאמרי אדה\"ז תקס\"ב ח\"א ע' קמה [וקיצורים נדפסו שם ע' רצב. וראשי פרקים מהמאמר נמצאו שם בח\"ב ע' תקפ. ושם בע' תרפג ישנו ביאור להמאמר]. והנחה אחרת ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370274\" data-slug=\"torah-or\" data-id=\"3901370274\">תו\"א בשלח סא, א</a>. ועם הגהות וכו' ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316300353\" data-slug=\"or-hatorah-hb\" data-id=\"8316300353\">אוה\"ת</a> בשלח (כרך ז) ע' ב'תרנא. (כרך א) ע' שנג ואילך. ראה פלח הרמון שמות ע' קיח. ראה עוד ע\"ד המאמר וזמן אמירתו להלן ברשימת הכת\"י [ושם מפורט ג\"כ סימני האותיות הבאים להלן בהמראי מקומות]."],["6413","2","<b>ויהי בשלח. . [אלקים]</b>: בשלח יג, יז."],["6414","3","<b>קדש ישראל לה'</b>: ירמי' ב, ג."],["6415","4","<b>תבואתו</b>: אב: תבואתה. וכ\"ה בירמי' ובהדרושים שנסמנו בריש המאמר כאן. — ראה מאמרי אדה\"א שמות ח\"א ע' א ובהערה שם. אוה\"ת כאן (ע' ב'תרנא)."],["6416","5","<b>וזרעתי' לי בארץ</b>: הושע ב, כה."],["6417","6","<b>לזרוע קב. . כורין</b>: נסמן לעיל מ, ג."],["6418","7","<b>וזרעתי את בנ\"י </b>[אב: בית ישראל]: נסמן לעיל יד, א."],["6419","8","<b>ויתהלכו מגוי אל גוי</b>: ראה גם לעיל פ' שמות מ, ג. וש\"נ."],["6420","9","<b>שיצאו ס\"ר ניצוצין</b>: בא יב, לז."],["6421","10","<b>ס\"ר ניצוצין. . בנהר נילוס</b>: נסמן לעיל מ, ב הערה 141."],["6422","11","<b>אל תירא מרדה מצרימה</b>: ויגש מו, ג."],["6423","12","<b>בפ' שמות</b>: לעיל מ, ג."],["6424","14","<b>ויברך יעקב את פרעה</b>: ויגש מו, ז."],["6425","15","<b>וישב ישראל ויאחזו בה</b>: ויגש מז, כז [בדילוג]."],["6426","13","<b>וכמ\"ש בזהר. . דילהון אתחזי</b>: ראה זהר ס\"פ ויגש (ריא, ב). ביאוה\"ז שם קלה, ב ואילך."],["6427","16","<b>צדקת פרזונו. . שפזרן</b>: ס' שופטים ה, יא. ראה פסחים פז, ב."],["6428","17","<b>גרים שהן נש\"י </b>[א: נשמות]: ראה גם הנסמן לעיל מ, ג."],["6429","18","<b>נתברך</b>: אב: נתברר."],["6430","19","<b>שיאמרו בגוים. . אלה</b>: תהלים קכו, ב. ראה גם לעיל פ' שמות לז, א ואילך. מא, ב ואילך."],["6431","20","<b>וכמא\"ר</b>: א: (כמבואר."],["6432","21","<b>למעלה בפ' שמות בענין ד' נהרות</b>: ראה לעיל לט, ג ואילך."]]],[2300540103,"ילך ובכה<sup data-n=\"6433\">22</sup> נושא משך הזרע כו' עד\"מ הזריעה גשמיי' שילך הלוך ובכה נושא משך הזרע מפני היראה פן תרקב הזריעה בארץ לגמרי ולא תצמיח פרי תבואתו כלל, אך אדרבה יודע הזורע שעיקר הצומח<sup data-n=\"6434\">23</sup> באה [רק] ע\"י הרקבון הגרעין<sup data-n=\"6435\">24</sup> לגמרי בארץ תחלה אז דוקא יתלבש בה כח הצומח שבארץ ותצמיח חטים רבים בתוס' ברכה. כך הוא בענין הזריעה הרוחני' למעלה בבחי' אור הזרוע לצ\"ע שזהו משארז\"ל אין ב\"ד בא<sup data-n=\"6436\">25</sup> עד שיכלו נשמות מן האוצר ששמו גוף, והוא מה שאור הזרוע לצ\"ע שהוא מקור כל תולדות הנשמות עליונות שנמשך באוצר הנשמות ששמו גוף הוא בחי' מל'<sup data-n=\"6437\">26</sup> דאצי' שכל הנשמות וניצוץ מישראל מקור חוצבו בבטן מל' בבחי' עיבור והגאולה נק' לידה<sup data-n=\"6438\">27</sup> כו' כידוע, וכמארז\"ל ג' שותפין<sup data-n=\"6439\">28</sup> [באדם] הן אב ואם ממשיכים הנה\"ט החומרי וה' נותן בו נשמה וכמ\"ש ואתה נפחת בי<sup data-n=\"6440\">29</sup> כו', ומ\"ש אתה בראת יצרת<sup data-n=\"6441\">30</sup> כו' היינו למעלה באוצר הנשמות כו' מאור הזרוע לצ\"ע שנק' אב כמ\"ש כי אתה אבינו<sup data-n=\"6442\">31</sup> וכמ\"ש לכבודי בראתיו<sup data-n=\"6443\">32</sup> יצרתיו אף עשיתיו בגוף כו' כידוע וד\"ל.\n<b>והנה</b> ע\"ז אמר הלך ילך ובכה כו' מפני שהזורע אור הנשמות לבא למטה בלבוש גס דחומר הגופני ודאי יסתר אור",[["6433","22","<b>הלוך ילך ובכה</b>: תהלים קכו, ו. ראה גם לקמן רלא, ב. פ' תצוה שיט, א. שע\"ת סד, ב ואילך. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670198\" data-slug=\"torat-chaim\" data-id=\"2300670198\">תו\"ח בראשית ג, ד</a>. מאמרי אדה\"א ויקרא ח\"ב ע' תקסג."],["6434","23","<b>הצומח</b>: א: הצמיחה."],["6435","24","<b>הרקבון </b>[אב: רקבון]<b> הגרעין</b>: נסמן לעיל ב, ג."],["6436","25","<b>אין ב\"ד בא</b>: ראה ע\"ז ה, א וברש\"י ותוס' שם. הנסמן במאמרי אדה\"א בראשית ע' ק. שה\"א צח, א ובהנסמן במ\"מ לשם."],["6437","26","<b>באוצר הנשמות. . מל'</b>: נסמן לעיל פ' וארא סז, א."],["6438","27","<b>והגאולה נק' לידה</b>: נסמן לעיל יז, ג."],["6439","28","<b>ג' שותפין</b>: ראה נדה לא, א. מאמרי אדה\"א דברים ח\"ב ע' תקנ. ח\"ד ע' א'רז. קונטרסים ע' קו. הנחות תקע\"ז ע' רעח."],["6440","29","<b>ואתה נפחת בי</b>: ברכות ס, ב. ברכת אלקי נשמה. הנסמן לעיל עג, ד."],["6441","30","<b>אתה בראת יצרת</b>: בברכת אלקי נשמה [בדילוג]."],["6442","31","<b>כי אתה אבינו</b>: ישעי' סג, טז."],["6443","32","<b>לכבודי בראתיו</b>: ישעי' מג, ז [ושם: ולכבודי — ראה לקמן פ' ויקהל שפט, א. הנסמן במאמרי אדה\"א קונטרסים ע' שסח. שע\"ת קו, ד]."]]],[2300540141,"האלקי [ב]נשמ[ות] לגמרי מצד חומר הגס הגופני המכסה על אור האלקי לגמרי כמו חטה הזרוע בארץ שיכסה עלי' העפר עד שתרקב לגמרי כו', כך הרי יחשך ויורקב רוחני' אור החיות דנשמה האלקי' מחמת רוח הבהמה שהן תאוות חומריות הגופני' כמו בכל דבר חיות גשמי' כמאכל ומשתה ושאר תענוגי עוה\"ז, וגם יצר לב האדם רע מנעוריו לרדוף אחרי כל תאוה רעה ביותר מן הבהמה כידוע עד שלבו אטום וקשה כאבן לבלתי <span data-k=\"pg\">קע</span> ּ יתעורר ברוח התעוררות תשובה כלל וישכח על [ה'] עושיהו לגמרי כו', לפי שאור נשמתו ורוחו האלקי נחשך לגמרי, כמו עד\"מ אור הנר באויר מעופש בבור עמוק שיכבה לגמרי, וכרקבון החיות רוחני שבחטה בעפר הארץ כו'. וכ\"ש בסיבת טרדת הנפש בעומק ההתקשרות בהבלי עוה\"ז כמו בעסק פרנסה לחיות [כ]חיי גוים ממש שהוא נמשך ע\"י גלגל המזלות דק\"נ שהוא לבושי הטבע שהוא מבחי' פסולת ושמרי דאופנים<sup data-n=\"6444\">33</sup> כו'. ובאמת הרי א' דאין מזל לישראל<sup data-n=\"6445\">34</sup>, וע\"כ גזרו אומר דישראל שבחו\"ל עובדי ע\"ז בטהרה<sup data-n=\"6446\">35</sup> כמ\"ש אותי עזבו מקור מים חיים לחצוב להם בורות<sup data-n=\"6447\">36</sup> נשברים כו' שהן שלוחי השפע הגשמי' [ו]הפרנסה (ודוקא בחו\"ל שהשכינה בגלות<sup data-n=\"6448\">37</sup> שם בע\"ש<sup data-n=\"6449\">38</sup> דנוגה<sup data-n=\"6450\">39</sup> דק\"נ כמ\"ש ושק אשים כסותם<sup data-n=\"6451\">40</sup> ). ולזאת רבים מאורות וניצוצות הקדושה הנזרעים בגופים שילכו לאיבוד ממש כמו נפשות רשעים שמתו בלא תשובה ומע\"ט וכמו נבלע ישראל בגוים<sup data-n=\"6452\">41</sup> כו' וכמו ויאכלו<sup data-n=\"6453\">47</sup> ישראל<sup data-n=\"6454\">43</sup> כל אוכליו יאשמו<sup data-n=\"6455\">44</sup> כו' וכתי' חיל בלע ויקיאנו<sup data-n=\"6456\">45</sup> כו' והוצאת את בלעו מפיו<sup data-n=\"6457\">46</sup> כו' וכן מ\"ש<sup data-n=\"6458\">42</sup> ויאכלו [את] ישראל בגוים<sup data-n=\"6459\">48</sup> כו' וכמו ויחוגו וינועו<sup data-n=\"6460\">49</sup> כו' וכל חכמתם תתבלע כידוע שכורת<sup data-n=\"6461\">*50</sup> ולא מיין<sup data-n=\"6462\">50</sup> כו', עד שיגיע[ו] לשערי מות<sup data-n=\"6463\">51</sup> דקליפה שכל אוכל דחכ' תתעב נפשם<sup data-n=\"6464\">52</sup> כחולה המסוכן בגשמי' (וכפרות הרעות שבלעו לפרות הטובות ומראיהן רע<sup data-n=\"6465\">53</sup> כאשר בתחלה כמ\"ש במ\"א), וז\"ש כי בלעונו אדוני' זולתיך<sup data-n=\"6466\">54</sup> כו' וד\"ל.\n<b>אך</b> [הנה] עכ\"ז אמר בא יבא ברינה<sup data-n=\"6467\">55</sup> נושא אלומותיו, שאחר הזריעה דאור צ\"ע בגופי' בכל גליות לא הני\"ח לעשק\"ם<sup data-n=\"6468\">56</sup> ויוכ\"ח עליהם מלכים כו' אל תגעו במשיחי<sup data-n=\"6469\">57</sup> כו' וכמ\"ש וחשב מחשבות<sup data-n=\"6470\">58</sup> לבלתי ידח ממנו נדח אפי' ניצוץ היותר קטן וקל שבקלים יעשה תשובה ויצמיח ועושה פרי למעלה כו', והוא מ\"ש",[["6444","33","<b>המזלות. . ושמרי דאופנים</b>: נסמן לעיל ס, ב ואילך."],["6445","34","<b>דאין מזל לישראל</b>: נסמן לעיל ב, א."],["6446","35","<b>דישראל שבחו\"ל עובדי ע\"ז בטהרה</b>: נסמן לעיל לח, א."],["6447","36","<b>אותי עזבו. . בורות</b>: נסמן לעיל ב, א."],["6448","37","<b>בחו\"ל שהשכינה בגלות</b>: ראה גם לעיל פ' וארא עג, ד. וש\"נ."],["6449","38","<b>בע\"ש</b>: נסמן לעיל לז, ג."],["6450","39","<b>דנוגה</b>: אב: ליתא."],["6451","40","<b>ושק אשים כסותם</b>: ישעי' נ, ג."],["6452","41","<b>נבלע ישראל בגוים</b>: הושע ח, ח [בדילוג — ראה לקמן קלו, א. מאמרי אדה\"א בראשית ע' ש. וש\"נ. שה\"א ו, א ובהערה 2]."],["6453","47","<b>ויאכלו [את] ישראל</b>: ישעי' ט, יא."],["6454","43","<b>ויאכלו ישראל</b>: אולי תיבות אלו מיותרות, ראה בשורה שלאח\"ז בפנים."],["6455","44","<b>כל אוכליו יאשמו</b>: המשך הכתוב קדש ישראל לה' (ירמי' ב, ג)."],["6456","45","<b>חיל בלע ויקיאנו</b>: נסמן לעיל פ' שמות מ, ג."],["6457","46","<b>והוצאת את בלעו מפיו</b>: ירמי' נא, מד [שם: והצאתי — ראה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680412\" data-slug=\"torat-chaim\" data-id=\"2300680412\">תו\"ח תולדות קנז, ב</a>]."],["6458","42","<b>ויאכלו. . מ\"ש</b>: אב: ליתא. וראה להלן הערה 59."],["6459","48","<b>בגוים</b>: אב: ליתא."],["6460","49","<b>ויחוגו </b>[אב: יחוגו]<b> וינועו</b>: תהלים קז, כז."],["6461","*50","<b>כידוע שכורת</b>: ב: כמ\"ש ושכורת."],["6462","50","<b>שכורת ולא מיין</b>: ישעי' נא, כא. ראה גם מאמרי אדה\"א דברים ח\"ב ע' תקכ. וש\"נ. נ\"ך ע' רג. וש\"נ. קונטרסים ע' לט."],["6463","51","<b>שיגיע[ו] לשערי מות</b>: תהלים קז, יח."],["6464","52","<b>שכל אוכל. . תתעב נפשם</b>: התחלת הכתוב שיגיע[ו]."],["6465","53","<b>וכפרות הרעות. . ומראיהן רע</b>: מקץ מא, כא. ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370146\" data-slug=\"torah-or\" data-id=\"3901370146\">תו\"א מקץ לא, סע\"ב</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370150\" data-slug=\"torah-or\" data-id=\"3901370150\">לב, ב</a>. שה\"א ו, רע\"א ובהערה 1."],["6466","54","<b>כי בלעונו אדוני' זולתיך</b>: ראה גם תו\"ח מקץ ובהערה 52. לקמן קלו, א."],["6467","55","<b>בא יבא ברינה</b>: המשך הכתוב הלך ילך ובכה (שבהערה 22)."],["6468","56","<b>לא הני\"ח לעשק\"ם</b>: נסמן לעיל מ, ג."],["6469","57","<b>אל תגעו במשיחי</b>: תהלים קה, טו. דהי\"א טז, כב."],["6470","58","<b>וחשב מחשבות</b>: שמואל-ב יד, יד."]]],[2300540178,"קדש ישראל להוי'<sup data-n=\"6471\">59</sup> ראשית תבואתו פי' לא די שלא נבלע ישראל בע\"ש דגוים אלא הוציא מהם ברכה בכפליים לאלפים ו[ל]רבבות פעמים מן גוף אור הזרוע עד שנק' ראשית תבואתו וכמ\"ש אז יאמרו בגוים הגדיל ה' לעשות עם אלה. וז\"ש בא יבא ברינה נושא אלומותיו והוא כאשר הצליח פרי תבואתו ברוב ברכה מרובה כו', והענין הוא בהיות שאע\"פ שבודאי ע\"י טרדת עומק הלב ונפש בפרנסה שוכח אדם על ה' לעבדו עד שלא יתעורר כלל <sup data-n=\"6472\">60</sup>כו', נרדם ו[כ]שכורת ולא מיין כו', ומצד ריבוי המסכים והעלמות מן העוונות שדש בעקבי'<sup data-n=\"6473\">61</sup> נעשה כמו מחיצה של ברזל<sup data-n=\"6474\">62</sup> להפסיק בינו לבין אביו שבשמים כו' שזהו כמו עפר המכסה כו', עכ\"ז אדרבה עי\"ז הרי יבא לכלל מרירות ושפלות גדולה בנפש אחר שיתבונן בעוצם ריחוקו מה' אחד כו' ויבא לכלל התעוררות תשובה בלב נשבר ונדכה מאד מתוך שרואה א\"ע בחושך והסתר אור האלקי לגמרי שזהו כמו רקבון הגרעין (בל\"א ער פולט באיי זיך זייער), ואחר דוחק הפרנסה [ש]בנפשו ממש יביא לחמו<sup data-n=\"6475\">63</sup> וטרף מזונו ורקבון אור נשמתו בשפלות ומרירות עצומה יתעורר לעבוד את ה' בתפלה בעבודה [שבלב] בשפלות והכנעה גדולה ביותר למס\"נ בא'<sup data-n=\"6476\">64</sup>, וכן במעשה המצוה ולימוד תו' ופיזור צדקה וכה\"ג, <span data-k=\"pg\">342</span> ּ אז עי\"ז דוקא יגדל אור גילוי אלקי במאד מאד בנשמתו הרבה יותר מכמו שהי' בה גילוי אור האלקי בהיותה למעלה צרורה בצרור החיים כו' קודם שירדה בגוף גשמי, והוא כמו החטה שנרקב בארץ שאז דוקא יתלבש בה כח הצומח להצמיח בה בתוס' ברכה כנ\"ל, כך ע\"י רקבון רוחני הנ\"ל שבניצוץ האלקי מדוחק טרדת הפרנסה והסתר חומר הגופני כנ\"ל יגדל בה כח הצומח האלקי להיות בה גילוי אור האלקי בתוס' ברכה והמשכה בכפלי כפליים כו', והוא שנתרבה ונתגדל אור הנשמה לעשות פרי למעלה מעלה [ע\"י] אוי\"ר ותומ\"צ כמו שיגדל ויצמח החטה בפרי תבואות הרבה כו'. ולזה נק' כנ\"י בגלות ראשית תבואתו כתבואה שגדלה יותר מן הזריעה בכפלי כפליים כו', והוא הטעם שנזרעו נש\"י בגלות בשביל תוס' אור רב בגילוי אלקו' וכמשל הנ\"ל בזורע קב כדי להוציא כמה כורין, וז\"ש וזרעתי כו' שז\"ש בא יבא ברינה נושא אלומותיו שהן פרי דמע\"ט דכנס\"י בהיותם זרועים בגלות דוקא, וז\"ש אז יאמרו בגוים דוקא הגדיל ה' לעשות עם אלה כו' וכמ\"ש קדש ישראל לה' כל אוכליו יאשמו כו'.",[["6471","59","<b>להוי'</b>: אב: ניתוסף: כל אוכליו יאשמו כו' (וכתיב חיל בלע ויקיאנו כו' והוצאת את בלעו מפיו כו'). [ב: מציין אות ב] וכן מ\"ש קדש ישראל לה'. וראה לעיל הערה 42."],["6472","60","<b>כו'</b>: אב: כמו."],["6473","61","<b>העוונות שדש בעקבי'</b>: נסמן לעיל פ' וארא עד, ד."],["6474","62","<b>מחיצה של ברזל</b>: ע\"פ פסחים פה, ב. ראה גם ברכות לב, ב וברש\"י שם. אוה\"ת תצוה ע' א'תרצא."],["6475","63","<b>[ש]בנפשו. . יביא לחמו</b>: ע\"פ פיוט (לימים נוראים) כי כשמך."],["6476","64","<b>למס\"נ בא'</b>: נסמן לעיל פ' וארא עז, א."]]],[2300540215,"<b>וז\"ש</b> והייתם ברכה בקרב הארץ<sup data-n=\"6477\">65</sup> כו', פי' ברכה הוא ההמשכה והשפע שנוסף על העצם בכפלי כפליים כמו הברכה גשמי' במעשה ידיו של אדם כו', כך ע\"י ישראל נתברך שם הוי' בקרב הארץ בחי' עלמא דאתגלייא שהוא העוה\"ז בה' בראם<sup data-n=\"6478\">66</sup> כו', שלזה נק' ישראל זרע ברוכי ה'<sup data-n=\"6479\">67</sup> כו', וכמ\"ש ברוך הוי' אלקי ישראל<sup data-n=\"6480\">68</sup> דוקא מן העולם ועד העולם, פי' מעלמא דאתכסיי' לעלמא דאתגלייא כידוע. והענין הוא דהעולם האצי' בכלל נק' עלמא דאתכסיא בבחי' ההעלם ומקיף [ש]אורות עליונים דאצי' [באים] בצמצום דקו המדה באו\"כ, כדי שימשיך האור האלקי בריבוי כלים מכלים שונים במיעוט אחר מיעוט לבא בהשתלשלו' רבות אור ושפע ג' עולמות דבי\"ע עד צמצום האחרון ביותר בסוף עולם העשי' שהוא העוה\"ז השפל כו' שכל זה בא דרך עו\"ע במדה וצמצום. אבל ע\"י ישראל בתומ\"צ ואוי\"ר ותשובה וצדקה בעוה\"ז דוקא הן מגלין אור הוי' בתורתם ועבודתם בעוה\"ז הרבה יותר מכפי המדה וצמצום הקצוב בעולם העשי' לפי אופן ההשתלשלו' דעו\"ע כו', עד שנק' ברכה בקרב הארץ ובתוס' אור רב הרבה מכמו שנמדד האור באצי' כו'. וזהו ברוך ה' ממש מן העולם כו', ולכך נק' ישראל ברוכי ה' ממש וכמו שא' בזהר איהו ברוך ואיהי ברכה<sup data-n=\"6481\">69</sup>, כי כנס\"י נק' בשם ברכה שהן כלי המחזיק הברכה דשם הוי' כמו ע\"י מצות ת\"ת א' למען תהי' תורת ה' בפיך<sup data-n=\"6482\">70</sup> וכן בצדקה וכה\"ג, וכ\"ז ע\"י הזריעה שגורמת הצמיחה בתוס' רב שלא הי' כח זה כ\"כ כמו<sup data-n=\"6483\">71</sup> בנש\"י כמו שהי' למעלה ממש טרם שירדו בגופים בעוה\"ז כנ\"ל במשל הזורע חטה בארץ שע\"י הרקבון בארץ מתלבש בה כח הצומח להצמיח ממנה חטים רבות בכפלי כפליים כו'. כך גם שכנס\"י נק' תבואתו גם טרם שירדו למטה אבל לא הי' בהן תוס' כלל, משא\"כ כשנזרעו למטה ניתוסף עי\"ז ברכה <span data-k=\"pg\">קעא</span> ּ רבה בגילוי אור האלקי בתו\"מ כתבואת השדה הנזרע שניתוסף מקב א' כמה כורין, משא\"כ מקודם שנזרעו שלא הי' נוסף כלום מכמו שהוא כו' וד\"ל. וז\"ש והייתם ברכה בקרב הארץ דוקא ולא קודם שירדו למטה בעוה\"ז וד\"ל. אך הנה י\"ל שרש וטעם לענין זה שהחטה הזרוע בארץ תצמיח בריבוי גדול שאין זה מצד עצמה כלל כ\"א מצד כח הצומח שבארץ שמתלבש בה כנ\"ל ומאין יש [זה] בכח הצומח שבארץ להצמיח כ\"כ בריבוי שזהו חידוש גמור כו', וא\"כ גם בנמשל מזה באור הזרוע לצ\"ע בנש\"י בגופי' בעוה\"ז מאין יש כח הגדול הזה בעפר דק\"נ כו'",[["6477","65","<b>והייתם ברכה בקרב הארץ</b>: חיבור שני כתובים זכרי' ח, יג. ישעי' יט, כד. ראה הנסמן במאמרי אדה\"א דברים ח\"א ע' קכג. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680071\" data-slug=\"torat-chaim\" data-id=\"2300680071\">תו\"ח ויחי רמ, ב</a>."],["6478","66","<b>בה' בראם</b>: בראשית ב, ד. ראה מנחות כט, ב. ב\"ר פי\"ב, ב."],["6479","67","<b>זרע ברוכי ה'</b>: ישעי' סה, כג."],["6480","68","<b>ברוך הוי' אלקי ישראל</b>: נסמן לעיל פ' שמות יח, ג."],["6481","69","<b>איהו ברוך ואיהי ברכה</b>: זהר תרומה קסב, א. (רע\"מ) ואתחנן רסד, ב. ראה גם מאמרי אדה\"א דברים ח\"א ס\"ע קכג ואילך."],["6482","70","<b>למען תהי' תורת ה' בפיך</b>: בא יג, ט."],["6483","71","<b>כמו</b>: א: ליתא."]]],[2300540247,"להצמיח בחי' תוס' גילוי<sup data-n=\"6484\">72</sup> אור גילוי אלקו' בברכת שם הוי' שהוא המשכת גילוי אלקו' מאד הרבה יותר מכפי אור אלקי הזרוע בתחלה כנ\"ל.\n(ב) <b>והנה</b> יש להקדים לזה עוד ענין א' שיש להפלא מאד והוא מארז\"ל בענין יו\"ד דורות שמאדה\"ר<sup data-n=\"6485\">73</sup> עד נח כו' להודיע כמה ארך אפיים לפניו כו' וכן במעשה<sup data-n=\"6486\">74</sup> דר\"א<sup data-n=\"6487\">75</sup> ור\"י ור\"ע כשראו כרך גדול דרומי<sup data-n=\"6488\">76</sup> כו' ששחק ר\"ע וא' אם לעוברי רצונו כך לעושי רצונו עאכו\"כ, וי\"ל מה שא' לו<sup data-n=\"6489\">*78</sup> ארך אפים שהוא מה שמאריך אף לרשעים<sup data-n=\"6490\">77</sup> כמו לצדיקי' בשוה כו', דהנה באמת אנו רואים מדה זו דארך אפים שהוא למעלה הרבה מבחי'<sup data-n=\"6491\">78</sup> היושר והדין והוא כמו בדורו של אנוש שהיו רובם עובדי ע\"ז וכו\"מ וניזונים היו בחסדו<sup data-n=\"6492\">79</sup> ברוב שפע רבה ויתירה כו', וכך בכל דורות שעד נח, וכן [גם] בכל דורות הראשונים ואחרונים כמו בחורבן בית ראשון ושני עד דור האחרון הזה אנו רואים שנמשך רוב שפע וברכה לאוה\"ע בלא חשבון ודקדוק כלל דהיינו שמלאים מכל שפע טוב עוה\"ז הגם שחוטאין מאד וירעו וישחיתו מאד בדרכיהם כמו בגזל וש\"ד וע\"ז כו' שנצטוו ב\"נ והם עובדים<sup data-n=\"6493\">80</sup> ועכ\"ז לא נמנע מהם השפע וברכה כלל, וכמו דור אנוש שהיו עובדי ע\"ז שנצטוו ב\"נ על ע\"ז והיו ניזונים ברוב שפע יתירה כו' (והגם שדור המבול נענש[ו], וכן בכל דור ודור עונשים לכל גוי וגוי אשר ישחיתו דרכיהם כמו סדום ועמורה שחטאו ביותר ונהפכו<sup data-n=\"6494\">81</sup>, וכן א' כי לא שלם עון האמורי<sup data-n=\"6495\">82</sup> עד הנה כו', הרי במשפט מביא כל גוי על מעשיהם וכמ\"ש השופט כל הארץ<sup data-n=\"6496\">83</sup> כו' וכתי' מלך אלקי' על גוים<sup data-n=\"6497\">84</sup> כו' כי אלקי' שופט<sup data-n=\"6498\">85</sup> זה ישפיל וזה ירים וכתי' משמים הביט ה'<sup data-n=\"6499\">86</sup> כו' ממכון שבתו<sup data-n=\"6500\">87</sup> השגיח על כל יושבי הארץ היוצר כו' המבין<sup data-n=\"6501\">88</sup> אל כל מעשיהם לדונם כפי מעשיהם דוקא, וראי' מנינוה שאם לא עשו תשובה היו נהפכים<sup data-n=\"6502\">89</sup> כסדום כו' וכתי' בסאסאה בשלחה<sup data-n=\"6503\">90</sup> שנתמלא סאתם כו' הכל ע\"פ משפט התו' דוקא, רק שאינם נשפטים על התו\"מ שלא קיבלו כלל רק על ז' מצות שקבלו ב\"נ<sup data-n=\"6504\">91</sup> כו' וכמ\"ש מלך במשפט<sup data-n=\"6505\">92</sup> כו' במשפט התו' דוקא, וכמו שניבאו כמה מנביאים על הגוים וממלכות [כו']. הענין הוא שעכ\"ז מוותרים להם ביתר מכפי המדה והדין ומשפט להאריך אפו להם וכמו משלם לשונאיו<sup data-n=\"6506\">93</sup> אל פניו [להאבידו] כו' וכה\"ג, והוא מה שא' להודיע כמה ארך אפים לפניו כו' יו\"ד דורות מאדם ועד נח כו').",[["6484","72","<b>גילוי</b>: א: ליתא."],["6485","73","<b>יו\"ד דורות שמאדה\"ר</b>: אבות פ\"ה, מ\"ב."],["6486","74","<b>במעשה דר\"א</b>: כ\"ה גם במאמרי אדה\"ז תקס\"ב כאן (ע' קמו). ובמכות כד, סע\"א וכבר הי' ר\"ג ורבי אלעזר בן עזרי'."],["6487","75","<b>דר\"א</b>: כ\"ה גם במאמרי אדה\"ז כאן. מאמרי אדה\"א דברים ח\"ב ע' תקיב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670144\" data-slug=\"torat-chaim\" data-id=\"2300670144\">תו\"ח לך צב, ד</a>. והוא ע\"פ גי' הילקוט שמעוני עקב יא, טו (רמז תתסה)."],["6488","76","<b>דרומי</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191067\" data-slug=\"likkutei-sichot\" data-id=\"1300191067\">לקו\"ש</a> שבת נחמו (כרך יט) ע' 67 הערה 6."],["6489","*78","<b>לו</b>: אוצ\"ל: ל'."],["6490","77","<b>שא' לו. . שמאריך אף לרשעים</b>: נסמן לעיל פ' שמות לא, א."],["6491","78","<b>מבחי'</b>: א: מכפי."],["6492","79","<b>בדורו של אנוש. . וניזונים היו בחסדו</b>: נסמן לעיל כד, ד."],["6493","80","<b>עובדים</b>: א: עוברים ע\"ז."],["6494","81","<b>סדום ועמורה. . ונהפכו</b>: וירא יט, כה."],["6495","82","<b>כי לא שלם עון האמורי</b>: לך טו, טז."],["6496","83","<b>השופט כל הארץ</b>: וירא יח, כה."],["6497","84","<b>מלך אלקי' על גוים</b>: תהלים מז, ט."],["6498","85","<b>כי אלקי' שופט</b>: תהלים עה, ח."],["6499","86","<b>משמים הביט ה'</b>: שם לג, יג."],["6500","87","<b>ממכון שבתו</b>: נסמן לעיל פ' שמות כא, ד."],["6501","88","<b>היוצר כו' המבין</b>: תהלים לג, טו."],["6502","89","<b>מנינוה. . היו נהפכים</b>: יונה ג, ד."],["6503","90","<b>בסאסאה בשלחה</b>: ישעי' כז, ח. רש\"י לך טו, טז. ראה סוטה ט, א."],["6504","91","<b>ז' מצות שקבלו בני נח</b>: נסמן לעיל פ' וארא ס, א."],["6505","92","<b>מלך במשפט</b>: משלי כט, ד. ראה גם לקמן קעג, א. וש\"נ."],["6506","93","<b>משלם לשונאיו</b>: נסמן לעיל פ' שמות ל, ד."]]],[2300540278,"<b>והענין</b> הוא לפי ששרשם הוא <span data-k=\"pg\">344</span> ּ מבחי' התהו שקדם לבחי' התיקון כידוע בענין ואלה המלכים<sup data-n=\"6507\">94</sup> כו', ושרש נש\"י הוא מבחי' התיקון שהוא בחי' התומ\"צ דכתיב ויקם עדות ביעקב<sup data-n=\"6508\">95</sup> ותו' שם בישראל כו', וע\"כ גם שפע וברכה הגשמי' לא נמשך לישראל רק ע\"פ מעשיהם בקיום תומ\"צ דוקא וכמ\"ש והי' א\"ש<sup data-n=\"6509\">96</sup> תשמעו אל מצותי כו' ונתתי מטר ארצכם<sup data-n=\"6510\">97</sup> כו' ואספת דגנך כו' וא'<sup data-n=\"6511\">98</sup> ועצר את השמים<sup data-n=\"6512\">99</sup> כו' וכן א' ראה נתתי לפניך<sup data-n=\"6513\">100</sup> הברכה והקללה את הברכה אשר תשמעון<sup data-n=\"6514\">101</sup> כו', וכמו שאנו רואים שהשגחה אלקי' על כנס\"י בחיי פרנסתם והצלחתם הוא רק כפי מעשיהם בקיום התו\"מ בחשבון ודקדוק גדול דוקא, אבל לאוה\"ע משפיע רב טוב וחסד גם שאינם ראוים כלל ע\"פ מעשיהם בז' מצות דב\"נ כו' כנ\"ל וזהו פלא גדול לכאורה כו'. אך הנה שרש הדברים הוא לפי ששרש אוה\"ע הוא מבחי' הצמצום<sup data-n=\"6515\">102</sup> והחשך שקדם לאור והוא מ\"ש בזהר דקליפה קדמה לפרי<sup data-n=\"6516\">103</sup> כו' ששם יכולים הכל לקבל גם שאינו ראוי כראוי להיות שהוא בבחי' המקיפי' שנק' עגולים שאין שם בחי' התחלקות כלל מראש לסוף אלא הכל כא' מבלי חילוק מדריגות בפנימיות וחיצוני' כלל כו' והיינו קודם שנחלק כל ספי' ומדה לי' כו' וכמשל כחות הנפש כמו שהן כלולי' בעצם הנפש כו'. ולמעלה הוא הנק' בחי' ההעלם דסוכ\"ע בכלל שמצד עוצם הרוממות שמרומם לבדו כו' ומתנשא מימות עולם וכולא קמי' כלא<sup data-n=\"6517\">104</sup> ממש והכל שוין עליון ותחתון פנימי' העולמות וחיצוני' העולמות עד שאצי' ועשי' שוין<sup data-n=\"6518\">105</sup> ובכללות כל ההשתל' דקו\"ח אינו רק הארה בעלמא מאמיתי' עצמותו ית', וע\"כ משם הכל יכולים לקבל וכמ\"ש שוה ומשוה קטן וגדול<sup data-n=\"6519\">106</sup> כו' וכמו שממית בידים<sup data-n=\"6520\">107</sup> כו' כך ערך כל השפעת שפע עוה\"ז שאינו תופס מקום כלל וכלל, וראי' ממה שביקש משה<sup data-n=\"6521\">108</sup> שלא תשרה שכינה באוה\"ע כמ\"ש ונפלינו אני ועמך<sup data-n=\"6522\">109</sup> כו' (והוא ע\"י תו\"מ שנק' עם קדוש לה'<sup data-n=\"6523\">110</sup> כו' וכן והייתם לי סגולה<sup data-n=\"6524\">111</sup> מכל העמים כו' כמשי\"ת). וזהו רם על כל גוים<sup data-n=\"6525\">112</sup> כו' שהשפע הנמשך להם בא מבחי' הרוממות דבחי' צמצום הראשון שלפני ההשתל' דקו\"ח כו' (וכמ\"ש במ\"א ע\"פ גמלתהו טוב<sup data-n=\"6526\">113</sup> כו' בשרש ישראל ואוה\"ע [ש]שניהם עלו במח' הקדו[מה] רק שישראל עלו בבחי' הפנימי' ועצמו' כו'). וזהו הטעם מה שנמשך השפע לאוה\"ע בלא דקדוק וחשבון כלל כנ\"ל לפי שהגם שמקבלים מבחי' מותרות השפע לבד, אבל מצד",[["6507","94","<b>ואלה המלכים</b>: ראה גם לעיל פ' שמות מג, ג. וש\"נ."],["6508","95","<b>ויקם עדות ביעקב</b>: תהלים עח, ה."],["6509","96","<b>והי' א\"ש</b>: עקב יא, יג."],["6510","97","<b>ונתתי מטר ארצכם</b>: שם שם, יד."],["6511","98","<b>וא'</b>: ואמר. א: וא\"ל ואם לאו."],["6512","99","<b>ועצר את השמים</b>: עקב יא, יז."],["6513","100","<b>ראה נתתי לפניך</b>: פ' ראה יא, כו [ושם: ראה אנכי נתן לפניכם היום ברכה]."],["6514","101","<b>את הברכה אשר תשמעון</b>: פ' ראה שם, כז [ושם: תשמעו — וכן הוא בא — ראה לקמן ריא, ג. מאמרי אדה\"א שמות ח\"א ע' רכח. וש\"נ. ש\"א נב, א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670456\" data-slug=\"torat-chaim\" data-id=\"2300670456\">תו\"ח נח נד, ג</a> ובהערה 41]."],["6515","102","<b>ששרש אוה\"ע. . הצמצום</b>: ראה מאמרי אדה\"ז תקס\"ח ח\"א ע' קפ. מאמרי אדה\"א ויקרא ח\"א ע' קכח. וש\"נ."],["6516","103","<b>דקליפה קדמה לפרי</b>: נסמן לעיל פ' בא פז, ד."],["6517","104","<b>וכולא קמי' כלא</b>: נסמן לעיל לח, א."],["6518","105","<b>שאצי' ועשי' שוין</b>: ראה גם לקמן קצא, ג. קצה, א. מאמרי אדה\"א שמות ח\"א ע' יג. וש\"נ. הנחות תקע\"ז ע' נט. וש\"נ. שעה\"י קטז, א. שע\"ת יד, ג. ש\"א ל, א. סט, ב."],["6519","106","<b>שוה ומשוה קטן וגדול</b>: ע\"פ פיוט (לימים נוראים) האוחז ביד מדת משפט."],["6520","107","<b>שממית בידים</b>: משלי ל, כח. ראה גם לקמן קעד, א."],["6521","108","<b>שבקש משה</b>: ראה גם לעיל פ' שמות לא, א. וש\"נ."],["6522","109","<b>ונפלינו אני ועמך</b>: תשא לג, טז."],["6523","110","<b>עם קדוש לה'</b>: תבוא כו, יט."],["6524","111","<b>והייתם לי סגולה</b>: יתרו יט, ה."],["6525","112","<b>רם על כל גוים</b>: תהלים קיד, ד. ראה גם לעיל פ' וארא סד, א."],["6526","113","<b>גמלתהו טוב</b>: משלי לא, יב. ראה ד\"ה זה לאדה\"ז (לא נדפס לע\"ע ונמצא בבוך 269 יא, ב). מאמרי אדה\"א ויקרא ח\"א ע' קפה. דברים ח\"ב ע' תקעא. בראשית ע' רנ ובהנסמן בהנ\"ל. לעיל פ' בא קכד, א. לקמן קעד, ג. קצב, ג. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670586\" data-slug=\"torat-chaim\" data-id=\"2300670586\">תו\"ח נח עו, א</a> ובהערה 4. אוה\"ת בשלח (כרך ז) ע' ב'תרנג."]]],[2300540306,"היותה ממקום ומדריגה הגבוה מאד נעלה מבחי' עצם הרוממות כנ\"ל ע\"כ גם בחי' המותרות דשם רב וגדול ביותר, כמו עד\"מ המלך המרומם ביותר שלפ\"ע רוממותו יושפע מאתו מותרות בלי שיעור גם למי שאינו ראוי כראוי כו' בלי דקדוק כלל מטעם הנ\"ל וד\"ל (והוא מ\"ש אלביש שמים קדרות<sup data-n=\"6527\">114</sup> כו' ששמים הוא בחי' מקיפים דעולם התהו נתלבשו בבחי' צמצום וגדרים<sup data-n=\"6528\">115</sup> דבחי' חשך להשפיע גם לשאינו ראוי כו'). והוא הטעם שנמשך השפעה רבה לע\"ש דנוגה גם שלא ע\"פ משפט התו' כלל הגם שעוברים על ז' מצות שנצטוו ב\"נ <sup data-n=\"6529\">116</sup>כו' להיות שמקבלים מבחי' התהו בבחי' מותרות <span data-k=\"pg\">קעב</span> ּ השפע שבאה מצד הרוממות כנ\"ל שקדם לבחי' התיקון דתו\"מ ע\"כ אין משפט[ם] ע\"פ משפט התו' כלל. וזהו שא' להודיע כמה ארך אפיים לפניו כו' בחי' ארך אפיים זה הוא בא מבחי' הרוממות דמקיפי' להיות נמשך השפע גם ל[מי] שאינו ראוי כלל וכמו דור אנוש שהי' עובדי ע\"ז וכה\"ג להיות שעדיין קודם שבא האור בבחי' התיקון (וכמ\"ש במ\"א בענין המאמר מ\"ט עיזי מסגי ברישא<sup data-n=\"6530\">117</sup> והדר אימרי כו' וכמ\"ש יעקב לעשו יעבר נא אדוני<sup data-n=\"6531\">118</sup> לפני עבדו כו' משום דחשך קדם לאור וכברייתו ש\"ע<sup data-n=\"6532\">119</sup> כו').\n<b>אך</b> הנה ידוע במ\"ש יבחר לנו<sup data-n=\"6533\">120</sup> כו' דגם בבחי' עצם הרוממות כנ\"ל נבחרו ישראל בבחי' פנימי' ועצמיות כו', והוא ענין בחי' עולם התיקון שאחר עולם התהו דהיינו לאחר שהי' שבה\"כ ונפלו רפ\"ח ניצוצין<sup data-n=\"6534\">121</sup> כו' נמשך מקור לבחי' התיקון שהוא שם מ\"ה דחכ' לתקן ולברר לרפ\"ח ניצוצי' דתהו כו' דבחכ' אתברירו<sup data-n=\"6535\">122</sup> כו', והיינו ע\"פ בחי' החכ' דתו' שבאה מבחי' הפנימי' ועצמו' המאציל שיהי' מדה ושיעור באו\"כ והוא בבחי' מיעוט האור וריבוי הכלים מכלים שונים דוקא שזהו עיקר בחי' התיקון כידוע והוא מ\"ש מי מדד<sup data-n=\"6536\">123</sup> כו', דהיינו ענין המצות שהן כלים מכלים שונים שיבא האור בפרטי התחלקות כמו מדת חסד בהתחלקות ג' כלים פנימי אמצעי וחיצון רת\"ס<sup data-n=\"6537\">124</sup> כו', וכה\"ג בכל הספי' ומדות הן באים במדה ושיעור ע\"פ בחי' התיקון דתומ\"צ שזהו עיקר בחי' אדם העליון שלזה נק' תורת האדם<sup data-n=\"6538\">125</sup> כו' בבחי' הפנימי' דוקא. וז\"ש ותורה שם בישראל דוקא. וזהו הטעם שהשפע נמשך לישראל ע\"פ דקדוק וחשבון דוקא כנ\"ל וכמ\"ש אם בחוקתי תלכו<sup data-n=\"6539\">126</sup> כו' וכן והי' אם שמוע כו' לפי שהן בחי'",[["6527","114","<b>אלביש שמים קדרות</b>: ישעי' נ, ג. ראה גם לעיל לט, ב."],["6528","115","<b>וגדרים</b>: א: וקדרות."],["6529","116","<b>כו'</b>: א: כנ\"ל."],["6530","117","<b>מ\"ט עיזי מסגי ברישא</b>: נסמן לעיל יח, א."],["6531","118","<b>יעבר נא אדוני</b>: וישלח לג, יד."],["6532","119","<b>וכברייתו ש\"ע</b>: שבת עז, ב. ראה גם לעיל פ' וארא מט, ג."],["6533","120","<b>יבחר לנו</b>: נסמן לעיל פ' שמות לה, ג."],["6534","121","<b>רפ\"ח ניצוצין</b>: נסמן לעיל לו, ג."],["6535","122","<b>דבחכ' אתברירו</b>: נסמן לעיל י, ג."],["6536","123","<b>מי מדד</b>: ישעי' מ, יב."],["6537","124","<b>ג' כלים. . רת\"ס</b>: ראה גם לעיל פ' בא קכט, ד ובהנסמן שם."],["6538","125","<b>נק' תורת האדם</b>: שמואל-ב ז, יט."],["6539","126","<b>אם בחוקתי תלכו</b>: בחוקותי כו, ג."]]],[2300540331,"התיקון דשם מה דתו\"מ בבחי' הפנימי' דוקא כנ\"ל ע\"כ הן נשפטי' ע\"פ משפט התורה דוקא אם בחקותי תלכו כו' וגם בהיותם בגלות שכינה עמהם<sup data-n=\"6540\">127</sup> ואע\"פ שמקבלים השפע מלבוש שק דע\"ש כו' וד\"ל. ובזה יובן מ\"ש על התו' ארוכה מארץ מדה<sup data-n=\"6541\">128</sup> במפיק ה\"א שמדייק במדה זאת דתו' שאינה כשאר מדות, והוא מה שבאמת יש בה דבר והיפוכו דאם ארוכה מארץ ורחבה מים הרי היא למעלה מן המדה ומ\"מ א' מדה שרצונו מדה שלה שיש בה מדה רק שאינו במדות הארץ והים כו'. והענין הוא דבאמת שרש התו' הוא מעצמו' פנימי' חכמתו ית' ועצמות פנימי' מדותיו שהן בחי' א\"ס ממש שלמעלה מן הצמצום ומדה דקו\"ח שבא בהשתלשלו' דאבי\"ע משום דלתבונתו אין מספר<sup data-n=\"6542\">129</sup> כלל. וז\"ש ארוכה מארץ בחי' עלמא דאתגלייא בחי' מל' ה\"א אחרונה<sup data-n=\"6543\">130</sup> שבא בקו<sup data-n=\"6544\">131</sup> המדה בירידה והמשכה למטה דוקא, ואמנם בחי' ה\"א דמל' דתו' שהוא בחי' הנגלה שבתו' [(או] תושבע\"פ מל' קרינן לה<sup data-n=\"6545\">132</sup> ) ארוכה הרבה ממנה ולא תכילנה הארץ, ועכ\"ז ניתנה במדה ושיעור והם בחי' השיעורים והגבולים שבתו' רק שהן באים מצד בחי' הפנימי' דח\"ע כמ\"ש מי מדד כו', ואדרבה באותיות התו' ברא כל העולמות כמ\"ש בס\"י בספר<sup data-n=\"6546\">133</sup> וסופר וסיפור כו', וזהו נפלאת חכמתו<sup data-n=\"6547\">134</sup> שניתנה התו' בארץ דוקא ובמדה דוקא וכמ\"ש בחכ' יבנה בית<sup data-n=\"6548\">135</sup> בי\"ת דבראשית וכמ\"ש פיה פתחה בחכ'<sup data-n=\"6549\">136</sup> כו' וכמ\"ש והארץ האירה מכבודו<sup data-n=\"6550\">137</sup> אין כבוד אלא תו'<sup data-n=\"6551\">138</sup>, וכן מלא כה\"כ<sup data-n=\"6552\">139</sup> כו'. וזה שדקדק מדה דוקא, <span data-k=\"pg\">346</span> ּ וכן ורחבה מני ים ברוחב דבינה בחי' ה\"א ראשונה<sup data-n=\"6553\">140</sup> בחי' עלמא דאתכסייא<sup data-n=\"6554\">141</sup> שהוא בחי' סוד הגנוז בטעמי תורה וכמ\"ש הנסתרות לה'<sup data-n=\"6555\">142</sup> כו' וד\"ל (וזהו איה סופר<sup data-n=\"6556\">143</sup> כו' כמ\"ש במ\"א בענין מתקלא דהיינו מקור קו המדה דאו\"כ להיות יחוד עליון בפנימי' וחיצוני' הכל במדה דוקא). והיינו מה שאנו רואי' שניתנה התו' במדה ושיעור בין בה\"ח דרמ\"ח מ\"ע<sup data-n=\"6557\">144</sup> כמו ל\"ב חוטין בציצית וד' בתים כו' בין בה\"ג דל\"ת<sup data-n=\"6558\">145</sup> כו', ולא עוד [אלא] שעיקר קיום [ה]עולמו' כולן הוא ע\"י [ה]מדה הפנימי' דתו\"מ וכמ\"ש ואשים דברי בפיך<sup data-n=\"6559\">146</sup> [כו'] לנטוע שמים כו').\n(ג) <b>והנה</b> בכ\"ז יובן מה ששחק ר\"ע כשראה כרך גדול של רומי מלא תענוגי עוה\"ז וא' אם לעוברי רצונו כך לעושי רצונו עאכו\"כ, דהנה מבואר למעלה דשרש יניקת השפע דע\"ש נמשך מלמעלה מן בחי' התהו שקדם לתיקון מבחי' מותרות השפע שנמשך לשאינו ראוי כראוי לרעים כמו לטובים בשוה",[["6540","127","<b>בגלות שכינה עמהם</b>: נסמן לעיל פ' שמות א, ד הערה 53."],["6541","128","<b>ארוכה מארץ מדה</b>: איוב יא, ט. ראה גם אוה\"ת כאן (ע' ב'תרנז)."],["6542","129","<b>דלתבונתו אין מספר</b>: תהלים קמז, ה."],["6543","130","<b>מל' ה\"א אחרונה</b>: נסמן לעיל פ' שמות יב, ד הערה 581."],["6544","131","<b>שבא בקו</b>: א: שבמא' קו."],["6545","132","<b>תושבע\"פ מל' קרינן לה</b>: ת\"ז בהקדמה (יז, א)."],["6546","133","<b>בס\"י בספר</b>: ראה שם בתחלתו."],["6547","134","<b>נפלאת חכמתו</b>: א: מפליאות חכמה."],["6548","135","<b>בחכ' יבנה בית</b>: משלי כד, ג. ראה גם לעיל פ' וארא פא, ג. וש\"נ."],["6549","136","<b>פיה פתחה בחכ'</b>: משלי לא, כו."],["6550","137","<b>והארץ האירה מכבודו</b>: יחזקאל מג, ב."],["6551","138","<b>אין כבוד אלא תו'</b>: אבות פ\"ו, ג."],["6552","139","<b>מלא כה\"כ</b>: ישעי' ו, ג."],["6553","140","<b>דבינה בחי' ה\"א ראשונה</b>: נסמן לעיל פ' שמות יב, ד הערה 581."],["6554","141","<b>דבינה. . עלמא דאתכסייא</b>: ראה זהר ויצא קנח, א. לקוטי תורה שמיני\nעצרת פח, ד. לקמן פ' ויקהל שצ, ב."],["6555","142","<b>הנסתרות לה'</b>: נצבים כט, כח."],["6556","143","<b>איה סופר</b>: ישעי' לג, יח. ראה מאמרי אדה\"ז תקס\"ה ח\"ב ע' ב. מאמרי אדה\"א נ\"ך ע' עא."],["6557","144","<b>בה\"ח דרמ\"ח מ\"ע</b>: נסמן לעיל פ' בא צו, א."],["6558","145","<b>בה\"ג דל\"ת</b>: ראה קו\"א לתניא (להבין מ\"ש בפע\"ח) קנח, ב."],["6559","146","<b>ואשים דברי בפיך</b>: ישעי' נא, טז."]]],[2300540354,"מצד עצם הרוממות (וז\"ש כמה ארך אפים לפניו דוקא עד\"מ כאשר המלך ברוממות התענוג בעצמותו שהכל מקבלים רוב שפע בלי דקדוק כלל כו'<sup data-n=\"6560\">*147</sup> וגם לעוברי רצונו משפיע לרוב בהיות שאינו תופס מקום כלל כו', ומ\"ש<sup data-n=\"6561\">147</sup> אם לעוברי רצונו כך לעושי רצונו עאכו\"כ, פי' אם בחי' מותרות השפע תענוג העליון נמשך וירד למטה מטה כ\"כ בבחי' שפע תענוגי עוה\"ז שנפלו בשבה\"כ לעוברי רצונו שהן ע\"ש (ובפרט בגלות השכינה בע\"ש דאמלאה<sup data-n=\"6562\">148</sup> כו' לא נתמלאה צור<sup data-n=\"6563\">149</sup> [כו'] כמו כרך רומי), לעושי רצונו בקיום התו\"מ שהוא בבחי' התיקון דשם מ\"ה כנ\"ל שהוא בחי' פנימי' התענוג והרצה\"ע עאכו\"כ שהוא ענין עוה\"ב שבא לשכר מצות דכתי' בי' להנחיל אוהבי יש<sup data-n=\"6564\">150</sup> ממקור כל התענוגי' העליוני' שנק' עדן כו' בחי' שעשועי המלך בעצמותו<sup data-n=\"6565\">151</sup> [ממש] כו' כמ\"ש יקימנו ונחי' לפניו<sup data-n=\"6566\">152</sup> [לפניו] ממש כו' וד\"ל. ואע\"פ שע\"פ משפט התו' [ומצות] בא אור השפע בדקדוק וחשבון דוקא כמ\"ש אם בחוקתי כו' ואין בזה ויתור במדת ארך אפים כמו לאוה\"ע שהן עוברי רצונו ונשפע להם כל טוב עוה\"ז כנ\"ל, הענין הוא דמדת ארך אפים זה שמשלם לשונאיו כו' הוא בא רק דרך מותרות לבד ומצד עוצם הרוממות דכל\"ח<sup data-n=\"6567\">153</sup> לפ\"ע הרוממות כמו עד\"מ מלך המרומם בעצמותו מאד שגם מותרות שלו אין לו שיעור כו' ע\"כ מאריך אף גם לרשעים כו', אבל מה שיאיר לעושי רצונו בקיום התו\"מ יהי' בבחי' פנימי' ועצמיות השפע תענוג שבעצמותו רוממותו דוקא וז\"ש לעושי רצונו עאכו\"כ כמו שאין ערוך כלל למחו\"ד<sup data-n=\"6568\">154</sup> הנופל מעצם פנימי' גדולת יקר כל הון בית המלך בסגולת מלכים כו', ולזה הטעם ניתן לישראל השפע בדקדוק גדול ע\"פ קו המדה דתו\"מ דוקא כמ\"ש אם כו' וד\"ל.\n<b>ובכל</b> זאת יובן ענין הנ\"ל בצמיחת החטה הזרוע בארץ כשתרקב דוקא יתלבש בה כח הצומח שבארץ ותצמיח בכפלי כפליים כו' מאין יש לכח הצומח שבארץ להוסיף הרבוי הזה כו', דהנה כנס\"י הן בע\"ש דק\"נ כמו משל הזריע' בארץ כמ\"ש וזרעתיה לי בארץ כו', והוא מה שנשפלו הנשמות בחומר גופני גשמי דק\"נ כמ\"ש ימי שנותינו בהם<sup data-n=\"6569\">155</sup> שבעים שנה כו' ומקבלים שפע חיי <span data-k=\"pg\">קעג</span> ּ גופם שהוא בני חיי ומזוני דרך צנור השפע לע\"ש<sup data-n=\"6570\">156</sup> דק\"נ כו' הוא בבחי' גלות השכינה בכלל כמאמר גלו לאדום שכינה עמהם<sup data-n=\"6571\">157</sup> כו'. ובפרט בכל ניצוץ האלקי הרי הוא משועבד ונעבד בעבודת עבד לקבל שפע מעשה<sup data-n=\"6572\">158</sup> שהן",[["6560","*147","<b>(וז\"ש. . כו'</b>: א: וז\"ש. . אוצ\"ל: כו')."],["6561","147","<b>ומ\"ש</b>: א: כמ\"ש."],["6562","148","<b>דאמלאה</b>: יחזקאל כו, ב."],["6563","149","<b>לא נתמלאה צור</b>: רש\"י תולדות כה, כג. ראה מאמרי אדה\"א דברים ח\"א ע' ס. וש\"נ."],["6564","150","<b>להנחיל אוהבי יש</b>: ראה גם לקמן קלח, ד. וש\"נ."],["6565","151","<b>שעשועי המלך בעצמותו</b>: נסמן לעיל פ' בא צב, ד."],["6566","152","<b>יקימנו ונחי' לפניו</b>: הושע ו, ב."],["6567","153","<b>דכל\"ח</b>: א: דכלא חשיב."],["6568","154","<b>למחו\"ד</b>: שם: למותרות."],["6569","155","<b>ימי שנותינו בהם</b>: תהלים צ, י."],["6570","156","<b>לע\"ש</b>: א: מע\"ש."],["6571","157","<b>גלו לאדום שכינה עמהם</b>: נסמן לעיל פ' שמות א, ד."],["6572","158","<b>מעשה</b>: א: מע\"ש."]]],[2300540377,"המזלו'<sup data-n=\"6573\">159</sup> בפרנסה ובני חיי [ומזוני] כו' כמ\"ש [כי] בלעונו אדונים זולתיך כו' בלחץ ודוחק גדול כידוע, ובחי' גסות דק\"נ מושל ושולט על הניצוץ ג\"כ להחשיך אורה בתכלית עד שנמשל כמו רקבון החטה הזרוע ב[עפר ה]ארץ המכסה עליה כנ\"ל, כך נרקב אור וחיות הניצוץ האלקי עד שיחשב כמת [ממש] עד שכל אוכל דחכ' תתעב כו' ונעשה כעפר דומם שהוא טמטום הלב ומוח<sup data-n=\"6574\">160</sup> ביותר ושוכח על ה' לגמרי רק לחיות כחיי הגוים כו' כמ\"ש נבלע ישראל בגוים כו'. והנה עיקר הריקבון היטב בעפר דק\"נ הוא מה שיבא האדם לכלל מרירות עצומה בנפשו וישבר רוחו בקרבו מאד על אשר נכרת נפשו ולבו מה' אחד ועל עזבו את ה' מקור החיים לחצוב בורות נשברים כו' שהן המזלות [(שז\"ש] שהן כעובדי ע\"ז בטהרה [כו')], ומרירות זאת היא כרקבון החטה ממש שעי\"ז מתבטל גסות וישות שלה שמזה בא לבחי' האין דכח הצומח שבארץ להצמיח מאין ליש בכפלי כפליים כו', וכך הוא בבחי' רקבון הניצוץ האלקי ע\"י המרירות שמצד הריחוק בהדבקו בעפר דק\"נ בגסות ושמרים כו', ועי\"ז מתבטל לבחי' האין האלקי שיש בשרש דשרש דכח הצומח שבעפר דק\"נ כמו שהוא בשרשם הראשון קודם שנפלו בשבה\"כ כו' שהוא מבחי' המקיפים דאורות דתהו שקדם לתיקון שבא מבחי' הרוממות דעצמו', שיומשך משם גם מותרי השפע רב לפ\"ע הרוממות דהיינו למעלה מכפי המדה וחשבון כנ\"ל בענין להודיע כמה ארך אפים לפניו כו', והוא ג\"כ הטעם שיצמיח גם באור הזרוע לצ\"ע [שהן הנשמות שבגופים להיות מוסיף והולך בכפלי כפליים על עצם אור הנשמה כמו שהיתה תחלה במקור חוצבה בצ\"ע] כו' כמ\"ש בא יבא ברינה כו'. וזהו שאנו רואים שאחר המרירות העצומה ולב ורוח נשברה מעומק התפלה<sup data-n=\"6575\">161</sup> בגסות דק\"נ הוא שיבא דוקא לכלל אה\"ר בתענוגי' להתענג על ה' בשמחה וטוב לבב כמו אה\"ר דבכל מאדך בלי גבול ושיעור שלא הי' אור גדול כזה בניצוץ מקודם כלל וד\"ל. וגם כל פרי טוב מעשה המצות בעוה\"ז שעובד מאוי\"ר בכל ימי חייו שנשמתו מלובש בגוף שנלקח מק\"נ דוקא עושה פרי למעלה מעלה בבחי' יחו\"ע להוסיף אור גדול באצי' כו' שזה אור חדש עליון יותר מאור ומקור המוליד את הנש\"י שנק' אור הזרוע לצ\"ע כו', וזהו כמשל פרי תבואות רב שנצמח מן הזריעה כו' כמ\"ש זרעו לכם לצדקה וקצרו<sup data-n=\"6576\">162</sup> כו', ובפרט מן שמחה של מצוה כמ\"ש עבדו את ה' בשמחה<sup data-n=\"6577\">163</sup> דוקא, וזהו תחת אשר לא עבדת<sup data-n=\"6578\">164</sup> את ה' בשמחה ובטוב לבב מרוב כל, פי' מרוב כל היא תוס' אור רב מבחי' כל שהוא אור עצמו' א\"ס ממש שנמשך ע\"י עבודת מעשה המצות בעוה\"ז דוקא שזה לא הי' בנשמות כלל בשרשם מקודם<sup data-n=\"6579\">165</sup> טרם שנזרעו בארץ, שאם הי' להם שמחה וטוב לבב מרוב כל שהוא [אח\"פ] ממש קודם לא היו צריכים לבא בעוה\"ז כלל, רק ע\"י",[["6573","159","<b>מע\"ש שהן המזלו'</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670093\" data-slug=\"torat-chaim\" data-id=\"2300670093\">תו\"ח נח נט, ד</a> ובהערה 56."],["6574","160","<b>טמטום הלב ומוח</b>: נסמן לעיל ב, ב."],["6575","161","<b>התפלה</b>: א: הנפילה."],["6576","162","<b>זרעו לכם לצדקה וקצרו</b>: נסמן לעיל פ' וארא פב, א."],["6577","163","<b>עבדו את ה' בשמחה</b>: תהלים ק, ב."],["6578","164","<b>תחת אשר לא עבדת</b>: תבוא כח, מז [ושם: ה\"א]. ראה גם מאמרי אדה\"א שמות ח\"ב ע' שיח ואילך."],["6579","165","<b>בשרשם מקודם</b>: א: בשרש מקורם."]]],[2300540398,"מרירות ושפלות העצומה בעוה\"ז תחת שעבוד דק\"נ אז באו לבחי' שמחה וטוב לבב מרוב כל מטעם הנ\"ל, ואם אין שמחה וטוב לבב מרוב כל <span data-k=\"pg\">348</span> ּ במעשה המצות אחרי הרקבון של הניצוץ במרירות דוקא כנ\"ל אז ועבדת את אויביך<sup data-n=\"6580\">166</sup> כמו נבלע ישראל כו' שהוא שעבוד עול קשה בטרדת פרנסה שנק' מים רבים כו'. אך כאשר בצר להם יבקשו משם דוקא את ה' בעבודה ובשמחה ובטוב לבב <sup data-n=\"6581\">167</sup>כו' הוא ענין התוס' ברכה בתבואות שהן נש\"י הזרוע[ים] בארץ ב[כפלי] כפליים לאין שיעור למעלה כמ\"ש אז יאמרו בגוים הגדיל ה' לעשות עם אלה כו', לפי שמהם וע\"י דוקא נעשה עוצם הריבוי וההגדלה דפרי תבואות מטעם הנ\"ל בבחי' יתרון האור מן החשך שקדם לאור דוקא כו' וד\"ל.\n(ד) <b>וזהו</b> ששחק ר\"ע ואמר אם לעוברי רצונו כך כו' [כי] הסתכל בחכמתו ורא[ה] תכלית המכוון מן הגלות דנש\"י בע\"ש דק\"נ שהוא כמשל הזריעה בארץ כנ\"ל שיצמיחו ויגדילו פרי למעלה בתוס' ברכה מרובה לאין שיעור למעלה כנ\"ל מצד בחי' יתרון אור הבא מן החשך דק\"נ דוקא מפני ששרשם בבחי' חשך סתרו דבחי' התהו כו', ע\"כ הי' לשחוק בעיניו כל ענין זה האור והשפע רק בתענוגי<sup data-n=\"6582\">168</sup> העוה\"ז הנמשך לע\"ש מפסולת שמרים הנופל מבחי' העונג הפנימי' והעצמי' שבעצמות המאציל דכלא ממש חשיב, וע\"כ א' בדרך ק\"ו כו' אם לעוברי רצונו כך נמשך מותרי השפע מבחי' ארך אפים דרצה\"ע הנופל דרך חיצוני' ואחורי' מצד הרוממות כנ\"ל בענין להודיע<sup data-n=\"6583\">169</sup>, לעושי רצונו עאכו\"כ שה[ן] קיום המצות פנימי' ורצון<sup data-n=\"6584\">170</sup> הפשוט בתכלית שהוא פנימי' תענוג הפשוט שנק' שעשועי המלך שמצד עצמותו ממש כנ\"ל, הרי שם האור והשפע התענוג העצמי' שאין לו שיעור למעלה מעלה כנ\"ל וד\"ל. והיינו דוקא ע\"י שעושין רצונו במצות בעוה\"ז בדברים גשמי' דנוגה דעשי' כמו בצמר דציצית וקלף דתפילין וכה\"ג בסו\"מ בפו\"מ דוקא שזהו התהפכות חשוכא דק\"נ לנהורא כו' שבמצות בגשמי' דוקא מלובש פנימי' הרצון ותענוג העצמו' הנ\"ל, וכמאמר היום לעשותם דוקא ואז למחר לקבל שכרם<sup data-n=\"6585\">171</sup> בעוה\"ב שהוא גילוי עדן העליון דתענוגי' ושעשועי העצמו'. אבל בלא מצות בעוה\"ז אין עוה\"ב כלל וכמאמר כל ישראל<sup data-n=\"6586\">172</sup> יש להם כו' שנא' ועמך כולם צדיקים<sup data-n=\"6587\">173</sup> במצות דאפי' פו\"י<sup data-n=\"6588\">174</sup> כו', וזהו רק מטעם היפך [ה]חשך לאור שמוסיף האור למעלה ביתרון גדול וכמ\"ש העם ההולכים בחשך<sup data-n=\"6589\">175</sup> דוקא ראו אור גדול שהוא עוה\"ב מפני שאחר החשך בגלות קשה ובמרירות עצומה מן הריחוק משם [דווקא] יעבדו את ה' במצות בשמחה וטוב לבב כנ\"ל ועי\"ז דוקא יראו האור הגדול בעוה\"ב מטעם הנ\"ל וד\"ל. וזהו בצר לך ומצאוך<sup data-n=\"6590\">176</sup> כו' ועבדת משם<sup data-n=\"6591\">177</sup> דוקא כו' כי תדרשנו כו' לפי",[["6580","166","<b>ועבדת את אויביך</b>: תבוא כח, מח."],["6581","167","<b>כו'</b>: א: כי."],["6582","168","<b>רק בתענוגי</b>: שם: רב מתענוגי."],["6583","169","<b>בענין להודיע</b>: שם: ליתא."],["6584","170","<b>ורצון</b>: א: רצונו."],["6585","171","<b>היום לעשותם. . שכרם</b>: נסמן לעיל פ' שמות ו, ד."],["6586","172","<b>כל ישראל</b>: סנהדרין ר\"פ חלק (צ, א)."],["6587","173","<b>ועמך כולם צדיקים</b>: ישעי' ס, כא."],["6588","174","<b>פו\"י </b>[א: פושעי ישראל]: עירובין יט, א."],["6589","175","<b>העם ההולכים בחשך</b>: ישעי' ט, א."],["6590","176","<b>בצר לך ומצאוך</b>: ואתחנן ד, ל."],["6591","177","<b>ועבדת משם</b>: ואתחנן ד, כט [ושם: ובקשתם משם]."]]],[2300540418,"שהמיצר ומצוק יגיעו מזה לתשובה אמיתי' במרירות עצומה שזהו כרקבון הגרעין שיעורר לכח הצומח להצמיח רב תבואות וכמו בגלות מצרים דכתי' וכאשר יענו אותו<sup data-n=\"6592\">178</sup> כן ירבה [וכן] כו'. ובזה יובן מה שרבקה הלבישה ליעקב<sup data-n=\"6593\">179</sup> בנה הקטן בגדי עשו בנה הגדול שזהו התלבשות הנשמה בגוף לעשות תשובה ומצות בדצח\"מ גשמי', ועשו נק' בנה הגדול כמ\"ש ואלה המלכים כו' שהוא ענין התהו שקדם לתיקון קודם השבירה שהוא בחי' שם ס\"ג<sup data-n=\"6594\">180</sup> <span data-k=\"pg\">קעד</span> ּ דתהו שלמעלה משם מ\"ה<sup data-n=\"6595\">181</sup> דתיקון כו', ואחר הבירור דס\"ג [שיעלה] ע\"י תשו' ותו\"מ יבא יתרון אור גדול מן החשך כנ\"ל בענין מ\"ש לעוברי רצונו כו' וד\"ל.\n<b>ובכל</b> הנ\"ל יובן מ\"ש ויהי בשלח פרעה את העם כו', כי הנה בגלות מצרים היו כנ\"י בבחי' זריעה והגדילו והצמיחו כמ\"ש רבבה כצמח השדה<sup data-n=\"6596\">182</sup> כו' ותרבי ותגדלי כו', וכן א' גפן ממצרים תסיע<sup data-n=\"6597\">183</sup> כסו הרים צלה<sup data-n=\"6598\">184</sup> כו', היינו כנ\"ל בענין ראשית תבואתו כו', שע\"י הגלות קשה דוימררו את חייהם<sup data-n=\"6599\">185</sup> כו' נעשה צמיחה בכפלי כפליים כמ\"ש העם ההולכים בחשך דגלות ראו אור גדול שנגלה עליהם כו' וקבלו התורה פב\"פ מעין עוה\"ב כידוע והוא מטעם כל הנ\"ל ביתרון האור מן החשך דוקא וד\"ל. וזהו ויהי בשלח פרעה כו', פי' פרעה אותיות עורף<sup data-n=\"6600\">186</sup> והוא בחי' עורף אחוריי' שמקבלים משם הקליפות יניקה דהיינו בחי' כתר דקליפה<sup data-n=\"6601\">187</sup> שמקבל מאחוריי' דכתר דקדושה כו', כמו העורף שהוא אחוריים דפנימי'<sup data-n=\"6602\">188</sup>, כי בפנים הוא בחי' פנימי' הרצון והשכל ובעורף הוא רק בחי' אחוריי' דרצון כמו עד\"מ הנותן שפע לשונאיו בדרך אחוריי' כמאן דשדי<sup data-n=\"6603\">189</sup> בתר כתפוי כו', וירדו נש\"י בגלות מצרים בשר של מצרים שהוא פרעה עורף ואחוריי' דרצון כענין הנ\"ל בענין מ\"ש אם לעוברי רצונו כך כו' שמאריך אף לרשעים כו', ובחי' כתר דקליפה הוא עומק רע שלמעלה מחו\"ב ומדות דקליפה שהן זקני פרעה וחרטומי מצרים<sup data-n=\"6604\">190</sup> כו' ויצאו נש\"י מעומק רע מנש\"ט דקליפה מאפילה לאור גדול<sup data-n=\"6605\">191</sup> כו' וכמ\"ש או הנסה אלקי'<sup data-n=\"6606\">192</sup> כו'<sup data-n=\"6607\">193</sup> לבא לקחת לו גוי מקרב גוי כו', וזהו כמו הקצירה שאחר הזריעה שע\"י שעבוד[ם] בגלות קשה דוקא כמו משל הרקבון דחטה כו' הגדילו ורבו למעלה כענין הזורע קב להוציא כמה כורין כו',",[["6592","178","<b>וכאשר יענו אותו</b>: שמות א, יב."],["6593","179","<b>שרבקה הלבישה ליעקב</b>: תולדות כז, טו. ראה גם לקמן פ' משפטים רפז, ב. תצוה שכה, א. וש\"נ."],["6594","180","<b>השבירה. . שם ס\"ג</b>: נסמן לעיל פ' וארא פה, ג."],["6595","181","<b>ס\"ג. . שלמעלה משם מ\"ה</b>: נסמן לעיל פ' שמות מ, ד."],["6596","182","<b>רבבה כצמח השדה</b>: יחזקאל טז, ז."],["6597","183","<b>גפן ממצרים תסיע</b>: תהלים פ, ט."],["6598","184","<b>כסו הרים צלה</b>: שם פ, יא."],["6599","185","<b>דוימררו את חייהם</b>: שמות א, יד."],["6600","186","<b>פרעה אותיות עורף</b>: נסמן לעיל יט, ב."],["6601","187","<b>פרעה. . כתר דקליפה</b>: נסמן לעיל לב, ד."],["6602","188","<b>דפנימי'</b>: א: דפנים."],["6603","189","<b>כמאן דשדי</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310027\" data-slug=\"tanya\" data-id=\"3401310027\">תניא פכ\"ב</a>."],["6604","190","<b>מחו\"ב ומדות. . זקני פרעה וחרטומי מצרים</b>: ראה גם מאמרי אדה\"א במדבר ח\"ג ע' א'כב. דברים ח\"א ע' ט. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670112\" data-slug=\"torat-chaim\" data-id=\"2300670112\">תו\"ח לך צב, ב</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680164\" data-slug=\"torat-chaim\" data-id=\"2300680164\">ויחי רלח, א</a>."],["6605","191","<b>מאפילה לאור גדול</b>: ע\"ד פסחים קטז, ב (במשנה). הגש\"פ פיסקא לפיכך."],["6606","192","<b>או הנסה אלקי'</b>: ואתחנן ד, לד."],["6607","193","<b>כו'</b>: כ\"ה גם בא."]]],[2300540438,"והן ס\"ר נשמות שיצאו ממצרים<sup data-n=\"6608\">194</sup> שהגדילו מאד ולא עוד אלא שיבוררו<sup data-n=\"6609\">195</sup> כל בחי' הטוב דקדושה שנפלו בקליפה דפרעה ועמו כו' וכמ\"ש ואח\"כ יצאו ברכוש גדול<sup data-n=\"6610\">196</sup> כו' וכמ\"ש וינצלו את מצרים שעשאוה כמצולה<sup data-n=\"6611\">197</sup> כו' כי גם ערב רב עלה אתם<sup data-n=\"6612\">198</sup> (שהן מספר ר\"ב מרפ\"ח ניצוצין ונשאר רק פ\"ו<sup data-n=\"6613\">199</sup> כו'). וזהו ויהי בשלח פרעה כו' כמו משלחי רגל<sup data-n=\"6614\">200</sup> כו' כמו שדה השלחין<sup data-n=\"6615\">201</sup> כשנגמר כבר כ\"צ<sup data-n=\"6616\">202</sup> בגידול התבואות שמשלחים לבית ועיר כו', וכך כאשר כבר נגמר גידול הזריעה דנש\"י במצרים שלחם פרעה דוקא כו' וממנו<sup data-n=\"6617\">203</sup> וע\"י הגדילו והצמיחו כ\"צ<sup data-n=\"6618\">204</sup> מטעם הנ\"ל וכמו אז יאמרו בגוים דוקא הגדיל ה' כו' כנ\"ל, וכן א' והייתם לי סגולה מכל העמים דוקא וכמ\"ש אתה בחרתנו מכל העמים<sup data-n=\"6619\">205</sup> כו', פי' מה שנבחרנו להיות למעלה מעלה ראשית<sup data-n=\"6620\">206</sup> כמ\"ש ראשית תבואתו בבחי' פנימי' ועצמו' ממש עם קרובו [ממש] הוא בא ע\"י היותם בגלות בבחי' זריעה בעלמא דוקא וד\"ל.\n(ה) <b>ולא</b> נחם אלקים דרך ארץ פלשתים כי קרוב הוא, [פי' כי קרוב הוא] לארץ מצרים ויוכלו לשוב מצרימה כו', והענין הוא כי בחי' הקליפות דפלשתים קרוב הוא לקליפות<sup data-n=\"6621\">207</sup> דמצרים שהוא בבחי' כתר דקליפה<sup data-n=\"6622\">208</sup> ויוכלו ליפול משם לקליפו' דמצרים כו'. כי הנה ידוע שאזלעו\"ז<sup data-n=\"6623\">209</sup> כו' ונגד הקדושה הוא הסט\"א שמקבל מחיצוני' ואחוריי' דע\"ס דקדושה ונק' כתרין דמסאבותא<sup data-n=\"6624\">210</sup> כידוע וע\"כ יש לכל שר ושר ולכל<sup data-n=\"6625\">211</sup> אומה ולשון שרש למעלה בחיצוני' ואחוריי' בכל ספי' ומדה דקדושה, וכמו שידוע בענין שא' אברהם <span data-k=\"pg\">350</span> ּ יצא ממנו ישמעאל<sup data-n=\"6626\">212</sup> שמחסד דקדושה דאברהם יצא בחי' המותרות ואחוריי' שר של ישמעאל חסד דקליפה<sup data-n=\"6627\">213</sup> וכן ביצחק בחי' גבורות<sup data-n=\"6628\">214</sup> דקדושה יצא ממנו עשו<sup data-n=\"6629\">215</sup> בחי' גבורות<sup data-n=\"6630\">216</sup> דקליפה וכך יש בכל פרטי מדרגות בע\"ס דחו\"ב<sup data-n=\"6631\">217</sup> ומדות כו'. והיינו גם לנגד בחי' הרצון ותענוג דקדושה יש בסט\"א הרצון והתענוג בקליפה, וכן חו\"ב דקליפה כו', וכמו ששר של מצרים הוא באחוריי' דרצה\"ע דקדושה כך שר של פלשתים הוא מאחוריי' דתענוג העליון דקדושה, והיינו בחי' מנגד לבחי' פנימי' דתענוג הפשוט ועצמו' דקדושה כמו ענין שמחה וטוב לבב בתענוג ושמחה עצמיות כו'",[["6608","194","<b>ס\"ר נשמות שיצאו ממצרים</b>: בא יב, לז."],["6609","195","<b>שיבוררו</b>: א: שביררו."],["6610","196","<b>ואח\"כ יצאו ברכוש גדול</b>: לך טו, יד."],["6611","197","<b>וינצלו. . שעשאוהו כמצולה</b>: נסמן לעיל פ' שמות לו, ג."],["6612","198","<b>גם ערב רב עלה אתם</b>: בא יב, לח."],["6613","199","<b>ר\"ב. . פ\"ו</b>: נסמן לעיל פ' בא קטו, ב."],["6614","200","<b>משלחי רגל</b>: ישעי' לב, כ."],["6615","201","<b>שדה השלחין</b>: ראה בבא בתרא סח, א."],["6616","202","<b>כ\"צ</b>: א: כל צרכי [צרכה]."],["6617","203","<b>וממנו</b>: שם: כי ממנו. ראה גם סה\"מ מלוקט ח\"א ע' יד."],["6618","204","<b>כ\"צ</b>: שם: כל צרכן."],["6619","205","<b>אתה בחרתנו מכל העמים</b>: תפלת העמידה ליו\"ט."],["6620","206","<b>ראשית</b>: א: ראש."],["6621","207","<b>הקליפות. . לקליפות</b>: א: הקליפה. . לקליפה."],["6622","208","<b>דמצרים. . כתר דקליפה</b>: ראה לקו\"ת — להאריז\"ל — ס\"פ שמות (עה\"פ ויאמר פרעה מי ה'). מאמרי אדה\"ז תקס\"ח ח\"א ע' תלג. מאמרי אדה\"א בראשית ע' רצט. ויקרא ח\"א ע' סה. וש\"נ. שה\"א לו, ב. לקמן קצא, ב הערה 357. וראה לעיל הערה 187."],["6623","209","<b>שאזלעו\"ז</b>: נסמן לעיל פ' שמות לד, ג."],["6624","210","<b>כתרין דמסאבותא</b>: ראה זהר (סבא) משפטים צד, ב. שמיני מא, ב. אחרי ע, א. (אד\"ר) נשא קמג, סע\"א וריש ע\"ב."],["6625","211","<b>ולכל</b>: א: דכל."],["6626","212","<b>אברהם יצא ממנו ישמעאל</b>: נסמן לעיל פ' בא קיז, ג."],["6627","213","<b>ישמעאל חסד דקליפה</b>: נסמן לעיל לא, א."],["6628","214","<b>ביצחק בחי' גבורות</b>: נסמן לעיל פ' וארא סא, ד."],["6629","215","<b>ביצחק. . יצא ממנו עשו</b>: נסמן לעיל פ' בא קיז, ג."],["6630","216","<b>עשו בחי' גבורות</b>: נסמן לעיל שם."],["6631","217","<b>דחו\"ב</b>: א: דכח\"ב."]]],[2300540458,"בלתי מורכב כלל בדבר מה אפי' ברצון וכ\"ש שאינו מורכב בשכל וטעם כו', ולנגד זה הוא עצם התענוג בנפש החומרי' שבלתי מורכב בטעם ורצון וחשק תאוה רעה כלל, והוא הנק' תענוג המפולש<sup data-n=\"6632\">218</sup> שפתוח ומפולש בנפש בלתי הרכבה כלל וכלל בדבר מה במציאות תענוג גשמי כתענוג הממון והמאכל והמשגל והכבוד והגדולה וכה\"ג כו', והוא קליפה דהוללות וליצנות ושחוק וקלות ראש שהתענוג הזה שבהוללות וליצנות הוא תענוג ושמחת הנפש בלתי מורכבת בדבר מה בתאוה גופני' וטבעי' כלל, שהרי כשהנפש תה[ו]לל בשחוק וליצנות כמו<sup data-n=\"6633\">219</sup> בכל מילי דליצנותא ובדיחותא הרי אין בזה שום תאוה גופני' כלל וכלל רק שישחוק וישמח לבו בהרחבת הנפש בלי<sup data-n=\"6634\">220</sup> מעצור לרוחו ודיבור[ו] כלל כמו שיגעון ממש לעשות מעשים ותנועות משונות כו', לפי שהוא רק פתיחת וז[ח]ות הלב והרוח שהוא ענין הפילוש שמפולש ופתוח ביותר מחמת תגבורת מרה הלבינה כידוע (בל\"א צו לאזין דיא הארץ [כו')], באין טעם ודעת כלל ובלא תשוקה וחמדת דבר מה כלל עד שאין ביכולת כלי מוחו ולבו לעצור רוחו והוא הנק' [רוח] הוללות וליצנות שמוכן הוא לכל תאוות רעות ממילא בלתי מניעה ועיכוב כלל וכמ\"ש אל תוכח לץ<sup data-n=\"6635\">221</sup> כו', כי טבע ההוללות וליצנות לעשות שחוק מכל דבר שבעולם ולא יקבל שום תוכחת מוסר כו' כמ\"ש דליצנותא א' דוחה ג' תוכחות<sup data-n=\"6636\">222</sup> ע\"כ מושב לצים קשה מדרך חטאים<sup data-n=\"6637\">223</sup> כו' בהיותו מקור לכל פר\"ע כו', לפי שהוא תענוג המפולש בעצם הנפש בהתפשטו' בלתי מוגבלת כלל כו' ולא יש דבר בעולם שיבטלנו כו' (וגם תענוגי' גשמי' שמורכבי' בטבע<sup data-n=\"6638\">224</sup> הנפש כמו לכל תאוות הון וכבוד ומשגל ומאכל יבוטלו לנגד תאוות השחוק וליצנות כמו שידוע בתענוגי השרים בטרטיאות שיעשו שחוק וליצנות והוללות כו'). והנה לנגד זה הוא בחי' תענוג העצמי' הפשוט ומפולש בעצם הנשמה שלמעלה מבחי' הרכבה גם לרצון וחשק ותשוקה אלקי' בדבר טעם ודעת כו' כמו שדוד הי' מפזז ומכרכר<sup data-n=\"6639\">225</sup> כו' בתנועות שונות וכמ\"ש ושחקתי לפני ה'<sup data-n=\"6640\">226</sup> כו'. וכמו\"כ מ\"ש אז ימלא שחוק פינו<sup data-n=\"6641\">227</sup> ולשוננו רינה והוא ענין שמחה וטוב לבב מרוב כל כו' במעשה המצות, וכמו ר\"ב דסמיך גאולה לתפלה<sup data-n=\"6642\">228</sup> לא פסק חוכא מפומא כו' שלמעלה הרבה מאה\"ר בתענוגי' כו' שמורכב ברצון ותשוקה בדבר מה כו' להיותו בבחי' עצמו' התענוג כמו חלל שהוא מפולש ופתוח לגמרי (טרם שבא להתענג על ה' ברצון וחכ' וטעם כו' כמובן מהיפך זה בתענוג והוללות הנ\"ל). וכמו\"כ הוא למעלה מ\"ש <span data-k=\"pg\">קעה</span> ּ לויתן זה יצרת לשחק בו<sup data-n=\"6643\">229</sup> וכן ותשחק ליום אחרון<sup data-n=\"6644\">230</sup> (שמפני זה הוא ענין הנבואה בנביאים בבחי' שגעון כמו שיגיון לדוד<sup data-n=\"6645\">231</sup> כו').",[["6632","218","<b>תענוג המפולש</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680121\" data-slug=\"torat-chaim\" data-id=\"2300680121\">תו\"ח תולדות קמג, ג</a>."],["6633","219","<b>כמו</b>: א: ליתא."],["6634","220","<b>בלי</b>: שם: באין."],["6635","221","<b>אל תוכח לץ</b>: משלי ט, ח."],["6636","222","<b><a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680152\" data-slug=\"torat-chaim\" data-id=\"2300680152\">דליצנותא א' דוחה ג</a>' </b>[א: ק]<b> תוכחות</b>: ראה גם ד\"ח ט, ג. תו\"ח תולדות קמד, א. מאמרי אדה\"א במדבר ח\"ד ע' א'תלז."],["6637","223","<b>מושב לצים קשה מדרך חטאים</b>: ראה ע\"ז יח, ב. תהלים א, א."],["6638","224","<b>בטבע</b>: א: בעצם."],["6639","225","<b>שדוד הי' מפזז ומכרכר</b>: נסמן לעיל פ' בא קה, ד."],["6640","226","<b>ושחקתי לפני ה'</b>: שמואל-ב ו, כא."],["6641","227","<b>אז ימלא שחוק פינו</b>: תהלים קכו, ב."],["6642","228","<b>ר\"ב דסמיך גאולה לתפלה</b>: ראה ברכות ט, ב. ראה גם מאמרי אדה\"א בראשית ע' רמב. במדבר ח\"ד ס\"ע א'תלו. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680137\" data-slug=\"torat-chaim\" data-id=\"2300680137\">תו\"ח תולדות קמג, ד</a> ובהערה 62."],["6643","229","<b>לויתן זה יצרת לשחק בו</b>: תהלים קד, כו."],["6644","230","<b>ותשחק ליום אחרון</b>: משלי לא, כה."],["6645","231","<b>שיגיון לדוד</b>: תהלים ז, א."]]],[2300540477,"<b>וזהו</b> ולא נחם אלקי' דרך ארץ פלשתים כו', דהנה בחי' פלשתים הוא מדת הליצנות<sup data-n=\"6646\">232</sup> והוללות לבד כו' כמ\"ש פלשתים לצנים היו<sup data-n=\"6647\">233</sup> כו', והוא ענין התענוג המפולש הנ\"ל שהוא מקור לכל פר\"ע הנ\"ל שמזה ודאי יפול הנופל ממילא בבחי' עומק רע שהוא עומק ההתקשרות תוקף הרצון דכל תאוה רעה שזהו קליפת מצרים כנ\"ל. והנה מ\"ש ולא נחם כו' היינו שלא נחם דרך ארץ פלשתים להכניע ולשבור לקליפה דפלשתים ע\"י בחי' המנגד לזה בסט' דקדושה, והוא בחי' התענוג העצמי ופשוט בסט' דקדושה שלמעלה גם מבחי' שמחה וטוב לבב שבעבודה [שבלב] באה\"ר [ב]תענוגי' או במעשה המצות שמורכב התענוג בדבר מה ברצון וחכ' [ש]בתו\"מ, אלא רק התפעלות עצם התענוג האלקי' כמו שהוא עד שיתפשט בלתי מעצור כלל שזהו כמו בחי' תענוג המפולש ופתוח בפתיחת הלב כנ\"ל בלתי מורכבת בדבר מה כלל כו' כי הוא [רק] מצד עצמות התענוג האלקי' לבד (וכמו דוד הי' מפזז כו' וכראב\"ש<sup data-n=\"6648\">234</sup> כו'). כי הנה יוכל להיות מזה נפילה שיפול בשמחה [ותענוג] וטוב לבב הזה בסט' דקליפה המנגד והוא בהוללות וליצנות ממש וכמו ויקומו לצחק<sup data-n=\"6649\">235</sup> כו'. והוא נראה בחוש לכל מתחילים בעבודת ה' שעדיין לא נתקשר נפשם ולבבם אל ה' א' ממש באמת מתוך תוך נקודת הלב, הגם שידמה בנפשו שיתפעל בעונג אלקי' בחדוה ושמחת הנפש בפתיחת הלב והרוח בלתי מורכבת ומוגבלת כלל עד שלא נעצר רוחו ולבו כלל (בל\"א ער קען זיך ניט איין האלטין) עד שיבא לידי שחוק, כמו ר\"ב דלא פסיק חוכא מפומא כו' אבל ר\"ב זה הי' בדיחא דעתו והי' מלא שחוק רק מחמת שסמך גאולה כו'. אבל מצד שאין התקשרות אהבה זו בתענוגי' זה אמיתי הרי נפסקת מיד ולא נעשה מזה שום מעשה ועבודה אלקי' כלל וכלל רק נשארה השחוק כמו שהוא מסט' דקליפה שהוא קלות ראש והוללות ממש (וכמו שמצינו<sup data-n=\"6650\">236</sup> זה בכל איש שמטעה א\"ע בזה מאד). וגם במי שהתחלת התענוג הוא בד\"ת הנגלה והנסתר כמו ונשמח בד\"ת<sup data-n=\"6651\">237</sup> וכר\"ש שא' חדאי נפשאי<sup data-n=\"6652\">238</sup> כו' יכול לבוא אח\"כ לשחוק וז[ח]ות הלב וגבהות כראב\"ש שהי' דעתו זחה לפי שלמד תורה הרבה כו' וא' כמה מכוער כו' וכ\"ש בקטני ערך שיפול הנופל כו'. משא\"כ כשהתענוג האלקי הוא בדבר מה כמו בקיום רצה\"ע במצות בפו\"מ שנק' שמחה ש\"מ או באה\"ר בתענוגי' שבלב ומוח כו' לא יפול הנופל בשחוק וקלות ראש וכ\"ש שלא יבא לפר\"ע להתמשך אחר עומק רע כו' וד\"ל. וז\"ש ולא נחם כו' כי קרוב הוא לארץ מצרים וכשיראו מלחמה לבער הרע מק\"נ שהוא מז' מדות הרעות לא י[ו]כלו לעמוד כלל כי יפול הנופל בהוללות וליצנות כנ\"ל שקרוב הוא לקליפה דעומק רע דמצרים ויאמרו לשוב למצרים כו', וכמ\"ש לא יתייצבו הוללים<sup data-n=\"6653\">239</sup> לנגד עיניך כו' לפי שמנגדים",[["6646","232","<b>פלשתים. . הליצנות</b>: ראה מאמרי אדה\"א בראשית ע' רמב. וש\"נ."],["6647","233","<b>פלשתים לצנים היו</b>: ראה ע\"ז יט, א."],["6648","234","<b>וכראב\"ש</b>: תענית כ, סע\"א ואילך. ראה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680196\" data-slug=\"torat-chaim\" data-id=\"2300680196\">תו\"ח תולדות קמד, ד</a>."],["6649","235","<b>ויקומו לצחק</b>: תשא לב, ו."],["6650","236","<b>שמצינו</b>: א: שמצוי."],["6651","237","<b>ונשמח בד\"ת</b>: ברכת ק\"ש ערבית."],["6652","238","<b>וכר\"ש שא' חדאי נפשאי</b>: פסחים סח, סע\"ב."],["6653","239","<b>לא יתייצבו הוללים</b>: תהלים ה, ו."]]],[2300540495,"גמורים הן לבחי' העבודה [ה]אלקי' ובפרט לקבלת התו\"מ וכמ\"ש ובמושב לצים<sup data-n=\"6654\">240</sup> לא ישב כ\"א בתו' [ה']<sup data-n=\"6655\">241</sup> כו' (וכמ\"ש בס' ד\"ח<sup data-n=\"6656\">242</sup> ).\n(וי\"ו) <b>ועוי\"ל</b> כי קרוב הוא הדרך לבא לא\"י ארץ זבת חלב ודבש<sup data-n=\"6657\">243</sup> כו' אלא הסיבם <span data-k=\"pg\">352</span> ּ דרך המדבר כו', כי תענוג המפולש הנ\"ל הוא בפנימי' הכתר דקליפה שקרוב הוא לבחי' פנימיות דכתר דקדושה וצריך שיבאו למדרגה דא\"י בהדרגה מלמטלמ\"ע דרך המדבר דוקא (כמשי\"ת). והנה כדי שיוכלו בנ\"י לקבל התו\"מ ביסוד מוסד בלי נפילה בקליפה דרצון ותענוג זר זולת לה' לבדו ולא די שלא נחם דרך ארץ פלשתים כי קרוב הוא כו' כנ\"ל, הנה הסיבם והקיפם דרך המדבר י\"ס<sup data-n=\"6658\">244</sup> כמ\"ש ויסב אלקים את העם דרך<sup data-n=\"6659\">245</sup> כו'. דהנה מבואר למעלה בענין הזריעה בעפר שגורם הצמיחה בכפליי' לאין שיעור כו' מטעם רקבון החטה כו', וכך הוא בענין הזריעה דנש\"י בגופים להיות משועבדים תחת ממשלת ע\"ס<sup data-n=\"6660\">246</sup> דנוגה דעשי' שמקורם הכללי הוא במדבר שנק' מדבר העמים<sup data-n=\"6661\">247</sup> כידוע ומבואר במ\"א שהן המזלות<sup data-n=\"6662\">248</sup> שע\"י עובר השפע חיי גופני בפרנסה כו' כנ\"ל, ועי\"ז נעשה רקבון הניצוץ אלקי אחר שיזכור על ה' שהוא מקור האמיתי כו' כנ\"ל יבא לכלל מרירות והכנעה עצומה קודם התפלה שהוא ענין כובד ראש שלפני התפלה<sup data-n=\"6663\">249</sup> (וז\"ש הרוצה לקבל עליו עומ\"ש<sup data-n=\"6664\">250</sup> שלימה יפנה כו' לנקות א\"ע מהתקשרות בהבלי עוה\"ז שהן בחי' פסולת דפסולת שנפלו מלמעלה כו' וכמ\"ש במ\"א ע\"פ ונשב בגיא<sup data-n=\"6665\">251</sup> מול בית פעור כו', וזהו יפנה כו')<sup data-n=\"6666\">252</sup> ע\"י ההכנעה והמרירות במה שנפרד מיחודו ית' ברוח נשברה מאד שבזה יפול התקשרות נפשו בגסות וחומריות החיות הגופני ויוכל לקבל עליו עומ\"ש כו', דהיינו להיות לו רק לב א' לאביו שבשמים<sup data-n=\"6667\">253</sup> ויקבל עומ\"ש ברצון שלם שלא יהי' עבד לאדונים זרים זולתו רק מ\"ש לבד כו' שזהו נק' מ\"ש שלימה וכנ\"ל. וזהו שהיו חסידים הראשוני' שוהין שעה א'<sup data-n=\"6668\">254</sup> ואח\"כ מתפללים כו' כי בשעה זו הי' מנק[ים] א\"ע מכל סיג ותערובות התקשרות כל רצונות זרות שלא לה' המה כו' ועי\"ז יהי' קבלת מ\"ש שלימה דוקא. וזהו מ\"ש מי זאת עולה מן המדבר<sup data-n=\"6669\">255</sup> שהיא עלי' דכנס\"י מע\"ש דנוגה ששרשם במדבר העמים והוא בברכת",[["6654","240","<b>ובמושב לצים</b>: תהלים א, א."],["6655","241","<b>כ\"א בתו' [ה']</b>: תהלים שם, ב."],["6656","242","<b>וכמ\"ש בס' ד\"ח</b>: ט, ב ואילך."],["6657","243","<b>ארץ זבת חלב ודבש </b>[א: ב' תיבות האחרונות ליתא]: שמות ג, ח."],["6658","244","<b>י\"ס</b>: א: ים סוף."],["6659","245","<b>ויסב אלקים את העם דרך </b>[א: ליתא]: בשלח יג, יח."],["6660","246","<b>ע\"ס</b>: א: ע\"ש ע' שרים. וכ\"ה במאמרי אדה\"ז כאן (ע' קמט)."],["6661","247","<b>מדבר העמים</b>: יחזקאל כ, לה. ראה מאמרי אדה\"ז תקס\"ז ע' קצב. תקס\"ח ח\"א ע' שנה."],["6662","248","<b>שהן המזלות</b>: ראה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670093\" data-slug=\"torat-chaim\" data-id=\"2300670093\">תו\"ח נח נט, ד</a> ובהערה 56."],["6663","249","<b>כובד ראש שלפני התפלה</b>: ראה ברכות ל, ב."],["6664","250","<b>הרוצה לקבל עליו עומ\"ש</b>: ברכות יד, סע\"ב ואילך."],["6665","251","<b>ונשב בגיא</b>: ואתחנן ג, כט. ראה ד\"ה זה במאמרי אדה\"ז הקצרים ע' קט. תקס\"ה ע' ד [נביאים ע' רכב. ענינים ע' סב]. מאמרי אדה\"א דברים ח\"א ע' קנ. וש\"נ."],["6666","252","<b>כו')</b>: תוקן ע\"פ א. ובתו\"ח: בין."],["6667","253","<b>לב א' לאביו שבשמים</b>: ברכות נז, א."],["6668","254","<b>חסידים הראשוני' שוהין שעה א'</b>: ברכות ל, ב."],["6669","255","<b>מי זאת עולה מן המדבר</b>: נסמן לעיל פ' בא קכב, ד."]]],[2300540513,"שלא עשני גוי ועבד<sup data-n=\"6670\">256</sup> כו' כמ\"ש במ\"א, ואח\"כ יפה כלבנה בפסוד\"ז ברה כחמה<sup data-n=\"6671\">257</sup> בק\"ש כו' וד\"ל.\n<b>וזהו</b> ויסב אלקי' את העם דרך המדבר דוקא והתו' נצחית היא<sup data-n=\"6672\">258</sup> בכל דור [ודור] ובכל זמן שהאבות סימן לבנים<sup data-n=\"6673\">259</sup>, שע\"י שהקיפו דרך מדבר העמים יוכלו להיות בחי' עלי' דכנס\"י מן המדבר העמים בכל דור ובכל זמן קו\"ה<sup data-n=\"6674\">260</sup> בבחי' כור<sup data-n=\"6675\">261</sup> כנ\"ל בהיותם בגלות בע\"ש דק\"נ [כנ\"ל], שעי\"ז יהי' יסוד לקבלת עומ\"ש שלימה בתו\"מ בלי שום נפילה עוד ברצון ותענוג זר גם בהיותם טרודי' בעסקיהם כו'. והוא מטעם הנ\"ל שזריעה זאת גורמת הצמיחה זאת בכפלי כפליים וכמ\"ש למעלה בענין ראשית תבואתו וכמ\"ש אז יאמרו בגוים דוקא הגדיל ה' כו' והוא הצומחי'<sup data-n=\"6676\">262</sup> דאור תו\"מ בכל דור כו' ע\"י הרקבון הניצוץ במרירות כנ\"ל וד\"ל (ואע\"פ שהמדבר הוא ארץ לא זרועה ששם העדר כל שפע גשמי' ונש\"י נזרעי' תחת הע\"ש דק\"נ באופן שיצמחו כנ\"ל, הנה ידוע דמדבר העמים הוא מקור כל ק\"נ שיתפשטו בכל הארץ וכמ\"ש בזהר על ענין שילוח השעיר לעזאזל המדברה, והיינו ג' קליפות הטמאות נחש שרף ועקרב<sup data-n=\"6677\">264</sup> כו' שבמ\"ב מסעות בארון<sup data-n=\"6678\">265</sup> ושכינה והוכנעו<sup data-n=\"6679\">266</sup> למקור עומק רע להיות מזה כח לכנס\"י בכח<sup data-n=\"6680\">267</sup> סו\"מ גמור וכמ\"ש במ\"א בענין לא זרועה דשס\"ה ל\"ת דלאו קודם <span data-k=\"pg\">קעו</span> ּ להן דמ\"ע כו'). ומ\"ש דרך המדבר י\"ס דוקא שאע\"פ שהכוונה הוא כמו שמפרש ואמר פרעה נבוכים הם<sup data-n=\"6681\">269</sup> כו' ורדף<sup data-n=\"6682\">270</sup> כו', עכ\"ז הענין הוא משום די\"ס הוא בחי' סופא דכ\"ד<sup data-n=\"6683\">271</sup> דאצי' והוא בחי' מ\"ש שלימה כנ\"ל. דהנה תושבע\"פ מל' קרינן לה הוא ים החכ' העליונה שיצא[ה ב]גילוי רצון וגזירת מלך לעשות כך ולא כך כמאמר מתניתין מל'<sup data-n=\"6684\">272</sup>, שבהיות האדם לומד ד\"ה<sup data-n=\"6685\">273</sup> אינו אלא כאור מקיף דמל'<sup data-n=\"6686\">274</sup> בבחי' ביטול מופלג בעצמותו רק כשמוע רבו המלך<sup data-n=\"6687\">275</sup> זה כשר וזה פסול כו', וכמ\"ש ודברי אשר שמתי בפיך<sup data-n=\"6688\">276</sup> כו' וכמו תען לשוני אמרתיך<sup data-n=\"6689\">277</sup> כו' שאינו אלא כלי ושילוח לדבר דבר המלך, [ו]ע\"כ נק' ת\"ח מלכים ושרים שרי התו'<sup data-n=\"6690\">278</sup> כשרי המלוכה ואומר גזירותיו<sup data-n=\"6691\">279</sup> ורצון המלך ע\"כ יש יכולת בידם לגמור אופן רצון המלך כרצונם וכמ\"ש [במשה] בכל ביתי נאמן הוא<sup data-n=\"6692\">280</sup> כו' וכמ\"ש",[["6670","256","<b>בברכת שלא עשני גוי ועבד</b>: ראה לעיל פ' וארא עד, ב."],["6671","257","<b>יפה כלבנה. . ברה כחמה</b>: נסמן לעיל פ' בא קכב, ד."],["6672","258","<b>והתו' נצחית היא</b>: נסמן לעיל פ' שמות א, א."],["6673","259","<b>שהאבות סימן לבנים</b>: נסמן לעיל פ' וארא עז, ד."],["6674","260","<b>קו\"ה</b>: א: קודם התפלה."],["6675","261","<b>כור</b>: א: כובד ראש."],["6676","262","<b>הצומחי'</b>: א: הצמיחה."],["6677","264","<b>ג' קליפות הטמאות נחש שרף ועקרב</b>: עקב ח, טו. ראה לקמן פ' ויקהל תכג, ד. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380388\" data-slug=\"likkutei-torah\" data-id=\"4001380388\">לקו\"ת נשא כ, א</a> (ובהנסמן במ\"מ לשם). מאמרי אדה\"ז תקע\"א ע' רכז. שע\"ת ד, ב ובהערה 19."],["6678","265","<b>שבמ\"ב מסעות בארון</b>: ראה דרושי אלה מסעי הב' והג' בלקו\"ת. מאמרי אדה\"א במדבר ח\"א ע' קסז ואילך ובהנסמן שם."],["6679","266","<b>והוכנעו</b>: א: הוכניעו. ואוצ\"ל: הכניעו."],["6680","267","<b>בכח</b>: א: בבחי'."],["6681","269","<b>ואמר פרעה נבוכים הם</b>: בשלח יד, ג."],["6682","270","<b>ורדף</b>: בשלח שם, ד."],["6683","271","<b>די\"ס. . סופא דכ\"ד</b>: ראה זהר בשלח נו, א. (רע\"מ) פינחס רנו, ב."],["6684","272","<b>מתניתין מל'</b>: ביצה כח, ב."],["6685","273","<b>ד\"ה</b>: א: דבר הלכה."],["6686","274","<b>כאור מקיף דמל'</b>: א: כאומר דבר מל'."],["6687","275","<b>כשמוע רבו המלך</b>: א: כמשמיע גזירת דבר מלך."],["6688","276","<b>ודברי אשר שמתי בפיך</b>: ישעי' נט, כא."],["6689","277","<b>תען לשוני אמרתיך</b>: תהלים קיט, קעב."],["6690","278","<b>ת\"ח. . שרי התו'</b>: נסמן לעיל פ' שמות י, ד הערה 481."],["6691","279","<b>ואומר גזירותיו</b>: א: שאומרים גזירת."],["6692","280","<b>בכל ביתי נאמן הוא</b>: נסמן לעיל פ' שמות י, ד."]]],[2300540531,"אתם אפי'<sup data-n=\"6693\">281</sup> כו' וכמ\"ש במ\"א. ונמצא ע\"י לימוד התורה נעשה בית קיבול למ\"ש העליונה דמל' דאצי' שבתושבע\"פ כו'. וזהו הנק' מ\"ש שלימה [רק קודם התפלה בשומו הטלית שהוא פרישו דמלכות שמים<sup data-n=\"6694\">282</sup> דלעילא כמו שום תשים עליך מלך<sup data-n=\"6695\">283</sup> כו' היינו רק התחלת הקבלה של מ\"ש שלימה] הזאת, והוא ע\"י מרירות והכנעת הלב ביותר כנ\"ל שנעשה בחי' כלי ריקן אמיתי להיות מחזיק בחי' מ\"ש בתכלית הקבלה והוא רק לקיים מצות המלך לבטל כל רצונו נגד רצונו כמו בטל רצונך<sup data-n=\"6696\">284</sup> כו', והוא בחי' מדת מל' בחיצוני' שנק' מצות המלך לקיים מצותו<sup data-n=\"6697\">285</sup> בלבד ואח\"כ אחר התפלה יהי' בית קיבול פנימי' מ\"ש שבדבר המלך בגזירת רצונו כשמדבר דבר ה' זו הלכה<sup data-n=\"6698\">286</sup> שהוא כמצוה בשם המלך ממש בביטול גדול כנ\"ל. וזהו והתו' והמצוה כו' תושב\"כ ותושבע\"פ<sup data-n=\"6699\">287</sup> כו' אבל מצוה דתושבע\"פ נמשך ע\"י קבלת עומ\"ש בתחלה בעטיפת הטלית דוקא וד\"ל.\n(ז) <b>והנה</b> הגם שבתו\"מ<sup data-n=\"6700\">288</sup> המלך הנ\"ל שהיא בחי' מל' בקבלת מ\"ש שלימה בחיצוני' ובפנימי' קודם התפלה בעטיפת הטלית ואח\"כ התפלה בלימוד תושבע\"פ מל' קרינן לה כו' הרי נק' י\"ס סופא דכ\"ד שבאצי' כו', ועכ\"ז הרי יש בזה דוקא מבחי' תחל[ו]ת כל התחל[ו]ת דפנימי' הכתר בכלל וכמאמר נעוץ תחב\"ס וסוב\"ת<sup data-n=\"6701\">289</sup> כו' דוקא וכמ\"ש סוף דבר<sup data-n=\"6702\">290</sup> כו' את האלקי' ירא ב[קבלת] מ\"ש שלימה בתושבע\"פ ואת מצותיו שמור לקיים מצות המלך כו' כי זה כל האדם דוקא מבחי' בעה\"ר שנק' תחילת הכל שמשם נמשך פנימי' הרצון והתענוג שבמהו\"ע ממש והוא ענין עושי רצונו כו' כנ\"ל במ\"ש לעושי רצונו עאכו\"כ כו'. והטעם הוא כידוע בענין [מדריגות] דו\"ר ורו\"ד<sup data-n=\"6703\">291</sup> שיו\"ד דיר\"ע מקבל מסוף הכל דחילו תתאה דהכנעה וביטול הרצון בק[עו]מ\"ש היא העולה למעלה [מ]פנימי' הרצון שנמשך מבעה\"ר, וראי' ממ\"ת כשאמר[ו] <sup data-n=\"6704\">292</sup>נעשה שמזה נמשך גילוי אור בפנימי' הרצון והתענוג באנכי<sup data-n=\"6705\">293</sup> כו' (והוא מ\"ש נאום דוד בן ישי<sup data-n=\"6706\">294</sup> הקים עול<sup data-n=\"6707\">295</sup> כו' שנק' כתר ש\"ט שעולה על ג' הכתרים<sup data-n=\"6708\">296</sup> דכתר תו' וכתר כהונה וכתר מל'. וז\"ש אז ראה ויספרה<sup data-n=\"6709\">297</sup> כו' עד ויאמר לאדם<sup data-n=\"6710\">298</sup> הן יראת ה' היא חכ' כו'<sup data-n=\"6711\">299</sup> וסו\"מ בינה, וע\"כ א' ועתה ישראל מה ה' אלקיך שואל מעמך כ\"א ליראה<sup data-n=\"6712\">300</sup> כו') וד\"ל.\n<b>ובכ\"ז</b> יובן מ\"ש ולא נחם אלקים דרך ארץ פלשתים כו', דהנה יש דרך קרובה ביותר לבא למדרגה לפנימי' הכתר",[["6693","281","<b>אתם אפי'</b>: ר\"ה כה, א."],["6694","282","<b>הטלית שהוא פרישו דמלכות שמים</b>: ראה זהר (סבא) משפטים צז, ב. הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"ב לע' תרמא. מאמרי אדה\"א במדבר ח\"ג ע' א'רפ לע' א'מד."],["6695","283","<b>שום תשים עליך מלך</b>: פ' שופטים יז, טו."],["6696","284","<b>בטל רצונך</b>: אבות פ\"ב, מ\"ד."],["6697","285","<b>מצותו</b>: א: כל מצותיו."],["6698","286","<b>דבר ה' זו הלכה</b>: עמוס ח, יב. שבת קלח, ב."],["6699","287","<b>והתו' והמצוה. . תושב\"כ ותושבע\"פ</b>: נסמן לעיל פ' שמות יז, א הערה 707."],["6700","288","<b>שבתו\"מ</b>: א: שבחי' מצות."],["6701","289","<b>תחב\"ס וסוב\"ת</b>: ראה ס\"י פ\"א, מ\"ז."],["6702","290","<b>סוף דבר</b>: קהלת יב, יג."],["6703","291","<b>דו\"ר ורו\"ד</b>: ראה זהר (רע\"מ) נשא קכג, סע\"א. מאמרי אדה\"א בראשית ע' לד. וש\"נ. שע\"ת כו, א ובהערה 4."],["6704","292","<b>נעשה</b>: יתרו יט, ח. משפטים כד, ג. ז."],["6705","293","<b>באנכי</b>: יתרו כ, ב."],["6706","294","<b>נאום דוד בן ישי</b>: שמואל-ב כג, א [בדילוג]."],["6707","295","<b>הקים עול</b>: א: הוקם על."],["6708","296","<b>כתר ש\"ט שעולה על ג' הכתרים</b>: אבות פ\"ד, מי\"ג."],["6709","297","<b>אז ראה ויספרה</b>: איוב כח, כז."],["6710","298","<b>ויאמר לאדם</b>: שם כח, כח."],["6711","299","<b>כו'</b>: א: ליתא."],["6712","300","<b>ועתה ישראל. . ליראה</b>: עקב י, יב."]]],[2300540549,"שהוא פנימי' התענוג והרצה\"ע שבעצמו' בעה\"ר והתענוג כו', והוא ע\"י התלהבות אה\"ר בתענוגי' הבאה ממילא ומאליה להיות בשמחה ובטוב לבב להתענג על ה' בבחי' תענוג עצמי' שבעצמו' הנפש ממש כנ\"ל שהוא נק' תענוג מפולש בתענוג פשוט בעצמו' ממש שבא רק מצד [עצמות] אלקו' בלבד, וזה ביכולת כל ניצוץ לימשך בהתפעלו' התלהבות התענוג <span data-k=\"pg\">354</span> ּ האלקי בלתי שום יגיעה ועבודה במוח ולב [ולא] מצד מעשה המצות כו' שנק' שמחה ש\"מ<sup data-n=\"6713\">302</sup> להיותה למעלה גם מתענוג המורכב ברצון וחכ' שבתו\"מ כנ\"ל באורך. ולפי דרך זה א\"צ כלל לעבודה האלקי' בתו\"מ לקבלת עומ\"ש ועול מצות בפו\"מ כלל, ולא בזה חפץ ה' כי לא בדרך זה ישכון אור פנימי' הרצה\"ע [כ\"א] שיהי' גילוי אלקות ע\"י תו\"מ ועבודה אלקי' באוי\"ר כו', שלזה הי' עיקר המכוון בתחלת המח' בסוף מעשה דוקא, ולזה העלם ממצרים לקרבם לה\"ס<sup data-n=\"6714\">303</sup> לקבלת תו\"מ באהבה ורצון בקבלת עומ\"ש דוקא ומשום דנעוץ תחב\"ס דוקא כנ\"ל. וגם מטעם שני כמו שמפרש כי קרוב הוא והי' בראותם מלחמה כו' דהיינו שקרוב לארץ מצרים (ופי' הב' כי קרוב הוא לא\"י כו'), שיפול הנופל מזה לקליפות דהוללות וליצנות בפני'<sup data-n=\"6715\">304</sup> לגמרי שהוא קליפות דפלשתים שזהו המנגד ממש לעומ\"ש דתו\"מ כו', וע\"כ לא נחם אלקי' בעלותם מנש\"ט דמצרים דרך ארץ פלשתים כי קרוב הוא, פי' כי קרוב דרך זה יותר לבא למדרגות דא\"י פנימי' התענוג והרצון (שזהו מכתר דק\"נ לכתר דקדושה), אבל בראותם מלחמה לא יעמדו בה להלחם נגד הרע דקליפה כלל וכנ\"ל, ועיקר המכוון לברר לעה\"ד טו\"ר ע\"י קבלת מ\"ש בתו\"מ בסו\"מ וע\"ט כנ\"ל. ולזה ויסב אלקי' את העם דרך המדבר כו', שהשפילם למטה מטה שיהי' התחלת העבודה האלקי' בסוף כל המדרגות דוקא לילך אחרי ה' דרך המדבר. כמ\"ש זכרתי לך כו' לכתך אחרי במדבר בארץ לא זרועה<sup data-n=\"6716\">305</sup> שהוא להכניע קליפות קשות דרע גמור של מדבר העמים ע\"י מרירות והכנעה בכובד ראש<sup data-n=\"6717\">306</sup> כנ\"ל כדי לקבל עומ\"ש שלימה בקיום מצות המלך בטלית ובפנימי' הקבלה בלימוד תושבע\"פ כו', שזהו דרך המדבר י\"ס סופא דכ\"ד כו' מפני שבחי' סוף הכל דקבלת עומ\"ש ע\"י הכנעה דוקא יגיע ויעלה בהדרגה מתחתון לעליון עד שיעלו ויגיעו לבחי' שמחה וטוב לבב בפנימי' התענוג והרצון ע\"י אמצעי' העבודה אלקי' באוי\"ר דוקא עד אה\"ר בתענוגי' שמצד מעשה המצוה שמורכב ברצון וחכ' שבתו\"מ דוקא, שזהו הי' הענין קבלת התורה שעכ\"ד<sup data-n=\"6718\">307</sup> כו' ועכשיו הוא שמחה ש\"מ דוקא כנ\"ל בפי' תחת אשר לא עבדת [את ה']",[["6713","302","<b>ש\"מ</b>: של מצוה."],["6714","303","<b>לה\"ס</b>: א: להר סיני."],["6715","304","<b>בפני'</b>: א: בפריקת עול."],["6716","305","<b>זכרתי. . בארץ לא זרועה</b>: ירמי' ב, ב."],["6717","306","<b>בכובד ראש</b>: א: בסור מרע."],["6718","307","<b>שעכ\"ד </b>[א: פרחה נשמתן]: נסמן לעיל פ' וארא סט, א."]]],[2300540566,"בשמחה ובתו\"מ<sup data-n=\"6719\">308</sup> כו' וד\"ל. וזהו ענין ההקפה דרך המדבר י\"ס להיות מזה ההיקף קי\"ס וע\"י שבתחלה ירדוף פרעה אחריהם ויצעקו אל ה' בצר להם<sup data-n=\"6720\">309</sup> כו' וכמ\"ש ופרעה הקריב<sup data-n=\"6721\">310</sup> הקריב [לבם] לאביהם שבשמים כו' (לפי שהיו ישראל באו ביבשה בתוך הים שהוא בחי' העלי' דכנס\"י ממש לאין<sup data-n=\"6722\">311</sup> האלקי (וכידוע בענין קי\"ס שארץ הוא עלמא דאתגליא וים הוא עלמא דאתכסיי'<sup data-n=\"6723\">312</sup> כו' ונעשה מהעלם דים גילוי [דיבשה] ומגילוי <sup data-n=\"6724\">313</sup>דים להעלם בב' אופנים<sup data-n=\"6725\">314</sup> כמ\"ש במ\"א) שזה הי' הקדמה והכנה למ\"ת דוקא, לפי שקי\"ס הוא בחי' התחתונה שנק' סופא דכ\"ד כו' ונתחב\"ס שהוא גילוי עצמו' התענוג ורצון במ\"ת כו' שזהו לפי שהי' נסב\"ת בקי\"ס כו' וד\"ל. ולפ\"ז מובן שד\"ז<sup data-n=\"6726\">316</sup> שהסיבם במדבר י\"ס הוא העלי' בהדרגה ממל' לכתר נק' בשם דרך ארוכה וקצרה ודרך הקרוב דרך ארץ פלשתים נק' דרך קצרה וארוכה כו' (שהוא מכתר לכתר שהוא דרך קצרה אבל ישובו אחור כו' כנ\"ל).\n<b>והנה</b> כ\"ז שהסיבם דרך המדבר י\"ס עד הר חורב הי' הכנה למ\"ת לבד אך ממ\"ת עד ביאתם לארץ הי' רק הכנה לבא לא\"י שנק' זבת חלב ודבש ארץ טובה ורחבה<sup data-n=\"6727\">317</sup> <span data-k=\"pg\">קעז</span> ּ כו', וזהו פלא גדול לכאורה דלפ\"ז גדולה מעלת א\"י ממ\"ת אחר שהי' הכנה רבה יותר לביאת א\"י מהכנה דמ\"ת (שעד מ\"ת לא הי' נסיעתם רק מט\"ו ניסן עד וא\"ו סיון וממ\"ת עד ביאת א\"י נסעו מ' שנה). אך הענין הוא דבאמת הגם שבמ\"ת היו כנס\"י במעלה ומדרגה עליונה ביותר בגילוי אור פב\"פ בפנימי' התענוג והחכ' כו' שהרי נגלה עליהם ה' בכבודו ובעצמו ממש באמרו אנכי כו' ועכ\"ד פרחה נשמתן כו' מרוב עוצם תגבורת התענוג ושמחה וטוב לבב דוקא כו', עכ\"ז יש בא\"י מעלה יתירה הרבה יותר ממ\"ת (וכמ\"ש אלו קרבנו כו' עד והכניסנו לא\"י שהוא המעלה העליונה יותר כו'), כידוע שיש ב' מדרגות בתענוג א' עונג המורגש ברצון וחכ' שגם שהוא בחי' פנימי' התענוג ורצון וחכ' כמו חכמת אדם תאיר פניו<sup data-n=\"6728\">319</sup> כי באור פניך נתת לנו<sup data-n=\"6729\">320</sup> כו', ה\"ז בחי' פנימי' שברצון ותענוג שבחכמה דתו\"מ לבד וע\"כ הי' עכ\"פ התפעלות התענוג האלקי' במורגש שיש מי שמתפעל כו' בהתפעלות אה\"ר בתענוגי' כו',",[["6719","308","<b>ובתו\"מ</b>: א: ליתא."],["6720","309","<b>ויצעקו אל ה' בצר להם</b>: תהלים קז, ו. כח."],["6721","310","<b>ופרעה הקריב</b>: בשלח יד, י. ראה שמו\"ר פכ\"א, ה. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670125\" data-slug=\"torat-chaim\" data-id=\"2300670125\">תו\"ח נח ס, ב</a> הערה 24."],["6722","311","<b>ממש לאין</b>: א: מאין ליש."],["6723","312","<b>שארץ הוא עלמא דאתגליא וים. . דאתכסיי'</b>: ראה לקמן קלט, א. קמג, ד. קנג, ב. קסח, ג. פ' פקודי תנט, ג. מאמרי אדה\"א שמות ח\"א ע' חצר. הנחות תקע\"ז ע' נה ובהנסמן בהנ\"ל. שה\"א לב, ב ובהערה 15. 14."],["6724","313","<b>דים</b>: א: ליתא."],["6725","314","<b>בב' אופנים</b>: ראה גם לקמן קפב, ג. וש\"נ."],["6726","316","<b>שד\"ז</b>: א: שדור זה."],["6727","317","<b>ארץ טובה ורחבה</b>: שמות ג, ח."],["6728","319","<b>חכמת אדם תאיר פניו</b>: קהלת ח, א."],["6729","320","<b>כי באור פניך נתת לנו</b>: סיום תפלת העמידה."]]],[2300540582,"אבל אין זה ערך לגבי בחי' פנימי' התענוג שבעצמו' א\"ס ב\"ה ממש שנק' שעשוע[י] המלך שמצד עצמו ממש כו' שמשם נמשך השעשועי' שבתורה כמ\"ש בתו' ואהי' אצלו אמון כו' שעשועי'<sup data-n=\"6730\">321</sup> כו' וכן אני תורתך שעשעתי<sup data-n=\"6731\">322</sup> כו' כידוע. וההפרש ביניהם הוא רק במה שבבחי' עצמיות התענוג ממש הוא בבחי' ביטול גדול מאד שאין בו בחי' הרגשת העונג כלל וכלל להיות בחי' הביטול מן העצמו' לגמרי מכל וכל והוא בחי' עונג הנעלם כו'. וזה הי' מדרגת א\"י דוקא שבקיום המצות התלוים בארץ כמ\"ש כי תבאו אל הארץ<sup data-n=\"6732\">323</sup> שם הוא עיקר עצמו' התענוג הנעלם שבמהו\"ע ממש לפי שנעוץ תחלת כל [ה]התחלת בסו\"מ בארץ דוקא, ולכך נק' ארץ חפץ<sup data-n=\"6733\">324</sup> כו', ארץ אשר ה' אלקיך דורש אותה עיני ה' אלקיך בה<sup data-n=\"6734\">325</sup> כו', וע\"כ הי' משה משתוקק ביותר לבא לא\"י כמ\"ש ואתחנן<sup data-n=\"6735\">326</sup> כו' אעברה נא ואראה [כו'] את ההר הטוב הזה<sup data-n=\"6736\">327</sup> כו', וזהו דוקא בקיום המצות בארץ בפו\"מ<sup data-n=\"6737\">328</sup> בארץ דוקא (וכמ\"ש אל יתהלל<sup data-n=\"6738\">329</sup> כו' כ\"א לעשות חסד<sup data-n=\"6739\">330</sup> כו' בארץ דוקא כי באלה חפצתי כו'), שמ\"ת לא הי' רק קבלת הרצון ותענוג לעשות ולקיים המצות אבל לא הי' עדיין [ה]מעשה בפו\"מ רק בא\"י. וע\"כ גדלה מעלת ביאת הארץ להיות לזה הכנה רבה ביותר והוא הנסיעה במדבר זמן רב וביסורים רבים כ\"כ כמ\"ש ויענך וירעיבך<sup data-n=\"6740\">331</sup> כו', כי לפ\"ע מעלת התענוג כן ערך היסורים מקודם לפום צערא אגרא<sup data-n=\"6741\">332</sup> כו' וכמא' ג' דברים באים ע\"י יסורים<sup data-n=\"6742\">333</sup> תו' וא\"י ועוה\"ב, הרי ג' מדרגות הן זו למעלה מזו תו' ואח\"כ א\"י ולמעלה מא\"י הוא עוה\"ב שהוא העדן [ש]עין לא ראתה כו', והיינו שגם בחי' התענוג העצמו' ממש בא בגילוי במורגש כמ\"ש להנחיל אוהבי יש<sup data-n=\"6743\">335</sup> ממש וכמ\"ש ונחי' לפניו ממש. ועכ\"ז במרירות קשה באורך זמן הגלות לבד הוא בתכלית הביטול דוקא<sup data-n=\"6744\">336</sup> לפי שהגילוי וההעלם שוין ממש כו' וכמ\"ש במ\"א, וזהו בא בשכר ע\"י מעשה המצות בעוה\"ז בקבלת עומ\"ש דוקא כו' מטעם הנ\"ל (דנתב\"ס וסוב\"ת כו') וד\"ל. אך א\"י קודם הבירור נק' ארץ כנען בסט' דקליפה והוא חם אבי <span data-k=\"pg\">356</span> ּ כנען תכלית הגסות וחומרי' בעונג המו\"מ אבל<sup data-n=\"6745\">338</sup> מרגיש בעצמו כלל, והוא למעלה מעונג ורצון דקליפה נש\"ט דמצרים שהוא העונג המורגש בכל תאוות רעות. וז\"ש וחברון שבע שנים<sup data-n=\"6746\">339</sup> [נבנתה לפני] כו' הוא קרית ארבע אדם הגדול בענקים<sup data-n=\"6747\">340</sup> כו' לפני",[["6730","321","<b>ואהי' אצלו. . שעשועי'</b>: משלי ח, ל."],["6731","322","<b>אני תורתך שעשעתי</b>: תהלים קיט, ע."],["6732","323","<b>כי תבאו אל הארץ</b>: בא יב, כה. אמור כג, י. בהר כה, ב."],["6733","324","<b>ארץ חפץ</b>: נסמן לעיל פ' שמות כב, ב."],["6734","325","<b>ארץ אשר. . בה</b>: עקב יא, יב [בדילוג]."],["6735","326","<b>ואתחנן</b>: ואתחנן ג, כג."],["6736","327","<b>אעברה נא. . הזה</b>: ואתחנן שם, כה."],["6737","328","<b>בארץ בפו\"מ</b>: א: ליתא."],["6738","329","<b>אל יתהלל</b>: ירמי' ט, כב."],["6739","330","<b>כ\"א לעשות חסד</b>: ירמי' שם, כג [בדילוג. ושם עושה חסד — ראה לקמן קסט, ד. קע, ד. קעב, ג. קעג, ג. פ' משפטים רצה, ד. פקודי תנג, ד. הנסמן במאמרי אדה\"א ויקרא ח\"ב ע' תרטז־ קונטרסים ע' תא. ש\"א ל, ב ובהערה 35]."],["6740","331","<b>ויענך וירעיבך</b>: עקב ח, ג."],["6741","332","<b>לפום צערא אגרא</b>: אבות ספ\"ה. ולפי גי' אדה\"ז בסידורו מכ\"א."],["6742","333","<b>ג' דברים באים ע\"י יסורים</b>: ראה לעיל ו, ג. וש\"נ."],["6743","335","<b>להנחיל אוהבי יש</b>: משלי ח, כא. ראה גם להלן קמט, ב. קנד, ב. קנו, ד. קנט, רע\"ד. קצה, א. קצז, ד. רכד, ב. רלה, א. פ' יתרו רסא, ד. מאמרי אדה\"א קונטרסים ע' ת. וש\"נ."],["6744","336","<b>בתכלית הביטול דוקא</b>: א: דווקא בתכלית הביטול לפי דנעוץ תחב\"ס וסוב\"ת."],["6745","338","<b>המו\"מ אבל</b>: א: החומרי מבלי."],["6746","339","<b>וחברון שבע שנים</b>: שלח יג, כב."],["6747","340","<b>הוא קרית. . בענקים</b>: יהושע יד, טו [ושם: קרית. . בענקים הוא]."]]],[2300540598,"צוען מצרים (ש[א]זלעו\"ז כו' [ו]בקדושה הרי א' כגן ה' כאמ\"צ<sup data-n=\"6748\">343</sup> כו', וז' שנים הן ז' מדות שבעצמו' התענוג הנעלם שלפני ז\"מ<sup data-n=\"6749\">344</sup> דעונג המורגש כו') ובביאת[ם] לא\"י ע\"י תומ\"צ דוקא נהפכו לקדושה כו' וד\"ל.",[["6748","343","<b>כגן ה' כאמ\"צ</b>: לך יג, י."],["6749","344","<b>ז\"מ</b>: א: ז' מדות."]]],[2300540066,"<b>בעזרה\"י וית'. ביום שביעי של פסח</b>\n<span data-k=\"pg\">קעח</span> ּ<b>ואתה</b> הרם את מטך<sup data-n=\"6750\">1</sup> ונטה את ידך על הים כו', כתיב הפך ים ליבשה בנהר יעברו ברגל שם נשמחה בו, וי\"ל למה התחלת הפסוק מדבר בלשון עבר שכבר הפך ים ליבשה כו' ובסופו מדבר בלשון להבא<sup data-n=\"6751\">4</sup> שם נשמחה בו והל\"ל שם שמחנו בו. ועוד י\"ל מארז\"ל ראתה שפחה על הים<sup data-n=\"6752\">5</sup> מה שלא ראה יחזקאל כו' מה ענין הנבואה [על הים], אם בא לספר בשבחם שהיתה הנבואה בהם מקטנם ועד גדולם מהו דראתה שפחה על הים דוקא הלא יחזקאל היתה נבואתו גם [כ]שלא [הי'] על הים<sup data-n=\"6753\">6</sup> כו', ואם בא להגדיל הנס של קי\"ס מהו ענין הנבואה לקי\"ס הלא כמה נסים נפלאים נעשו ולא הי' התגלות הנבואה עי\"ז כו'. ובאמת יש להבין כל עיקר ענין קי\"ס מהו שציוה ה' להם לחזור מן הדרך <sup data-n=\"6754\">7</sup>כו' וישובו<sup data-n=\"6755\">8</sup> כו' בכדי שירדפו אחריהם בים דוקא כו'. אך הענין הוא דמבואר בזהר דים ויבשה הוא למעלה עלמא דאתכסיי' ועלמא דאתגלייא<sup data-n=\"6756\">9</sup> כו'. וביאור הדברים הנה ידוע דמח' ודבור הם משל להבין ענין ההעלם ו[ה]גילוי בהיות כי אנו רואים שכל מה שיחשוב האדם באותיות המח' מתגלה בדבור ליש ודבר מה בקול גשמי ונק' אותיות המח' בשם העלם והדבור הוא המגלה את העלם המחשבה לזולתו <sup data-n=\"6757\">10</sup>כו'. כמו\"כ יובן הכלל בכל השתלשלו' עו\"ע באבי\"ע הוא ע\"ד העלם וגילוי שהעילה הוא העלם העלול והעלול הוא הגילוי מן ההעלם, וכשהעלול הזה משפיע למטה הימנו הוא בבחי' העלם לגבי', וכן עד\"ז כל העלולים<sup data-n=\"6758\">11</sup> התחתון הוא בחי' גילוי [ל]עליון וגילוי העליון הוא העלם [ל]תחתון כו', כי [מ]מדריגה למדריגה עד רום המעלות משתלשל עד\"ז מהעלם לגילוי ונק' בשם ים ויבשה עלמא דאתכסי' ועלמא דאתגלייא וכל מה שיש ביבשה<sup data-n=\"6759\">12</sup> כנגדן יש בים",[["6750","1","<b>ואתה הרם את מטך</b>: מאמר זה הוא הנחת כ\"ק אדה\"א ממאמר אביו כ\"ק אדה\"ז שנאמר ביום שביעי של פסח תקס\"ג. דרוש זה בארוכה מכ\"ק אדה\"א (נדפס ע\"י קה\"ת בשנת תשמ\"ט) ופתיחתו: לה\"ע קי\"ס [ונדפס להלן קמג, ד]. והנחת הר\"מ (בן כ\"ק אדה\"ז) מדרוש זה נמצא במאמרי אדה\"ז תקס\"ג ח\"א ע' שט ופתיחתו היא: דבר אל בנ\"י וישובו. ובתוס' הגהות וכו' באוה\"ת בשלח ע' שפט (ד\"ה דבר אל בנ\"י וישובו). וראה שם ע' תטו (ד\"ה ואתה הרם את מטך). ראה עוד ע\"ד המאמר להלן ברשימת הכת\"י [ושם ג\"כ מפורט סימני האותיות הבאים להלן במראי מקומות]."],["6751","4","<b>התחלת הפסוק. . ובסופו. . להבא</b>: ראה גם ד\"ח נח, ג (ספ\"נ). שה\"א ע' פג וע' צ. מאמרי אדה\"א ויקרא ח\"א ע' רג. דרושים שבהערה 1. לקמן קמג, ד. קנז, ד. קפה, ג."],["6752","5","<b>ראתה שפחה על הים</b>: מכילתא בשלח טו, ב. ראה גם מאמרי אדה\"א ויקרא ח\"א ע' ריא. וש\"נ."],["6753","6","<b>יחזקאל. . [כ]שלא [הי'] על הים</b>: ראה מכילתא בא יב, א. מועד קטן כה, א. ת\"י וילקוט שמעוני יחזקאל א, ג (רמז שלו)."],["6754","7","<b>כו'</b>: גז: כמ\"ש."],["6755","8","<b>וישובו</b>: בשלח יד, ב."],["6756","9","<b>דים ויבשה. . עלמא דאתכסיי' ועלמא דאתגלייא</b>: נסמן לעיל קלח, ג."],["6757","10","<b>כו'</b>: גז: כידוע."],["6758","11","<b>העלולים</b>: שם: העלם."],["6759","12","<b>וכל מה שיש ביבשה</b>: נסמן לעיל פ' שמות יח, ג."]]],[2300540104,"פי' מקורם האמיתי שממנו יצא לגילוי יש ודבר כו' הוא בבחי' ים העליון דאתכסיי' בהעלם כו'. ובדרך כלל הנה ידוע דמל' דאצי' המהווה<sup data-n=\"6760\">13</sup> מאין ליש כל הנבראים דבי\"ע נק' בשם ים<sup data-n=\"6761\">14</sup> ויבשה<sup data-n=\"6762\">15</sup> דהיינו כשהוא ית' מחי' את הנבראים מאין ליש ממש בבחי' גילוי כמ\"ש וברוח פיו כל צבאם<sup data-n=\"6763\">16</sup> כו' נק' שפע כח האלקי המחי' אותם בתמידות בשם יבשה בחי' עלמא דאתגלייא והן הי' מאמרות שבדבור העליון ויאמר אלקים יהי רקיע<sup data-n=\"6764\">17</sup> כו' כמשל הדבור למטה שמגלה מצפון והעלם המח' כנ\"ל, וכשמל' דאצי' בבחי' אצי' ממש לקבל [מ]בחי' העלם העצמו' דאורות הנאצלי' נק' ימא עילאה כמ\"ש כל הנחלים הולכים<sup data-n=\"6765\">18</sup> [אל הים] כו', וזהו שכל הברואים יש מאין בגילוי כנגדו הי' תחלה בימא עילאה בחי' העלם במח' דבחי' אותיות וכלים דאצי' עצמו כו' כמ\"ש במ\"א.\n<b>והנה</b> ענין בריאה ויצי' הוא חשך ואור כי הרי הדבור הוא הגילוי של המח' לזולתו והמחשבה היא בהעלם לזולתו כמו האור שמאיר את המצפון ונעלם שבחושך כו', וזהו יוצר אור<sup data-n=\"6766\">19</sup> ובורא חשך כו' שהיצי' באור וגילוי ההעלם והבריאה הוא בחי' מח' שבהעלם וחשך כו', וידוע דג' מדרגות יש בי\"ע [מחדו\"מ<sup data-n=\"6767\">20</sup> ו]כמ\"ש ולכבודי בראתיו יצרתיו אף עשיתיו<sup data-n=\"6768\">21</sup> כו'. והנה אם נאמר שהמעשה הוא ג\"כ ענין גילוי פעולת המעשה<sup data-n=\"6769\">22</sup> כמלאכת הכתיבה וכדומה הרי לא ישתווה ערך המדרגות מזה לזה מעילה לעלול כי <span data-k=\"pg\">358</span> ּ הלא ערך הדבור המתגלה לא רחוק הוא מהעלם המח' כ\"כ כמו שרחוק פעולת העשי' לגבי הדבור (כידוע שע\"ז כיוון הפסוק באמרו אף עשיתיו אף הפסיק<sup data-n=\"6770\">23</sup> ההשתל' בריחוק ההדרגה כו' כמ\"ש במ\"א). ואמנם באמת לא על פעולת גילוי המעשה נאמר עשיתיו כ\"א על פנימי' כח המעשה, וכן בדבור שא\"א<sup data-n=\"6771\">24</sup> שהוא גילוי מן העלם המח' לא על התגלות הדבור הוא אלא על כח הדבור הפנימי' שבנפש, [כי] הלא ידוע ומבואר במ\"א בענין<sup data-n=\"6772\">25</sup> אחה\"ע<sup data-n=\"6773\">26</sup> מהגרון כו', שאין הה' מוצאות בחי' כלים להאותיות כלל עד שמחמת השפתים הגשמי' תהי' סיבת יציאת אותיות בומ\"ף, שא\"כ הי' ראוי שתהי' קמיצת השפתים אחר[י מבטא] אות בי\"ת [והרי נקמצו קודם שיבטא כו' אין זה כ\"א שיש כח בנפש הרוחניות לבטא אות בי\"ת] והוא יוצא ומקמץ את השפתים [ו]עושה אותה כלי לכך כו' והשפתיים",[["6760","13","<b>המהווה</b>: גז: המחי'."],["6761","14","<b>דמל'. . נק' בשם ים</b>: ראה זהר בהעלותך קנ, ב. הנסמן במאמרי אדה\"א שמות ח\"ב ע' תסג."],["6762","15","<b>דמל'. . נק' בשם. . ויבשה</b>: ראה זהר בראשית יח, א ובמק\"מ שם. ת\"ז תכ\"א (נד, א. סא, א). פרדס (שער עה\"כ) שכ\"ג, מערכת יבשה."],["6763","16","<b>וברוח פיו כל צבאם</b>: תהלים לג, ו."],["6764","17","<b>ויאמר אלקים יהי רקיע</b>: בראשית א, ו."],["6765","18","<b>כל הנחלים הולכים</b>: קהלת א, ז."],["6766","19","<b>יוצר אור</b>: נסמן לקמן קמד, ג."],["6767","20","<b>בי\"ע [מחדו\"מ</b>: נסמן לקמן קמד, ב."],["6768","21","<b>ולכבודי. . אף עשיתיו</b>: ישעי' מג, ז."],["6769","22","<b>המעשה</b>: גז: העשי'."],["6770","23","<b>אף עשיתיו אף הפסיק</b>: נסמן לקמן קמד, ג."],["6771","24","<b>שא\"א</b>: גז: שאנו אומרים."],["6772","25","<b>ומבואר במ\"א בענין אחה\"ע</b>: ראה גם דרושים שבהערה 1. להלן קמד, ד. מאמרי אדה\"א ויקרא ח\"ב ע' תתקכב ואילך. נ\"ך ע' קמה. קונטרסים ע' תכז ובהנסמן בהנ\"ל."],["6773","26","<b>אחה\"ע [ג: אחע\"ה]</b>: נסמן לעיל פ' שמות מז, ב."]]],[2300540142,"[עצמן] <b>אין</b> להם ערך והשתוות כלל אל אות ב' הרוחני שבנפש המדבר כמ\"ש [שם] בארוכה. ועד\"ז בכל ך\"ב אותיות שבה' מוצאות עיקר האותיות המה רוחני' מאד כלולים בנפש ונק' רוח ממללא<sup data-n=\"6774\">27</sup> והיינו כח הדבור שבנפש מה שתוכל הנפש לדבר כש[ת]רצה כו'. וכן עד\"ז העלם המח' הוא בחי' כח אותיות המחשבה והיינו כח שכלי ורוחני שמוציא אותיות הגשמי' של המח', וערך גשמי' אותיות המח' לגבי כח [ה]רוחני המוציאם כו' כערך גשמי' אותיות הדבור בה' מוצאות לגבי כח הדבור שבנפש המוציאם כו' וד\"ל. ועד\"ז גם בעשי' הכוונה הוא על כח המעשה ולא פעולת גילוי המעשה והיינו כח התנועה הרוחני' שבגוף כו', ועתה משתלשלי' ג' מדרגות הללו בהשתוות א' מזה לזה בערך [מ]עילה לעלול דהיינו מכח המח' נמשך לכח הדבור ומכח הדבור לכח המעשה [ו]כולם רוחנים בנפש עצמה כו', ורחוק ערך כח המעשה הרוחני' שבנפש לגבי כח הדבור שבה כמו שרחוק ערך כח הדבור לגבי כח המחשבה הרוחני' כו' וד\"ל.\n<b>וזהו</b> משל להבין ענין ג' מדרגות דבי\"ע דכללות כל ההשתלשלו' דאבי\"ע שנשתלשלו רק ע\"י ג' מדרגות הללו כידוע [ד]הלא ידוע דבעולם הנאצלים למעלה מאצי' ג\"כ נחלקו לג' מדרגות הללו דבי\"ע<sup data-n=\"6775\">28</sup>, כי עקודים נקודים וברודים הוא בחי' בי\"ע<sup data-n=\"6776\">29</sup> כו' אדם דאצי' בחי' ברודים נק' אדם דעשי' ונקודים הוא עולם התהו כו' נק' אדם דיצי'<sup data-n=\"6777\">30</sup> כו' ועקודים הוא אדם קדמון הנק' אדם דבריאה בדרך כללות השתלשלו' הפרצופי' כמבואר בע\"ח. [ו]גם למטה מטה בפרטי פרטיות הנאצלים והנבראים כו' הנה כל מציא[ו]ת נחלק לג' מדרגות אלו והיינו הידוע שבכל דבר יש ג' פרקים כלול חב\"ד חג\"ת נה\"י וכמו חסד דרועא ימינא<sup data-n=\"6778\">31</sup> יש בו הזרוע והקיבורת כו', והטעם לכ\"ז הוא לפי שבאמת הגם שג' מדרגות אלו משתלשלי' מעילה לעלול ויש הרחק רב מזה לזה עכ\"פ<sup data-n=\"6779\">32</sup> כולם בכללות כדבר א' נחשבו כמו היד שנק' יד אחת גם שהוא כלול מג' פרקים כנ\"ל, אע\"פ שהמה משתלשלים ממדרגה למדרגה מאחר שהוא מיש ליש הרי כולם ממהות א' אלא שיורד בהדרגה כו'.\n<b>וביאור</b> הדברים יובן עד\"מ האומן העושה את הכלי הרי מצייר במחשבתו איך לעשות[ה] בפועל ידיו, הנה לא נתחדש דבר בפעולת העשי' [מ]כמו אופן ציור הכלי במחשבתו ממש רק ששם היתה בציור רוחני יותר כו'. ולתוס' ביאור יובן מן הכלי עצמ[ה] כי הרי בכלי עצמה יש ג' מדרי' הנ\"ל [בחי'] מחדו\"מ",[["6774","27","<b>רוח ממללא</b>: ראה תרגום אונקלוס לבראשית ב, ז."],["6775","28","<b>למעלה מאצי'. . לג' מדרגות הללו דבי\"ע</b>: באוה\"ת כאן (ע' שצד): כנ\"ז [כנז' ] בתיקונים וע\"ח שער עיגולים ויושר."],["6776","29","<b>עקודים נקודים וברודים. . בי\"ע</b>: ויצא לא, י. יב. ראה גם מאמרי אדה\"ז תקס\"ז ע' לד. (וראה גם) מארז\"ל ע' שדמ. סה\"מ תרס\"ה ע' צה."],["6777","30","<b>נקודים הוא עולם התהו. . נק' אדם דיצי'</b>: ראה גם מאמרי אדה\"ז תקס\"ד ע' קצד. הקצרים ע' רנ [נדפס גם בכתובים ח\"א ע' קפב]. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370011\" data-slug=\"torah-or\" data-id=\"3901370011\">תו\"א בראשית ג, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380653\" data-slug=\"likkutei-torah\" data-id=\"4001380653\">לקו\"ת מטות פב, סע\"ד</a>. [וראה גם] מסעי צה, א. בהערה שלפנ\"ז."],["6778","31","<b>חסד דרועא ימינא. . הזרוע והקיבורת</b>: ת\"ז בהקדמה (יז, א). נסמן לעיל פ' שמות מה, א הערה 99."],["6779","32","<b>עכ\"פ</b>: גז: עכ\"ז."]]],[2300540179,"בי\"ע <sup data-n=\"6780\">33</sup>כמו החומר של הכסף <span data-k=\"pg\">קעט</span> ּ שממנו עושים גופו של הכלי הוא בחי' ההיולי וחומר הפשוט שיוכל לבא לכל ציור שירצה, כי כל ציור שיעשו אינו [מחדש] בו בגופו של כסף דבר כ\"א ההתגלות שלו לבד שיתגלה בצורה כזו או בצורה אחרת ואין בזה שינוי והתחדשות בעצמו[ת] מהות הכסף כו', וה\"ז כמו המח' והדבור שהדבור גילוי העלם המח' כמ\"כ הציור של הכלי הוא בחי' גילוי והכסף עצמו הוא בחי' העלם ההיולי וחומר הפשוט כו'. ומדרגה השלישי' הוא העשי' ותיקון של הכלי דהיינו לעשות הציור בפו\"מ בחלל בית קיבול וכדומה וכידוע בע\"ח דעשי' הוא התיקון כמ\"ש לעשות לתקן<sup data-n=\"6781\">34</sup> וכן ועשתה את צפרניה<sup data-n=\"6782\">35</sup> כו'. ונמצא הגם שהי' בכלי זה [ג'] מדרגות עד שנעשה כלי <sup data-n=\"6783\">36</sup>זה ממש עכ\"ז כא' נחשבו<sup data-n=\"6784\">37</sup> שהרי גופו של כסף עדיין [ישנו] במציאות בכלי הגביע וממשו הוא ומה שנצטייר ונתקן בחלל ובית קיבול לא נשתנה בזה כלל כו'. והיינו לפי שכל מדרגה מיש ליש אין בזה שינוי ממהות למהות כ\"א ההדרגה והירידה לבד, וכן [מ]מח' לדבור יש מיש הוא אין בדיבור שינוי המהות כלל רק אותה כח מהות המח' ממש יוצאת לגילוי בכח הדבור, וכן מדבור לכח [ה]מעשה כו'. ונמצא כח המעשה היינו כח המח' ממש ומה שירדה במדרגות מעילה לעלול הכל הוא בעצמותה ומהותה כו'. אמנם הכח של המח' שיצאת מן השכל הוא בחי' יש מאין<sup data-n=\"6785\">38</sup> פי' שיש שינוי המהות בהשתלשלות זו שהרי מהות כח המח' נחשב לדבר זר לגמרי לגבי מהות השכל ואין ביניהם שום השתוות וערך כלל וכלל עד שנאמר שגופו ומהות[ו] של השכל נעשה מהות מח' בירידות המדריגות כו', אלא המח' היא בריאה חדשה במהותה כמו שימצא היש מאין שמהות היש אין לו ערך עם מהות האין כידוע ולא הי' מציאת היש תחלה באין<sup data-n=\"6786\">*39</sup> [ב]שום ערך והשתוות עד שנא' שיוצא מן ההעלם לגילוי [כידוע ו]כמבואר במ\"א וד\"ל.\n<b>והנמשל</b> מכ\"ז יובן ג\"כ למעלה בכללות כל ענין ההשתל' בין באצי' בין בבריאה מאחר שנק' בשם השתלשלו' עו\"ע שהוא בבחי' יש מיש דהיינו מן ההעלם לגילוי כו' לא ימלט מג' מדרגות אלו הנ\"ל מדו\"מ הנק' בי\"ע, אך שבעולם הנבראים ליש <sup data-n=\"6787\">39</sup>מיש הוא למטה במדרגה ובעולם הנאצלים הוא למעלה במדריגה, אמנם גם למעלה במאצי'<sup data-n=\"6788\">40</sup> ובאצי' מאחר שנשתלשלו מעילה לעלול כו' גם בבחי'<sup data-n=\"6789\">41</sup> א\"ק הנק' אדם דבריאה נק' יש הגם שהוא מקור<sup data-n=\"6790\">42</sup> העלם ומקור עולם העקודים<sup data-n=\"6791\">43</sup> כו' ועולם הנקודים העלם ומקור אדם דעשי' כולם מיש ליש הוא וכדבר א' נחשבו כמו היד בג' פרקי' וכמשלים הנ\"ל. אבל אדם דבריאה הנק' א\"ק",[["6780","33","<b>כמו</b>: שם: כו'."],["6781","34","<b>בע\"ח. . לעשות לתקן</b>: בראשית ב, ג. ראה ב\"ר פי\"א ו ובפרש\"י שם. הנסמן במאמרי אדה\"א ויקרא ח\"ב ע' תתסח. דברים ח\"ד ע' א'רט. סה\"מ תרצ\"ז ע' 214."],["6782","35","<b>ועשתה את צפרניה</b>: נסמן להלן קמה, ד. במאמרי אדה\"ז תקס\"ג כאן (ע' שיב) מביא עוד פסוק: לעשות את השבת (תשא לא, טז)."],["6783","36","<b>זה</b>: גז: ליתא."],["6784","37","<b>נחשבו</b>: שם: חשיבי."],["6785","38","<b>המח'. . יש מאין</b>: ראה גם לעיל פ' בא קלא, ג ובהנסמן לשם."],["6786","*39","<b>ולא הי' מציאת היש תחלה באין</b>: ראה גם לקמן קמו, א. וש\"נ."],["6787","39","<b>מיש</b>: גז: ממש."],["6788","40","<b>במאצי'</b>: שם: מהאצי'."],["6789","41","<b>גם בבחי'</b>: שם: נק' בחי'."],["6790","42","<b>מקור</b>: שם: ליתא."],["6791","43","<b>העקודים</b>: שם: הנקודים."]]],[2300540216,"לגבי בחי' העצמיות דאוא\"ס הוא נשתלשל בבחי' יש מאין [בבחי'] שינוי המהות לגמרי כמו אותיות המח' לגבי השכל כנ\"ל [ש]אין ערוך כלל בינו עם עצמות אוא\"ס, ולכך נק' אדם דבריאה ע\"ש שנברא מאין ליש ואינו מסוג א' עם אוא\"ס משא\"כ עקודים<sup data-n=\"6792\">44</sup> וברודים הם מסוג א' עם א\"ק כי בי\"ע יש להם [ערך ו]השתוות מזה לזה כנ\"ל וד\"ל.\n<b>והנה</b> ג' מדרגות הנ\"ל בי\"ע ישנם [ג\"כ] בעבודת ה', ויובן בנפש הבהמית במילי דעלמא כשיתבונן ב[איזה] מו\"מ להרויח ישכיל השכל[ו'] איך שירויח ויש שאין לו שכל להשכיל ירויח במלאכה ועבודה לחרוש [ולזרוע] וכדומה, וה\"ז ענין א' רק שזה <span data-k=\"pg\">360</span> ּ ירויח ע\"י שכלו וזה ע\"י עבודתו ושניהם אינ[ם] אלא בחי' לבושים [דלבושים] אל פנימי' המכוון שהוא הריוח עצמו והשכל מלבישו כך [ו]המלאכה מלבשת [ב]גשמיות יותר וה\"ז כמו מלבושים דמחדו\"מ זה מלביש לזה וכולם יש מיש כנ\"ל. אמנם הריוח עצמו [הוא] אשר אינו בלבושים וכלים [כלל] רק הוא נתפס בנקודת הלב שלמעלה מן השכל והמעשה, כי הרי נקודת הלב שלו ורעותא דלבא אינו אלא שיהי' פקוח לנפש בריוח המעות יהי' איך שיהי' כו' מחמת שאוהב חיי נפשו ורוצה לחיות ולא למות ברעב כו', וזה לא [בא] בלבושי' כלל רק בהעלם פשוט בעצמות הנפש רק אח\"כ יבא לידי לבושי' וכלים בהתחכמות איך שיהי'<sup data-n=\"6793\">45</sup> שימצא טרף לנפשו אם בשכל אם במלאכה כו'. וכמו\"כ יובן בנה\"א שההתבוננו' בגדולת הבורא היא מלבשת בחי' רעותא דלבא והוא בחי' יש מאין, כי נקודת הלב אל אור א\"ס ב\"ה הוא [פשוט] בתכלית ההעלם בעצמו' הנה\"א [וכמ\"ש כלה שארי ולבבי<sup data-n=\"6794\">46</sup> כו' בכלות הנפש ממש בלתי לבוש בשכל וטעם כלל והיינו רעותא דלבא הנק' נקודת הלב שהוא בחי' אין, ומה שישכיל השכלות והשגות באור א\"ס איך דכולא קמי' כו' הוא מחמת נקודת הלב שימצא טרף לנפשו האלקית] להחיות[ה] להיות מתקיימת בהתקשרות[ה] ב[אור] א\"ס ע\"י החכ' והשגה האלקי' או ע\"י מעשה העבודה במצות כו', להיות כי הגם<sup data-n=\"6795\">47</sup> ההתחלה בעבודת ה' צ\"ל ממטה למעלה ע\"כ תקדים ההתבוננו' והעבודה עד שיגיעו לנקודת הלב אהבת בכל מאדך, אבל כשיגיע אליה הנה כל מה שקדם לה הכל רק בחי' לבושי' וכלים אלי' כו'. וכמו שמבואר למעלה שג' מדרגות דבי\"ע הם יש מיש והבריאה [הוא] יש מאין כו' כן נקודת הלב הוא בחי' אין של היש דחכמה. ונמצא מובן שהתפעלות נקודת הלב לא תהי' באדם כ\"א אל עצמות אוא\"ס ב\"ה שלמעלה מסדר ההשתל' דאבי\"ע כשאינו מתלבש בלבושי' וכלים דבי\"ע עקודים נקודים כנ\"ל [ו]התפעלות",[["6792","44","<b>עקודים</b>: שם: נקודים."],["6793","45","<b>שיהי'</b>: שם: ליתא."],["6794","46","<b>כלה שארי ולבבי</b>: תהלים עג, כו."],["6795","47","<b>הגם</b>: גז: ליתא."]]],[2300540248,"אהוי\"ר שמחמת השכל והדעת הוא מהתבוננו' ההשתלשלות וד\"ל, וזהו קרוב ה'<sup data-n=\"6796\">48</sup> לכל קוראיו לכל אשר יקראוהו באמת, פי' הקריאה באמת הוא בחי' רעותא דלבא הנ\"ל אל עצמו' אוא\"ס שהוא בחי' האין של הי\"ס<sup data-n=\"6797\">49</sup> דא\"ק שנק' אדם דבריאה וכמ\"ש כי גאה גאה<sup data-n=\"6798\">50</sup>, פי' למעלה מן הגיאות כי [הגיאות] הוא אשר המאציל [הוא] רם ומתנשא על הנאצלים בבחי' מקיפים כידוע, אבל [ב]בחי' עצמותו ית' לא יתכן לזו<sup data-n=\"6799\">51</sup> לומר כלל ענין ההשתלשלו' עד שנא' עליו שהוא גאה ומתנשא על המשתלשל ממנו כו' כי קמי' כלא חשיב כל המדרגות של בי\"ע ונק[ראים] בחי' יש לגבי עצמות אוא\"ס ב\"ה, וזהו אליו ולא למדותיו<sup data-n=\"6800\">52</sup> כו' [ו]כמ\"ש במ\"א וד\"ל.\n<b>וזהו</b> ואתה הרם את מטך כו', פי' מטה לשון הטי'<sup data-n=\"6801\">53</sup> כמו מטה כלפי חסד<sup data-n=\"6802\">54</sup> [כי] כמו שהשבט מן האילן נק' בשם שבט ע\"ש המשכתו<sup data-n=\"6803\">55</sup> שנמשך מן האילן<sup data-n=\"6804\">56</sup> ומתפשט מגופו של אילן כמו כוכבא דשביט<sup data-n=\"6805\">57</sup> כו', כמו\"כ המטה נק' ע\"ש הטיי' כאשר [הענף] יתקשה ויהי' פניו נוט[ין] לארץ כו'. וביאור ענין המטה כמו שבנ\"י<sup data-n=\"6806\">58</sup> נק' שבטי י\"ה<sup data-n=\"6807\">59</sup> היינו כמו שנשמתן נמשכו משרשם [ה]אלקי כענף מגופא דאילנא דלעילא שבבחי' אצי' כו', ועד\"ז נק'<sup data-n=\"6808\">60</sup> בשם מטות היינו כאשר בעבודתם באהוי\"ר שלהם ממשיכים אלקו' למטה מטה כלשון הטיי' וכמ\"ש במ\"א ע\"פ אלה מטות<sup data-n=\"6809\">61</sup> כו'. וגם כאן בענין המטה ר\"ל<sup data-n=\"6810\">62</sup> ואתה הרם כו' ענין ההטי' שלמטה<sup data-n=\"6811\">63</sup> כשהוא מטה כלפי חסד או כלפי גבורה והיינו כי משה הוא בחי' דעת עליון<sup data-n=\"6812\">64</sup>, וידוע ההפרש בין דעת עליון לד\"ת<sup data-n=\"6813\">65</sup> כי ד\"ת היינו בחי' [ה]התקשרות מלמטה למעלה כשמקשר עצמו באיזה שכל וכדומה, אבל <span data-k=\"pg\">קפ</span> ּ ד\"ע הוא [ה]התקשרות של המשפיע במקבל מלמעלה למטה מעלמא דדכורא לנוק' כו', והיינו כח הממשיך ההכרעה להטות את השכל ההיולי לזכות כמו<sup data-n=\"6814\">66</sup> לחוב [כו' כי מן המשכיל יוכל להיות המשכות שכל לזכות כמו לחוב כו'] ומי הוא המכריע ומטה את [המשכיל לירד כך ולא כך כו', אין זה אלא בחי' הדעת עליון שבמשכיל דח\"ס דמקשר את עצמותו להשפיע]<sup data-n=\"6815\">67</sup> כך ולא כך, והרי הוא עיקר המקשר מלמעלה למטה לנטות כלפי חסד או להיפוך כו' וד\"ל. והנמשל מזה יובן למעלה שבהיות [ש]אין ערוך כלל בין עצמות [ה]א\"ס לבחי' א\"ק היינו<sup data-n=\"6816\">68</sup> אדם דבריאה שהרי הוא נמשך בבחי' [יש] מאין כמשל השכל מלמעלה מן השכל שבבחי' יחידה וצריך לבא לבחי' התקשרות שיקשר עצמו' א\"ס לירד ולהשפיע יש מאין כו', הנה הדעת עליון שבעצמות הוא המקשר [הארת ה]א\"ס לבחי' א\"ק<sup data-n=\"6817\">69</sup> והוא שרש דשרש מדריגת",[["6796","48","<b>קרוב ה'</b>: תהלים קמה, יח. ראה גם לקמן קמז, א."],["6797","49","<b>הי\"ס</b>: גז: היש."],["6798","50","<b>כי גאה גאה</b>: בשלח טו, א. ראה גם שע\"ת יב, ב. שה\"א לו, א. לעיל פ' בא ק, ג. לקמן קמז, א. קסא, ג. קסח, ד."],["6799","51","<b>לזו</b>: גז: ליתא."],["6800","52","<b>אליו ולא למדותיו</b>: ראה גם לעיל פ' וארא עז, א. וש\"נ."],["6801","53","<b>מטה לשון הטי'</b>: נסמן לקמן קמז, ב."],["6802","54","<b>מטה כלפי חסד</b>: ר\"ה יז, א."],["6803","55","<b>שבט ע\"ש המשכתו</b>: ראה גם מאמרי אדה\"ז תקס\"ה ח\"א ע' קיד (נוסח א'). ע' קכב (נוסח ב). פרשיות התורה ח\"ב ע' תקיז ובהנסמן במ\"מ לשם. מאמרי אדה\"א במדבר ח\"א ע' סז. דברים ח\"ב ע' תסח. לעיל פ' שמות לז, ג. לקמן שם."],["6804","56","<b>מן האילן</b>: גז: להלאה."],["6805","57","<b>כוכבא דשביט</b>: ברכות נח, ב."],["6806","58","<b>כמו שבנ\"י</b>: גז: הנה כשבנ\"י."],["6807","59","<b>שבטי י\"ה</b>: תהלים קכב, ד."],["6808","60","<b>ועד\"ז נק'</b>: גז: וכשנקראים."],["6809","61","<b>אלה [גז: ואלה ה]מטות</b>: ראה גם מאמרי אדה\"ז תקס\"ב ח\"א ע' רלח."],["6810","62","<b>המטה ר\"ל</b>: גז: מטה משה רצונו לומר באמרו."],["6811","63","<b>שלמטה</b>: שם: של משה."],["6812","64","<b>משה. . דעת עליון</b>: נסמן לקמן קמז, ב."],["6813","65","<b>עליון לד\"ת</b>: גז: תחתון לדעת עליון. ראה גם לקמן שם."],["6814","66","<b>כמו</b>: שם: או."],["6815","67","<b>[המשכיל. . להשפיע]</b>: בתו\"ח כאן: השכל להיות."],["6816","68","<b>היינו</b>: גז: הנק'."],["6817","69","<b>א\"ק</b>: בתו\"ח כאן ניתוסף: הנק' אדם דבריאה שהרי הוא נמשך הארת א\"ס בבחי' א\"ק. ותיבות אלו מיותרות כי כבר נדפסו בשורות שלפנ\"ז."]]],[2300540279,"משה שהרי הי' מרכבה לבחי' דעת דז\"א<sup data-n=\"6818\">70</sup> כו'. ולכך ציוה אל משה דוקא לנטות במטהו על הים להפוך מים ליבשה כי בו תלוי עיקר ירידת ההמשכה כנ\"ל וד\"ל.\n<b>וענין</b> ההרמה שציוה[ו] להרים את מטהו כו', בהיות כי גם ד\"ע דמשה צריך להרים עצמו לגבי עצמות אוא\"ס ב\"ה שלמעלה מן ההשתל' יש [ו]אין דא\"ק וכל אבי\"ע כנ\"ל, ואז יוכל להוריד מעצמות הא\"ס אור חדש בהטות[ו] במטהו, [כי] להיות מתהפך הים ליבשה כו' צ\"ל בהיפך זה מבחי' הארה הגבוה משניהם [ש]למעלה מים ויבשה גם בשרשם, כלומר שאין לים ויבשה שרש ומקור כלל באותה ההארה, והרי לפי ההשתל' דא\"ק עד רגלי העשי' יש לים ויבשה שרש ומקור ובכל פרצוף הים גבוה מהיבשה והוא נק' [עלמין] סתימין דלא אתגליין כמ\"ש אפיקת יו\"ד תיקונין<sup data-n=\"6819\">71</sup> וקרית לון [י' ספירן] לאנהגא בהון עלמין סתימין כו', וא\"כ כל מה<sup data-n=\"6820\">72</sup> שיש בחי' י\"ס המאציל אז יש גם עלמין סתימין ולא [י]תגלו ליבשה כו' הרי כשנהפך הים ליבשה מוכרח שהי' אז הארת עצמו' אוא\"ס שהוא הגבה מאד נעלה מן ההשתל' דמאציל יו\"ד הספי' כו' ואין לים ויבשה העליונים בו שרש ומקור להיות ההכרח בים שלא יתגלה כו' משא\"כ המח' ודבור יש הכרח למח' שלא [ת]תגלה בדבור ומכ\"ש שלא יתהפך הדבור למהות מח' [מ]אחר שבאו בסדר השתלשלות כו'. וזהו ענין ההרמה שאמר לו הרם את מטך, פי' הרם כח המטה כלפי העצמות שלמעלה מעיקר שרש ההשתל' בכדי שתוריד [במטך] אח\"כ הארה חדשה לשנות צירוף הים ליבשה, ואז בהורידו את המטה הרי הוא בא בצמצום כדרך כל ירידת שפע שאינו אלא בשם הוי' דע\"ב<sup data-n=\"6821\">73</sup> כל<sup data-n=\"6822\">74</sup> צמצום דיו\"ד<sup data-n=\"6823\">75</sup> כו', וז\"ש אח\"כ ונטה את ידך על הים כו', פי' אחרי ההרמה כלפי מעלה מעלה<sup data-n=\"6824\">*76</sup> כנ\"ל ציוהו להורידו אח\"כ בהטיי' על הים בבחי' המשכ' שפע [שבא] בסדר השתל' דיו\"ד שבידך כו' לפי שצ\"ל המשכה ממש מאין ליש דהיינו [יבשה] מים כו' וד\"ל (ועמ\"ש במ\"א [בארוכה] על ענין ובקעהו ליו\"ד<sup data-n=\"6825\">76</sup> כו' וד\"ל).\n<b>ועיקר</b> שרש הדברים בענין ההרמה יובן עד\"מ בנפש שהיא מליאה אותיות<sup data-n=\"6826\">*77</sup> דהנה ידוע פי' כי לכל דבר שבנפש יש בחי' אותיות כי כמו שיש אותיות הדבור כן יש אותיות למדות ואותיות לשכל ואותיות לרצון ותענוג כו', וביאור הדברים היינו ענין הגילוי של מהות הדבר נק' בשם אותיות אם השכל [מ]תגלה במוח נק' אותיות השכל וכשהרצון<sup data-n=\"6827\">77</sup> מתגלה נק' אותיות הרצון וכן גילוי המדות כו', והטעם שנק' הגילוי בלשון אותיות כי פי' אותיות הוא מלשון ואתא ב[ו]קר<sup data-n=\"6828\">78</sup> כו' פי'",[["6818","70","<b>משה. . דעת דז\"א</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061254\" data-slug=\"likkutei-sichot\" data-id=\"1300061254\">לקו\"ש שמות (כרך ו) ס\"ע 244</a>: בלקו\"ת בי' דוידעת [ואתחנן ה, ב] משמע דמשה הוא דעת דז\"א. וכ\"כ בבי' דחוקת ס\"ב [שם נח, א]."],["6819","71","<b>אפיקת יו\"ד תיקונין</b>: ראה ת\"ז בהקדמה (יז, א)."],["6820","72","<b>מה</b>: גז: ליתא."],["6821","73","<b>הוי' דע\"ב</b>: נסמן לעיל פ' וארא פה, ג."],["6822","74","<b>כל</b>: גז: כו'."],["6823","75","<b>צמצום דיו\"ד</b>: ראה אגה\"ת פ\"ד. לקמן קמג, ב. קמח, א. קנ, ב."],["6824","*76","<b>מעלה</b>: שם: ליתא."],["6825","76","<b>ובקעהו ליו\"ד</b>: ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"א ע' עדר."],["6826","*77","<b>בנפש שהיא מליאה אותיות</b>: נסמן לקמן קמח, א."],["6827","77","<b>וכשהרצון</b>: גז: ואם הרצון."],["6828","78","<b>אותיות. . ואתא ב[ו]קר</b>: נסמן לעיל פ' שמות כה, ג."]]],[2300540307,"שבא <span data-k=\"pg\">362</span> ּ הב[ו]קר בגילוי לעין כל כי תרגום בא אתא<sup data-n=\"6829\">79</sup> כו'. והנה בביאת האדם ממקום רחוק לביתו וכדומה הרי לא נתחדש בגופו דבר רק בזה שבא לידי גילוי מקרוב ומקודם הי' [מרחוק], וכן כל הבאה כמו וזרח השמש ובא השמש<sup data-n=\"6830\">80</sup> שבא לידי גילויים<sup data-n=\"6831\">81</sup> בגילוי מן המרחק שהי' מקודם מתחת לארץ כו'. כמו\"כ הרצון או השכל כשבאים בקירוב בבחי' הגילוי במוח ובלב נק' בשם אותיות הרצון והשכל כלומר ביאתם שבאו מהמרחק של עצמות הנפש בגילוי בכלי המוח והלב כו', וזהו הטעם שתומ\"י כשיעלה הרצון באדם יתהוו ממנו אותיות במוח ולב והיינו גילויו וקירובו להיכלו ולבית מקום משכנו בגוף כו', וכן אותיות השכל ואותיות המדות עד\"ז הם <sup data-n=\"6832\">82</sup>כו'. והנה הביאה של הרצון והשכל הנק' אותיות הוא ענין המטה [ה]נ\"ל שהוא היורד ונמשך מגבוה לנמוך כמו שהרצון בא ויורד בגילוי במוח כנ\"ל, וכאשר צריך להיות אותיות אחרים ברצונו או [ב]שכלו צריך שיתבטל ויעלה הרצון או השכל הקדום למעלה לבחי' יחידה שבנפש ואז יורד הרצון ויבא בגילוי באופן אחר שהוא בחי' אותיות אחרים כו'. ובכ\"ז יובן הנמשל בענין ההרמה את המטה דמשה [ד]היינו להיות כי הי' צריך להיות אותיות אחרים להפך מצירוף אותיות ים ליבשה כו', הוצרך להרים בחי' הרצון הקדום שהאיר באותיות דמטה משה כו' ואח\"כ יטה באותיות חדשים כו' וכנ\"ל [וד\"ל].\n<b>וזהו</b> הפך ים ליבשה בנהר יעברו ברגל כו', כי הנה מבואר למעלה דבחי' נקודת הלב באדם התחתון הוא [כדוגמת] אין של היש למעלה מעלה כו', [ע\"כ] ע\"י אתעדל\"ת תהי' אתעדל\"ע<sup data-n=\"6833\">83</sup> לעורר עצמות אוא\"ס שלמעלה מכלים ולבושים דבי\"ע שבמאציל עקודים נקודים כו' שהם יש מאין כנ\"ל. וזהו שבשעה שהפך ים ליבשה שהיתה אז בחי' הארת עצמו' אוא\"ס שלמעלה מהשתל' יש מאין כנ\"ל קבלו כללות נש\"י בלכתם שם אותה ההארה העצמי' לדורות הבאים שיוכלו להגיע אל העצמות אוא\"ס באתדל\"ת בנקודת הלב ש[ל]הם כלה שארי ולבבי כו', כי זה נפלא שיוכל האדם הגשמי להיות לו נקודת הלב למעלה אל אוא\"ס עצמו אליו ולא למדותיו כנ\"ל, אין זה כ\"א שהאיר ה' בכנ\"י אז בלכתם ביבשה שבתוך הים, כי כשהפך הים ליבשה אז הי' גילוי עצמות אוא\"ס ב\"ה כנ\"ל וד\"ל. וזהו שם נשמחה בו והל\"ל שם שמחנו בו, אך לפי שהיתה הארה והמשכה זו הנעשית<sup data-n=\"6834\">84</sup> עליהם להיות בקביעות בנפשם האלקי לדור[י] דורות לכך נאמר נשמחה בו לשון להבא כלומר שתמיד כל צל ימינו עלי הארץ<sup data-n=\"6835\">85</sup> בבוא השמחה האלקי' מצד עצמות אוא\"ס כמשי\"ת לקמן אינה אלא מחמת [השמחה] שהיתה אז שגרמה שמחה",[["6829","79","<b>תרגום בא אתא</b>: ת\"א ות\"י לך יד, ה."],["6830","80","<b>וזרח השמש ובא השמש</b>: קהלת א, ה."],["6831","81","<b>גילויים</b>: גז: קירוב."],["6832","82","<b>כו'</b>: שם: וד\"ל."],["6833","83","<b>אתעדל\"ת תהי' אתעדל\"ע</b>: נסמן לעיל מא, א."],["6834","84","<b>הנעשית</b>: גז: הנעלית."],["6835","85","<b>כל צל ימינו עלי הארץ [גז: ארץ]</b>: ע\"פ איוב ח, ט. דהי\"א כט, טו."]]],[2300540332,"לדורות כו' וד\"ל. וזהו ראתה שפחה על הים דוקא מצד גילוי אור העצמ[ו]' שע\"י קי\"ס דוקא כנ\"ל ראתה גם השפחה כו' כמ\"ש זה אלי ואנוהו<sup data-n=\"6836\">86</sup> דמשמע שהיו רואים בבחי' גילוי האור עד שרמזו עליו באצבע זה אלי כו', [ו]לפי שהי' הגילוי אור מצד עצמו ולא מחמת הכנות המקבלים כלל לכך גם השפחה ראתה כו', משא\"כ בנבוא' הנביאים שאין הגילוי אלקי בהם רק לפי ההכנה שלהם כידוע [וד\"ל].\n<b>והנה</b> להבין לשון שם נשמחה בו מהו ענין השמחה לכאן יש להקדים תחלה פי' [הפסוק] תחת אשר לא עבדת<sup data-n=\"6837\">87</sup> את ה' אלקיך בשמחה ובטוב לבב כו', טוב לבב היינו בחי' הטוב של הלב [והוא] בחי' נקודת הלב שלמעלה מהכלים ולבושי' כנ\"ל <span data-k=\"pg\">קפא</span> ּ והוא בחי' כלות הנפש ממש כנ\"ל. אך [הנה] כל מה שתגדל ביותר העלי'<sup data-n=\"6838\">88</sup> של הנפש ועוצם הצמאון כמו\"כ תגדל ביותר השמחה והחדוה כשמשיג ומצא את שאהבה נפשו וכלתה אליו מתחלה כו', וכמ\"ש מים קרים על נפש עיפה<sup data-n=\"6839\">89</sup> כו' לפי ערך החום הגדול שמפחה<sup data-n=\"6840\">90</sup> הנפש מאד כן לפ\"ע יהי' השגת<sup data-n=\"6841\">91</sup> הנפש ועוצם התענגה כשתש[י]ב מים קרים כו'. וכן עץ חיים תאוה באה<sup data-n=\"6842\">92</sup> כשהתאוה שכלתה הנפש אליו היא באה לו בגילוי אור כו' אזי תחי' את הנפש ממש בחיות חדש מעיקרו כו' והא בהא תלי' ממש וכמ\"ש במ\"א. וא\"כ גם בעבודת ה' כל מה שתהי' התשוקה יותר נפלאה בכלות הנפש בבחי' נקודת הלב בתפלה אזי יותר יגיל וישמח כשמצא תאוותו אח\"כ בעשותה המצות שהן בחי' הגילוי אור האלקי באמרו אשר קדשנו במצותיו וצונו בטלית פרישו דמלכא<sup data-n=\"6843\">93</sup> כו', והא בהא תליא ערך השמחה תהי' לפ\"ע התשוקה וטוב הלבב שבתפלה ולכך נאמרו שניהם כא' שמחה וטוב לבב וד\"ל. וזהו הטעם שזכה האריז\"ל לרזין דאורייתא מפני שעבד ה' במצות מעשיות בשמחה<sup data-n=\"6844\">94</sup> גדולה כמבואר בכתבי האריז\"ל וכמ\"ש במ\"א. וזהו שם נשמחה בו דוקא שם שהי' בחי' גילוי עצמו' אוא\"ס כנ\"ל הי' לפ\"ז<sup data-n=\"6845\">95</sup> ערך גודל השמחה עד שנקבע בנפשם שמחה לדורות בכל עת מצוא בתפלה מבוקש תאוותם בנקודת הלב [מקודם] כנ\"ל וד\"ל.\n<b>וזהו</b> בנהר יעברו ברגל כו', פי' כי לזאת צוה ה' להם לחזור מן הדרך כמ\"ש וישובו ויחנו כו' כדי שיאיר עליהם הארת עצמותו ית' עד שתקבע בנפשם לדורות כנ\"ל כדי שבכל פעם",[["6836","86","<b>זה אלי ואנוהו</b>: בשלח טו, ב."],["6837","87","<b>תחת אשר לא עבדת</b>: תבא כח, מז."],["6838","88","<b>העלי'</b>: גז: הכליון."],["6839","89","<b>מים קרים על נפש עיפה</b>: משלי כה, כה. ראה גם מאמרי אדה\"ז תקס\"ג ח\"א ס\"ע רז ואילך."],["6840","90","<b>שמפחה</b>: גז: שעפתה."],["6841","91","<b>השגת</b>: שם: השבת."],["6842","92","<b>עץ חיים תאוה באה</b>: משלי יג, יב [ושם: ועץ — ראה גם לקמן קמט, א]."],["6843","93","<b>בטלית פרישו דמלכא</b>: נסמן לעיל קלח, א."],["6844","94","<b>שזכה האריז\"ל. . בשמחה</b>: נסמן לעיל פ' וארא נה, א."],["6845","95","<b>לפ\"ז</b>: ג: לפי ערך זה. ז: לפ\"ע."]]],[2300540355,"שיעלו לרגל את פני ה' כו' יעברו בנהר<sup data-n=\"6846\">*96</sup> ג\"כ ברגל כו'. וביאור הדברים כי הנה כתי' ונהר יוצא מעדן<sup data-n=\"6847\">96</sup> כו', וידוע דבינה נק' נהר<sup data-n=\"6848\">97</sup> ע\"ש האורך והרוחב בחי' השגת דבר מה כשמשיג ומבין השכל ועדן הוא נקוד' החכ'<sup data-n=\"6849\">98</sup> כו', וכתיב בעבר הנהר ישבו אבותיכם<sup data-n=\"6850\">99</sup> כו', פי' שרש ומקור האמיתי של המדות אהוי\"ר דאברהם ויצחק כו' הוא למעלה מן השכל דבינה המולידם כו', כי בחי' נהר דבינה הוא רק כמו בחי' מעבר לבד כי הם היו תחלה ברצון ותענוג שלמעלה מן השכל כו' ואח\"כ עברו בנהר דבינה ונתגלו למהות אהבה כו' וכמ\"ש במ\"א. ובהיות כי בשעת קי\"ס היו כנס\"י בבחי' רעו\"ד שלמעלה מן השכל ודעת כלים ולבושים כנ\"ל לכך עלו אז בשרשם האמיתי בבחי' עבר הנהר העליון דאצי' כו', עד שבכל ג' רגלים שיש עלי' למל' דאצי' בעלותה לראות את פני הוי' בחי' פנימי' המדות העליון<sup data-n=\"6851\">100</sup> כמו שהן בבחי' אורך<sup data-n=\"6852\">101</sup> שורש חו\"ב הנאצלים כו' תוכל לעבור את הנהר שיוצא מעדן העליון דאצי'. וזהו בנהר יעברו ברגל כלומר מה שכללות כנס\"י עולים ברגל לראות את פני הוי' ויכולים לעבור הנהר כו' הוא מחמת [ש]שם נשמחה בו כשהפך ים ליבשה מטעם גודל ההארה שהי' אז כנ\"ל, וא\"ל<sup data-n=\"6853\">102</sup> לא היו יכולים לעבור את הנהר בעלותם לרגל. וזהו יעברו לשון להבא לדורי דורות בכל פעם שיעלו לרגל יוכלו לעבור הנהר ברגל כו' מפני שכבר נקבע זאת ההארה בנפשם כשהפך הים ליבשה ומשם נשמחה בו לדורות כנ\"ל וד\"ל.",[["6846","*96","<b>שבכל פעם שיעלו לרגל. . יעברו בנהר</b>: ראה גם ד\"ה הפך ים ליבשה תשכ\"ז (סה\"מ מלוקט ח\"א ע' תק)."],["6847","96","<b>ונהר יוצא מעדן</b>: בראשית ב, י."],["6848","97","<b>דבינה נק' נהר</b>: ראה זהר (אדרא דמשכנא) משפטים קכג, ב."],["6849","98","<b>ועדן. . החכ'</b>: ראה זהר (אד\"ז) האזינו רצ, א. יתרו צ, א. לעיל פ' שמות כו, ג. מ, א. לקמן פ' יתרו רסז, ד. ויקהל שצא, ג. סידור ענייני סעודות שבת קעג סע\"ב ואילך. מאמרי אדה\"ז תקס\"ה ח\"א ע' קיז. פרשיות התורה ח\"א ע' רסב. תקס\"ט ע' לח. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370313\" data-slug=\"torah-or\" data-id=\"3901370313\">תו\"א יתרו ע, ב</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670111\" data-slug=\"torat-chaim\" data-id=\"2300670111\">ש\"א מא, א</a>. מאמרי אדה\"א ויקרא ח\"א ע' כח וע' ריג. דברים ח\"ג ע' תתסד. וש\"נ. נ\"ך ע' קמח. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670521\" data-slug=\"torat-chaim\" data-id=\"2300670521\">תו\"ח לך פא, ב</a>. שה\"א צ, א ובהערה 13."],["6850","99","<b>בעבר הנהר ישבו אבותיכם</b>: יהושע כד, ב. ראה גם לקמן קמט, ג. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380278\" data-slug=\"likkutei-torah\" data-id=\"4001380278\">לקו\"ת בחוקותי מז, א</a>. וראה גם ביאוה\"ז בשלח מז, ד ואילך."],["6851","100","<b>העליון</b>: גז: עליונות."],["6852","101","<b>אורך</b>: שם: אריך."],["6853","102","<b>וא\"ל</b>: שם: ואם לאו."]]],[2300540378,"<b>ולהבין</b> איך ע\"י לכתם בים קיבלו<sup data-n=\"6854\">103</sup> זאת בנפשם כו' הנה הדוגמא לזה הי' בהנפת אהרן את הלוים<sup data-n=\"6855\">104</sup> כו' <span data-k=\"pg\">364</span> ּ שהי' כחו גדול כ\"כ להניף<sup data-n=\"6856\">105</sup> אלף<sup data-n=\"6857\">107</sup> לוים<sup data-n=\"6858\">106</sup>, פי' שמדרגת אהרן כה\"ג היינו אה\"ר שלמעלה מן השכל ששרשו למעלה בחי' ורב חסד<sup data-n=\"6859\">108</sup> כו', ומחמת עוצם הכח הרב של אה\"ר זו יכולה להגביה ולעורר גם את הלוי שאין לו אהבה כ\"כ שיוכל לשורר בשיר על הקרבן ג\"כ באה\"ר ותשוקה נפלאה כידוע. וזהו ענין ההנפה [כ]אדם המגביה לנמוך כו', וכמו\"כ הי' יכולת בגילוי אוא\"ס בשעה שהפך הים כו' להניף ולהגביה שרש כנ\"י בבחי' עבר הנהר העליון לדורי דורות כו' וד\"ל.",[["6854","103","<b>קיבלו</b>: שם: נקבע."],["6855","104","<b>בהנפת אהרן את הלוים</b>: בהעלותך ח, יא ואילך."],["6856","105","<b>כ\"כ להניף</b>: גז: להניף כ\"ב."],["6857","107","<b>כ\"ב אלף לוים</b>: במדבר ג, לט."],["6858","106","<b>להניף כ\"ב אלף לוים</b>: ויק\"ר פכ\"ו, ט. קה\"ר פי\"ב, ז."],["6859","108","<b>אהרן כה\"ג. . ששרשו. . ורב חסד</b>: ראה גם לעיל פ' וארא עח, א. וש\"נ."]]],[2300540067,"<b>שבת שלאחר הפסח</b>\n<b>ולהבין</b> בתוס' ביאור<sup data-n=\"6860\">1</sup> כל הדברים הנ\"ל, וגם להבין הפ' ויולך ה'<sup data-n=\"6861\">2</sup> ברוח קדים עזה כו', הנה יש להקדים ענין א' המבואר בפרד\"ס<sup data-n=\"6862\">3</sup> אשר בכלים דאצי' יתכן ענין בחי' עילה ועלול<sup data-n=\"6863\">4</sup> כו' ולא באורות כו' ע\"ש, וגם לפי קבלת האריז\"ל<sup data-n=\"6864\">5</sup> כן ההסכם אך לא בכלים דאצי' אלא עוד למטה מהם במדריגה והוא בבחי' היכלות<sup data-n=\"6865\">7</sup> דאצי'<sup data-n=\"6866\">6</sup> יתכן עלי'<sup data-n=\"6867\">8</sup> העילה והעלול [אבל גם בכלים לא יתכן עדיין ענין העילה ועלול] כו'. וביאור כ\"ז הנה כתיב נעשה אדם<sup data-n=\"6868\">9</sup> בצלמנו כדמותנו, ויש להבין ההפרש בין צלם לדמות, הנה הצלם המצוייר<sup data-n=\"6869\">10</sup> על הלוח הגם שציורו הוא ממש ציור צלמו של פני האדם אין לו ערך כלל עם צלם האדם, כי הרי צלם פני האדם יש בו חיות גמור ובציורו על הלוח הדמות<sup data-n=\"6870\">11</sup> אין בו חיות כלל ואינו אפי' כמו השכל הרוחני כשנכתב כו', והגם שנצטייר בכל תנועות העינים והפה והחוטם כאלו חי כו' כמו שעושין בציורי הצבעים<sup data-n=\"6871\">12</sup> שמציירים גם התנועה הרוחני' כו' עכ\"ז אינו חי באמת אלא בדמיון שנדמה לעין הרואה כך כו'. והנה כשיניחו אותו הציור שעל הלוח על שעוה וישקע בשעוה אותו הציור הרי ירד עוד ממדרגה למדרגה, כי כמו שירד המדרגה בלוח הנ\"ל כן ירד עוד למטה מציור גופו של הלוח כשישקע בשעוה שהרי אין בשעוה אלא דוגמת הציור שבלוח כו', וזה נק' חותם ונק' ג\"כ דמות שכל ענין דמיון הוא כאשר כבר נכפלה הצורה מעצמות הצורה בב' מדרגות כמו הצורה הנראית במראה שלא נצטיירו מגופו של צורת האדם כמו הציור על הלוח אלא מחמת הארה דהארה נדמה לעין הצורה כו' וד\"ל. ועוד יש ירידות מדרגות מדמות לדמות כמו ענין בבואה דבבואה כו' ונק' חותם בתוך חותם כו' כמו צורה שבשעוה שמצטיירת בשעוה אחרת וכדומה לזה כו' עד כמה מדרגות כו' ובזה\"ק נק' ג\"כ בלשון אתוון גליפין<sup data-n=\"6872\">13</sup> כו' וד\"ל. והנמשל מכ\"ז יובן בהיות שאין ערוך כלל בין האצי' לבריאה כמ\"ש במ\"א בענין בקיעת המסך<sup data-n=\"6873\">14</sup> כו' שהבריאה היא בחי' הארה דהארה לבד כו', וזהו נעשה אדם בצלמנו י\"ס דאדם דבריאה יצי' והוא רק בחי' צלם אלקי' שבמדרגה האצי' [עצמו] והעולמות דבריאה יצי' כו' הן בחי' דמות של אותו הצלם האלקי' בחי' הארה דהארה לבד",[["6860","1","<b>ולהבין בתוס' ביאור</b>: מאמר זה הוא הנחת כ\"ק אדה\"א ממאמר אביו כ\"ק אדה\"ז משבת שלאחר הפסח תקס\"ג [והוא ביאור לד\"ה שנדפס לפנ\"ז]. והנחת הר\"מ בן כ\"ק אדה\"ז מדרוש זה נדפס במאמרי אדה\"ז תקס\"ג ח\"א ע' שיז. ובתוס' הגהות וכו' באוה\"ת בשלח ע' תא. ראה עוד ע\"ד המאמר להלן ברשימת הכת\"י [ושם ג\"כ מפורט סימני האותיות הבאים להלן בהמראי מקומות]."],["6861","2","<b>ויולך ה'</b>: בשלח יד, כא [בדילוג — ראה לקמן קנג, ד. מאמרי אדה\"א במדבר ח\"ג ע' א'רמ]."],["6862","3","<b>בפרד\"ס</b>: ראה הנסמן לעיל פ' בא צ, א הערה 157."],["6863","4","<b>בפרד\"ס אשר בכלים. . עילה ועלול</b>: ראה שם (שער סדר עמידתן) ש\"ו, פ\"ו. אגה\"ק ס\"כ (קכט, ב). הגהות לד\"ה פתח אלי' (תרנ\"ח) ע' ס."],["6864","5","<b>האריז\"ל</b>: במאמרי אדה\"ז תקס\"ג כאן (ע' שיח), ועד\"ז באוה\"ת (ס\"ע תב) ניתוסף: (ובעש\"ט והרב המגיד דמעזריטש)."],["6865","7","<b>היכלות דאצי'</b>: ראה אוה\"ת דברים ע' כא: ובע\"ח שמ\"א פ\"ד [ שער דרושי אבי\"ע — בהוצאת שקלאב תק\"ס. ובדפו\"א שמ\"ב, פ\"ב] משמע שאף באצילות יש היכלות. . ומ\"מ בזוהר ובפרדס נזכר היכלות רק בבי\"ע. ובמאמרי אדה\"ז תקס\"ז ע' רכה: שיש היכלות גם באצי' וגם לפני האצי' כמבואר בזוהר בכמה דוכתי. לקמן פ' ויקהל תכז, א."],["6866","6","<b>האריז\"ל. . היכלות דאצי'</b>: ראה גם אגה\"ק שם (קל, א). אוה\"ת כאן (ע' תג)."],["6867","8","<b>עלי'</b>: גו: ענין."],["6868","9","<b>נעשה אדם</b>: בראשית א, כו."],["6869","10","<b>המצוייר</b>: גו: המצטייר. וראה בסמוך בפנים שו\"ה: והגם."],["6870","11","<b>הדמות</b>: שם: הדומם."],["6871","12","<b>בציורי הצבעים</b>: שם: בציורים הטובים."],["6872","13","<b>אתוון גליפין</b>: זהר בראשית טו, ב. ראה גם שעה\"י קמא, ב ובהערה 46."],["6873","14","<b>שאין ערוך. . האצי' לבריאה. . בקיעת המסך</b>: כנראה הכוונה לד\"ה להבין מ\"ש בע\"ח במאמרי אדה\"ז תקס\"ג ח\"א ע' רצא ואילך. וראה גם לעיל צו, ד."]]],[2300540105,"כמשל הנ\"ל [בחקיקת הציור] של הלוח בשעוה והוא בחי' חותם וכדמותנו בכ\"ף הדמיון כו' הוא חותם שאחר החותם דמות לדמות כו' הנק' אתוון מתגלפין כו' וד\"ל. ועפ\"ז יובן הטעם למה באתעדל\"ת של נה\"א הנק'<sup data-n=\"6874\">16</sup> יש מאין יהי' אתעדל\"ע<sup data-n=\"6875\">15</sup> שבבחי' האצי' עצמו כידוע, לפי שהנפש הוא בחי' דמות דדמות האלקי כנ\"ל ע\"כ בהתעוררות הנפש איזה מדה או שכל כן יתעורר למעלה <span data-k=\"pg\">קפב</span> ּ בבחי' עצמיות הצורה האלקי' דאצי' כמשל הצורה הנראית במראה כו' וכמ\"ש בזה\"ק בענין מראה דמות כבוד ה'<sup data-n=\"6876\">17</sup> שהוא בחי' אספקלריא דלא נהרא<sup data-n=\"6877\">18</sup> כו'.\n<b>ואחר</b> הקדמה זו יובן ענין הנ\"ל בהפרד\"ס שעילה ועלול היינו בכלים או בהיכלות<sup data-n=\"6878\">19</sup> דוקא כו', כי הנה כתי' למען יזמרך כבוד<sup data-n=\"6879\">20</sup> ולא ידום כו' ומבואר ע\"פ אלקי' אל דמי לך<sup data-n=\"6880\">21</sup> כו' וע\"פ מזמור לדוד בהיותו במדבר<sup data-n=\"6881\">23</sup><sup data-n=\"6882\">22</sup> יהודה כו' של\"ב נ\"ח שבמל'<sup data-n=\"6883\">25</sup> דאצי' הנק' כבוד<sup data-n=\"6884\">24</sup> מזמר ומשבח כלפי מעלה עצמיי' האצי' כו' קארי תדיר ולא שכיך<sup data-n=\"6885\">26</sup> כו', וי\"ל איך יתכן [ענין] השירה והביטול בבחי' העצמ[ו]' כי עד\"מ באדם לא יתכן לומר שהדבור שלו מתבטל במציאות לגבי המח' והשכל כשנשתתק מלדבר כו', שהרי השתיקה היתה ע\"י הבחירה ברצון נפשו וכשירצה ידבר ואין זה ביטול מאחר שכחות הנפש מתאחדים עם הנפש בעצמו' וד\"ל<sup data-n=\"6886\">27</sup>, וכמו שלא יתכן לומר הביטול על היד לגבי הגוף כו'. וכמ\"כ יש להפליא איך יתכן לומר בבחי' דבר ה' שמחי' כל העולמות שהוא מזמר בבחי' תשוקה וביטול<sup data-n=\"6887\">28</sup> כו', אך הענין הוא דבאמת בכל עילה ועלול יתכן ענין התשוקה והביטול דוקא בכל עלול כלפי העילה שלו מאחר שהעלול נמשך מהעילה דרך משפיע ומקבל מוכרח שיהי' תשוקת המקבל תמיד אל המשפיע לקבל וא\"ל<sup data-n=\"6888\">29</sup> יהי' העדר והפסק שפעו מן העילה כו', ומטעם זה כל עלול דבוק [תמיד] מחציו ולמעלה בעילתו<sup data-n=\"6889\">30</sup> כמ\"ש בפרד\"ס שם. ויובן [זה] עד\"מ השפעת שכל הרב לשכל התלמיד כידוע ששכל התלמיד עלול הוא וצריך תמיד לקבל השפע ע\"כ א\"א לו בלתי תשוקה והעלאה מתחלה להדבק וליכלל בעילתו המשפיע כו'. ואמנם למעלה מבחי' עילה ועלול לא יתכן התשוקה וההעלאה כלל, כי כמו הבן אל אביו שנלקח מעצמיות האב והם מהות א' ממש כידוע איך יתכן לומר שסיבת ההשפעה מן האב",[["6874","16","<b>הנק'</b>: גו: הנברא."],["6875","15","<b>באתעדל\"ת. . אתעדל\"ע</b>: נסמן לעיל פ' שמות מא, א."],["6876","17","<b>מראה דמות כבוד ה'</b>: יחזקאל א, כח."],["6877","18","<b>מראה. . אספקלריא דלא נהרא</b>: ראה זהר וישלח קע, ב ואילך."],["6878","19","<b>או בהיכלות</b>: ראה לעיל בפנים ובהערות 5-7."],["6879","20","<b>למען יזמרך כבוד</b>: תהלים ל, יג."],["6880","21","<b>אלקי' אל דמי לך</b>: נסמן לעיל פ' וארא מט, ג."],["6881","23","<b>במדבר</b>: גו: ליתא."],["6882","22","<b>מזמור לדוד בהיותו במדבר</b>: תהלים סג, א. ראה גם מאמרי אדה\"א שמות ח\"א ע' קלח. וש\"נ."],["6883","25","<b>שבמל'</b>: גו: ליתא."],["6884","24","<b>של\"ב נ\"ח. . כבוד</b>: נסמן לעיל יא, א."],["6885","26","<b>קארי תדיר ולא שכיך</b>: ראה הערה 21."],["6886","27","<b>וד\"ל</b>: גו: א'."],["6887","28","<b>תשוקה וביטול</b>: שם: ביטול ותשוקה."],["6888","29","<b>וא\"ל</b>: ג: ואם לאו."],["6889","30","<b>כל עלול. . בעילתו</b>: ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקכו. מארז\"ל ע' רפב. מאמרי אדה\"א במדבר ח\"ג ע' א'קצב."]]],[2300540143,"לא תהי' כ\"א מצד דביקות והעלאת הבן בלבד כו', כי הוא מוכרח לו בהשפעתו מצד העצמיות כו'. וכמו\"כ בעצמיות הנפש באדם יובן ההפרש הזה כמו המח' והדבור שהן בחי' כלים ולבושים נפרדים מן הנפש יתכן בהם ענין עילה ועלול דהיינו ע\"י הביטול והתשוקה שלהם יגרמו תוס' שפע שכל או מדות בהם מאחר שהם נפרדים כמשל התלמיד לגבי הרב, אבל בשכל ומדות עצמם מאחר שהם בחי' עצמיות הנפש הגם שהמדות יר[ד]ו מן השכל כידוע עכ\"ז כמהות א' ממש חשיב[י] ואינם בבחי' נפרד מן השכל כלל עד שנאמר עליהם הביטול והתשוקה כמו בעו\"ע כו' וד\"ל. והנמשל מזה מובן [מ\"ש] בפרד\"ס שבכלים יתכן ענין עו\"ע כו' כלומר שכל [עיקר] ענין השפעת עו\"ע [בבחי'] נפרדת מתחלת [מן] הכלים דאצי' אבל לא באורות הן י\"ס דז\"א ואו\"א שהן הכל בבחי' העצמיות כו' ולא בדרך עו\"ע כו'<sup data-n=\"6890\">31</sup> כנ\"ל במשל וד\"ל.\n<b>וע\"פ</b> קבלת האריז\"ל הנה ענין עו\"ע שבדרך נפרד [ה]נ\"ל מתחיל למטה מבחי' הכלים דאצי' והוא בבחי' היכלות ולבושי' דאצי', וביאור הדבר ידוע במ\"א ההפרש בין אור לשפע<sup data-n=\"6891\">32</sup> שבשפע יש שינוי כו' וזהו עו\"ע דכלים אבל באור כתי' אני הוי' לא שניתי<sup data-n=\"6892\">33</sup> כו'. וההפרש שבין כלים ללבושים<sup data-n=\"6893\">34</sup>, הנה מבואר למעלה ההפרש <span data-k=\"pg\">366</span> ּ בין בחי' צלם לדמות כו', וזהו ההפרש עצמו בין כלים ללבושים והיכלות כי הצלם הוא ציור הראשון מעצם הצורה העצמיות והוא בחי' כלי לאור דנחשבים כא' עדיין כו', ולכך נא' בזוה\"ק על הכלים דאצי' דאיהו וגרמוהי חד<sup data-n=\"6894\">35</sup> כו' וד\"ל, ולא יתכן גם בכלים דאצי' ענין הביטול והתשוקה כו'. אבל בבחי' הדמות הן לבושי' [ד]מחדו\"מ שהן לגבי השכל עצמו בציור אחר ציור כמו השכל שנכתב בכתב אותיות שאין מהות השכל כלל באותיות הכתובים וכן באותיות המח' ודבור כו', ומכ\"ש כמו ענין בבואה דבבואה שנק' חותם <sup data-n=\"6895\">36</sup>כו' שהן בחי' ההיכלות מן הלבושים כו' שהן נפרדי' לגמרי, הגם שהם בבחי' האצי' יתכן השפעת עו\"ע לנבראים עד שג\"כ יתכן בהם בחי' התשוקה והביטול והיינו מ\"ש למען יזמרך כבוד כו' וד\"ל. ובזה יובן ג\"כ מה שמצינו ענין האהבה והיראה בי\"ס הנאצלים כמו שנק' גם הכתר עליון ירא בשת<sup data-n=\"6896\">37</sup> משום דאוכם הוא לגבי עילת העילות<sup data-n=\"6897\">38</sup> כו' וכה\"ג במדות דאצי' לגבי או\"א דאצי' שנז' בהם אהבה ובושה שהוא היראה כו' רו\"ש כו', הענין הוא הכל כנ\"ל בפרד\"ס שלא על העצמות די\"ס נא' אלא על הכלים או על בחי' ההיכלות שלהם כו' ומצד שבבחי' ההיכלות יש ענין ההשתל' עו\"ע נק' עילת העילות כו' וד\"ל.",[["6890","31","<b>כו'</b>: ג: כלל. ו: ליתא."],["6891","32","<b>ההפרש בין אור לשפע</b>: ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"ב ס\"ע תקנז ואילך. תקס\"ב ח\"ב ע' שע. הנסמן במ\"מ לשעה\"י קטז, א הערה 6. אוה\"ת ואתחנן (כרך ז) ס\"ע ב'רמה ואילך. וש\"נ."],["6892","33","<b>אני ה' לא שניתי</b>: מלאכי ג, ו."],["6893","34","<b>וההפרש שבין כלים ללבושים</b>: ראה מאמרי אדה\"ז תקס\"ג ח\"א ע' רסא (שם ע' רמח נוסחא שני'). מאמרי אדה\"א שמות ח\"ב ע' תסד. וש\"נ."],["6894","35","<b>דאיהו וגרמוהי חד</b>: ת\"ז בהקדמה (ג, ב)."],["6895","36","<b>כו'</b>: גו: בתוך חותם."],["6896","37","<b>שנק' גם הכתר. . ירא בשת</b>: ראה גם לעיל פ' שמות יב, ב. וש\"נ."],["6897","38","<b>דאוכם הוא לגבי עילת העילות</b>: נסמן לעיל שם. וראה מאמרי אדה\"ז תקס\"ג כאן (ע' שיח) בשם הה\"מ."]]],[2300540180,"<b>והנה</b> כתי' מלכותך מכ\"ע<sup data-n=\"6898\">39</sup> פי' ענין המל' ידוע שהוא <sup data-n=\"6899\">40</sup>ענין ההתפשטות הארה מרחוק ולא בקירוב עד שהדבר שמקבל המל' הוא נפרד ממש ואין לו שייכות והתחברות אל המלך כו', כמו ממשלה והתנשאות של המלך [ע]ל אנשי המדינה [וכל] אשר בה, הנה לא שיחיו ויקבלו השפע מן המלך שהרי כל שפעם בכל חלקי דצח\"ם נשפע במדינה גם בלעדי המלך וא\"כ למה נק' המדינה ע\"ש [המלך] לומר ארצו של פלוני [כו'] מאחר שהוא מובדל בעצמותו מן המדינה ואין להם שייכות והתחברות עד שיהי' שינוי המדינה תלוי בשינוי גוף המלך כו', ואין בכאן כ\"א ש[נ]קרא שמו של [ה]מלך עליהם בבחי' התפשטות מרחוק [מ]עצמו' המדינה לא בגדר שפע וחיות כלל כו', [ו]מחמת זה נק' המדינה מדינת פלוני המלך כו' דהיינו שממשלת[ו] והתנשאות[ו] עלי[הם] להתנהג בהם כרצונו כו' [ו]בזאת ההתפשטות לבד יקרא שמו עלי' ונק' ארצו כו'. נמצא מובן מזה המשל שענין שם המל' אע\"פ שהוא עיקר ומקור השפעתו מאד מרחוק קדוש ומובדל מאד<sup data-n=\"6900\">41</sup> בערך מן המקבלי' בלתי יקבל שינוי משינוי המקבלי' כו'. וזהו היפך ענין עו\"ע שיש שינוי בהשפעתו ומקבל שינויים ג\"כ משינוי העלול כו' לפי שהשפעתו [ל]עלול בקירוב כו' וד\"ל. והנמשל יובן ענין כללי בכל מדות מל' בין במדת מל'<sup data-n=\"6901\">42</sup> דאצי' המקור לנבראי' בין למעלה מעלה במל' דא\"ס המקור לאדם דבריא' הנק' א\"ק כו' שאין ההשפעה בקירוב בבחי' עו\"ע כו' אלא בבחי' הריחוק הגדול בחי' התפשטות השם בלבד כמו המלך על אנשי מדינתו<sup data-n=\"6902\">43</sup> שנק' רק שמו עליהם כנ\"ל וד\"ל. וזהו [ענין] אני הוי' לא שניתי כלל שלא יקבל שינויים משינוי המקבלים הנאצלים והנבראים כו' כי אין ערוך ביניהם כלל אלא מחי' אותם בהתפשטות מרחוק בלבד, והוא מדת מל' שנק' שם והוא בחי' כלי ג\"כ לגבי העצמיות האמיתי כידוע, ולפי שגם בכלים לא יתכן עדיין ענין עו\"ע כנ\"ל <span data-k=\"pg\">קפג</span> ּ לכך מדת מל' מרומם ומתנשא בכל עולם לפי ערכו כמ\"ש המלך המרומם<sup data-n=\"6903\">44</sup> כו'. וזהו מלכותך כו', פי' מל' דא\"ס<sup data-n=\"6904\">45</sup> נק' מלכותך לנוכח כלומר מלכותך ושמך העצמי כי גם קודם ש[י]הי' עדיין אפי' שרש ומקור לנאצלים הי' הו\"א ושמ\"ו בלב\"ד<sup data-n=\"6905\">46</sup>, פי' שלא הי' שמו מתפשט אלא בלבדו הי' בשוה עם העצמו' של הא\"ס כמשל המלך בלא עם כו', וכשנתפשט שמו העצמי הנק' מל' דא\"ס הי' מסיבת התפשטות זו להיות שרש ומקור לנאצלים הנפרדי' מן העצמיות כו' דהיינו בחי' א\"ק הנק' אדם דבריאה שהוא יש מאין פי' מהארות והתפשטות מל' דא\"ס הנק' אין כנ\"ל וד\"ל. ואח\"כ המל' יורדת עוד להיות מלכותו מכ\"ע, פי' כי הנה ידוע שמל' דאצי' נעשה עתיק לבריאה<sup data-n=\"6906\">47</sup> ופי' עתיק ידוע [שהוא] מלשון המעתיק הרים<sup data-n=\"6907\">48</sup> כו', לשון נעתק",[["6898","39","<b>מלכותך מכ\"ע</b>: תהלים קמה, יג."],["6899","40","<b>ענין</b>: גו: בחי'."],["6900","41","<b>מאד</b>: גו: ליתא."],["6901","42","<b>במדת מל'</b>: שם: במל'."],["6902","43","<b>מדינתו</b>: שם: המדינה."],["6903","44","<b>המלך המרומם</b>: ברכת יוצר."],["6904","45","<b>מלכותך. . מל' דא\"ס</b>: ראה גם לקמן קסא, ג. קעח, ג. קפג, ד. פ' ויקהל תג, ג. שע\"ת קמה, א. ש\"א נו, א."],["6905","46","<b>הי' הו\"א ושמ\"ו בלב\"ד</b>: נסמן לעיל פ' וארא נג, ב."],["6906","47","<b>שמל' דאצי' נעשה עתיק לבריאה</b>: ראה ע\"ח (שער העקודים) ש\"ו, פ\"ב."],["6907","48","<b>עתיק. . המעתיק הרים</b>: איוב ט, ה. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380213\" data-slug=\"likkutei-torah\" data-id=\"4001380213\">לקו\"ת אמור לא, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380471\" data-slug=\"likkutei-torah\" data-id=\"4001380471\">שלח לט, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380965\" data-slug=\"likkutei-torah\" data-id=\"4001380965\">חוקת סז, ב</a>. ר\"ה סא, ג. מאמרי אדה\"א ויקרא ח\"א ע' רמה. וש\"נ. שעה\"י קכו, א ובהערה 5."]]],[2300540217,"ממקומו דהיינו מובדל בערך כו', כן [מ]מדת התנשאות דאצי' יורחק המקבל ויופרד כו' עד שהמל' נעתק ומובדל ממנו הרבה<sup data-n=\"6908\">49</sup> מאד נעלה כו' ונק' עתיק של הנברא יש מאין כו' וד\"ל. ועד\"ז יובן גם למעלה מעלה שממל' דא\"ס נעשה עתיק לאדם דבריאה הנק' א\"ק<sup data-n=\"6909\">50</sup> כו' מאחר שאין ער[ו]ך בין עצמות [ה]א\"ס לא\"ק שהרי הוא יש מאין כנ\"ל א\"כ מבחי' [ה]התנשאות דשם ומל' דא\"ס יהי' נק' לגבי א\"ק בשם עתיק כו' כמו שממל' דאצי' נעשה עתיק לבריאה ממש כו' וד\"ל. וזהו מלכותך מכ\"ע כל בחי' המל' שמעולם העליון שנעשה ראש ומקור לתחתון בבחי' <sup data-n=\"6910\">51</sup>עתיק בכל עולם ופרצוף לפי ערכו וא\"ק ע\"י<sup data-n=\"6911\">52</sup> וע\"י לא\"א<sup data-n=\"6912\">53</sup> וא\"א לאו\"א<sup data-n=\"6913\">54</sup> הכל הוא ממלכותך וד\"ל.\n<b>ועתה</b> י\"ל דכל מדרגות הנ\"ל בבחי' עו\"ע שבכלים ולא באורות כ\"ז<sup data-n=\"6914\">55</sup> הכל ימצא בניצוץ [ה]אלקי מאחר דבצלם אלקי' נעשה אדם התחתון כמ\"ש בצלמנו כו', ותחלה יש להקדים מאמר הזהר הידוע ע\"פ שחורה אני ונאוה<sup data-n=\"6915\">56</sup> כו' מגו דוחקא כו' אזעירת גרמ[ה] ואתעבידת נקודה חדא כו' עד דלית חיוורא בגו אתוון כו' ע\"ש. דהנה ענין עילה ועלול בעבודת ה' היינו כידוע שהאהבה [ש]נולדה מן השכל יש בה ב' מדרגות, הא' מה שנתעורר[ה] מן השכל שהשכל מקורה נק' אהבה חיצוני', אבל מדרגה השני' היינו אותה האהבה עצמ[ה] כמו שהיא למעלה מן השכל ברצון נק' נקודת הלב ופנימיות[ה] רק שירדה ועברה דרך השכל כו', שזה פי' אית חסד ואית חסד<sup data-n=\"6916\">57</sup> הנק' רב חסד שבי\"ג ת\"ד כמ\"ש בזהר דהיינו חסד ואהבה שנגבלה וירדה מן השכל נק' חסד סתם, אבל אותו החסד כמו שהוא למעלה מן השכל נק' רב חסד כו' שהוא בלתי גבול עד שלא יכילנו ויגבילנו השכל כלל כו' ונק' אהבת בכל מאדך כו' כידוע. בהיות כי האהבה שהשכל יכיל אותה אז היא נתפסת ומתיישבת בכלי הלב כידוע אבל כשאין כלי הלב מגבילי' אותה וכענין לא יוכל למסבל דר\"ע<sup data-n=\"6917\">58</sup> [ש]נז' במדרש הנעלם כו', [ו]היינו נקודת פנימי' של הלב שאינה מתיישבת ומתצמצמת בכלי הלב הוא אשר גם השכל לא יכילנה והוא למעלה מן השכל ונק' מאד בלתי גבול ושיעור וכח כי בכח<sup data-n=\"6918\">59</sup> שמתפשט בלתי גבול בשכל כידוע, ולכך גם הי\"ג תיקוני כו' נק' בשם מדות הרחמים<sup data-n=\"6919\">60</sup> אלא שהם גדולים<sup data-n=\"6920\">61</sup> ע\"ש התפשטותם בלי גבול כי הם מדות שברצון קודם שעברו דרך השכל כו' וד\"ל. וזהו פי' מאמר הנ\"ל מגו דוחקא אזעירת גרמ[ה] בבחי' נקודה חדא כו' היינו נקודה <span data-k=\"pg\">368</span> ּ הפנימי' של הלב שאינה מתצמצמת בכלי הלב",[["6908","49","<b>הרבה</b>: גו: הגבה."],["6909","50","<b>שממל' דא\"ס נעשה עתיק. . א\"ק</b>: נסמן לעיל פ' שמות ה, ב."],["6910","51","<b>עתיק</b>: אג: ע\"י וא\"א לאו\"א [א: ואו\"א] כו'. וכנראה שנשתרבבו תיבות אלו כאן מבסמוך. וראה הערות הבאות."],["6911","52","<b>וא\"ק ע\"י </b>[אגד: מא\"ק לע\"י. בה: וא\"ק לע\"י]: נסמן לעיל ה, ב."],["6912","53","<b>וע\"י לא\"א</b>: ראה ע\"ח (שער סדר אצי') ש\"ג, פ\"א. אגד: ליתא (וראה הערה 51). ו: וא\"א — ראה בהנסמן לעיל שם."],["6913","54","<b>וא\"א לאו\"א</b>: ראה ע\"ח שם. מאמרי אדה\"א בראשית ע' רכח. אג: ליתא (וראה הערה 51)."],["6914","55","<b>כ\"ז</b>: גו: כו'."],["6915","56","<b>שחורה אני ונאוה</b>: נסמן לעיל פ' בא קטו, ב."],["6916","57","<b>אית חסד ואית חסד</b>: זהר ויחי ריט, א. ראה אגה\"ק ס\"י. סי\"ג. מאמרי אדה\"א ויקרא ח\"ב ע' תשעז. וש\"נ. לקמן פ' משפטים רפט, א."],["6917","58","<b>לא יוכל למסבל דר\"ע</b>: ראה זהר (מדהנ\"ע) וירא צח, ב."],["6918","59","<b>וכח כי בכח</b>: ג: בכח הרצון. ו: ככח הרצון."],["6919","60","<b>הי\"ג תיקוני. . מדות הרחמים</b>: נסמן לעיל פ' בא קכג, ג."],["6920","61","<b>הי\"ג. . מדות הרחמים. . גדולים</b>: ראה גם מאמרי אדה\"א דברים ח\"ב ס\"ע תקפד ואילך. שמות ח\"א ע' קכו."]]],[2300540249,"כלל כנ\"ל והיינו בחי' כתר שהוא הרצון רעו\"ד כו' ואז לית חיוורא בגו אתוון כו', פי' מופשטת מהגבלת המדות חיצוני' אוי\"ר שנולדה מן השכל עפ\"י ההתבוננו' מתחלה כו' מאחר שהוא למעלה מן השכל כנ\"ל וד\"ל.\n<b>והנה</b> אהוי\"ר החיצוני' שנולדים מן השכל הן בבחי' כלים לגבי אהוי\"ר הפנימי' שלמעלה מן השכל ובכלים יתכן [עדיין] ענין עו\"ע הנ\"ל, ומה שנאמר בחי' רו\"ש מטי ולא מטי כו' גם באורות עליונים אע\"פ שאינם בכלי' אהוי\"ר חיצוני' כנ\"ל, וכן החכ' יראה לעלות לכתר<sup data-n=\"6921\">62</sup> וכדומה לזה גם בכתר דאוכם הוא כו' הכל הוא גם [כשאינם] בכלים [ו]בבחי' עצמיות הנקודה הפנימי' של הכתר כשאינה מתיישבת בכלים שאז היא בחי' נקודה חדא כו' הרי מופשטת מחסדים וגבור[ות] אהוי\"ר חיצוני' כנ\"ל, הענין הוא באהוי\"ר הפנימי' ולא באהוי\"ר החיצוני' כי גם בנקודת הרצון אית רב חסד כנ\"ל, וכן יראה עילאה שלמעלה מן השכל הוא מה שהחכ' יראה לעלות כו' והוא בחי' שוב ומה שתכלה הנפש בנקודת הלב הוא הרצוא כו' והכל הוא בעצמות פנימי' נקודת הרצון כו' וזה לא נק' עו\"ע כלל כי הכל הוא בבחי' העצמיות ועו\"ע תשוקת העילה לעלול<sup data-n=\"6922\">63</sup> מחמת ריח[ו]קו ופירודו הוא כו' וד\"ל. ובהיות כי כתיב בצלמנו כדמותנו, ע\"ד<sup data-n=\"6923\">64</sup> ברעו\"ד הנק' בכל מאדך [י]עורר למעלה ג\"כ בחי' מאד העליון שלמעלה בחי' הכתר דא\"ק שנק' יש כו', כי הרי מה שלא יוכל נקודה הפנימי' שבלבו להתיישב הגם שלגבי כלי [ה]נפש איש אחר שלמעלה ממנו תתיישב <sup data-n=\"6924\">65</sup>כו', עכ\"ז הוא בחי' א\"ס שבכלי נפשו כלומר אין כלי של[ה] מגביל[ה] ותקרא בחי' א\"ס לגבי כל[י] שלה כו', [ו]מאחר שהנה\"א בדמות וצלם אלקי' ה[י]א מעוררת בזה בחי' א\"ס האמיתי בחי' נקודה האלקי' העצמיות שאינה מתיישבת גם בחכ' וכתר דא\"ק כו', ולכך נאמר בכל מאדך לשון יחיד<sup data-n=\"6925\">66</sup> שכל חד לפושע\"ד<sup data-n=\"6926\">67</sup> דוקא אז בנקודת הלב שבו מעורר מאד העליון כו' וכמ\"ש במ\"א. והיינו דוקא מטעם שהוא כדמותנו שבהיות שאין ערוך כלל וכלל בין נפש האדם לגבי עצמיות אוא\"ס שהנפש הוא [סוף] כל ההשתלשלו' דאבי\"ע כידוע לכך לא יהי' סיבת ההעלאת מ\"ן כ\"א מחמת בחי' הדמות לדמות כו', אבל העלאות מ\"ן שלה לעורר אורות הנאצלי' שאין הערך רחוק כ\"כ הוא לפי שהוא בצלמנו וכנ\"ל ההפרש בין צלם לדמות כו' וד\"ל, ובדרך כלל יובן שבהאוי\"ר חיצוני' הנפש בצלם אורות הנאצלים מא\"ק שהם ג\"כ בחי' כלים כו', אבל בנקודת הלב באהוי\"ר פנימי' הוא [ב]דמות אוא\"ס ממש כו' וד\"ל.",[["6921","62","<b>החכ' יראה לעלות לכתר</b>: במאמרי אדה\"ז תקס\"ג כאן (ע' שיח) בע\"ח. ובאוה\"ת כאן (ע' תב): (צ\"ע בע\"ח שער מטי ולא מטי ושער הכללים כו')."],["6922","63","<b>העילה לעלול</b>: גו: העלול לעילה."],["6923","64","<b>ע\"ד</b>: שם: ע\"כ."],["6924","65","<b>כו'</b>: שם: בו."],["6925","66","<b>בכל מאדך לשון יחיד</b>: נסמן לעיל פ' וארא עט, ג."],["6926","67","<b>שכל חד לפושע\"ד </b>[ג: לפום שיעורא דילי']: ראה הקדמת התניא ע\"פ הזהר וירא קג, ריש ע\"ב."]]],[2300540280,"<b>וזהו</b> הפך ים ליבשה בנהר יעברו ברגל כו', פי' כי עיקר הכוונה הי' בעולי רגל שיבאו לעזרה להשתחוות<sup data-n=\"6927\">68</sup> שם לפני הוי' כמ\"ש ג\"פ בשנה<sup data-n=\"6928\">69</sup> יראה כל זכורך לראות<sup data-n=\"6929\">70</sup> את פני ה' כו', ופי' פני הוי' הוא ענין פנימי' דשם הוי' וכמ\"ש עד יעבור עמך ה'<sup data-n=\"6930\">71</sup> למעלה משם הוי' שאינ[ו] אלא חיצוני' המדות העליונות כו'. וביאור הדברים הנה ענין ההשתחווא' הגשמי<sup data-n=\"6931\">72</sup> הוא פישוט ידים ורגלים<sup data-n=\"6932\">73</sup> על [פני] שטח הארץ לפני הדום רגלי הארון<sup data-n=\"6933\">74</sup> שמשתחווה לפניו כידוע, וזה מורה עוצם ביטול המציאות מכל וכל עד שיפול כאבן דומם ר\"ל שמחש[י]ב עצמו רק לדומם עפר תחת רגליו ולא לש[ו]ם מהות דבר בפ\"ע כלל וכלל כו', <span data-k=\"pg\">קפד</span> ּ ויתפעל הארון מביטול מופלג כזה עד שיתאחד רצונו עמו ע\"י ההשתחוואה ולכך יכול לפעול אצלו הדבר הגדול שלא הי' באפשרי לו לפעול [לא] מצד אהבתו אליו ולא מצד חכמתו ושכלו כו'. וכמו\"כ יובן ענין ההשתחואה בעזרה לפניו<sup data-n=\"6934\">75</sup> בפישוט ידים ורגלים כו' הוא ענין ביטול המציאות מכל וכל גם משכל והשגה באלקי' רק בחי' נקודה חדא כנ\"ל דלית חוורא לגו כו', והוא נקודת הרצון שבלב למעלה מן השכל כו' עד שהכלים לא יכילוהו ויפול כאבן דומם מבלתי מהות דבר מה כו'. וה\"ז כדוגמת השתיקה שהוא ביטול החכ' והשכל שהשיג כבר לומר מה פשפשת<sup data-n=\"6935\">76</sup> בו<sup data-n=\"6936\">77</sup>, וידוע הענין ששתיקה זו היא עליות השכל המושג בבחי' ביטול גדול לכח המשכיל עצמו שברצון ובחי' יחידה שבנפש כו' ולכך מלה בסלע ושתיקה בתרין<sup data-n=\"6937\">78</sup> לפי שפי שנים יורדת השפע מן המשכיל ע\"י השתיקה שהיא העלאת מ\"ן בחי' ביטול המציאות דחכ' כו' וד\"ל. והנה ע\"י השתחוואה זו שנתבטל[ו] כללות נש\"י ממציאותם לגמרי מכל וכל נעשה אתעדל\"ע באוא\"ס ג\"כ בבחי' נקודה חדא הנ\"ל שלמעלה מכלי החכ' דאצי' כו' עד שהי' גילוי אלקות בכנ\"י אז בהשתחוואתם מבחי' פני הוי' פנימי' דשם הוי' פי' כמש\"ל פנימי' נקודת הלב באדם התחתון כמ\"כ למעלה בחי' פנימי' המדות דאצי' [הנק' רעותא דלבא<sup data-n=\"6938\">79</sup> ששרשה בכתר הכללי ג\"כ בחי' כתר עד דכתר דא\"ק אוכם לגבי<sup data-n=\"6939\">80</sup> כנ\"ל וד\"ל]<sup data-n=\"6940\">81</sup>.\n<b>(ויולך </b>ה' את הים ברוח קדים, פי' קדים מבחי' קדמונו של עולם שהוא בחי' העלם במח' קדומה הנק' א\"ק כמ\"ש במ\"א וכנ\"ל וד\"ל ).",[["6927","68","<b>בעולי רגל שיבאו לעזרה להשתחוות</b>: ראה יומא כא, א. וראה גם מאמרי אדה\"ז תקס\"ג כאן (ע' שכב). לקמן קמט, ב. קסא, ב. פ' תרומה שטז, א. מאמרי אדה\"א נ\"ך ע' רצו. וש\"נ. קונטרסים ריש ע' שפב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670075\" data-slug=\"torat-chaim\" data-id=\"2300670075\">תו\"ח בראשית לד, ג</a> ובהערה 31."],["6928","69","<b>ג\"פ בשנה</b>: פ' ראה טז, טז."],["6929","70","<b>לראות</b>: גו: ליתא."],["6930","71","<b>עד יעבור עמך ה'</b>: בשלח טו, טז. ראה גם להלן קמט, ב. ש\"א כ, ב ובהערה 31."],["6931","72","<b>הגשמי</b>: גו: בגשמיות."],["6932","73","<b>ההשתחווא'. . פישוט ידים ורגלים</b>: ברכות לד, ב. רמב\"ם הל' ע\"ז פ\"ו, ה\"ו. הל' תפלה פ\"ה, הי\"ג."],["6933","74","<b>הארון</b>: גו: האדון."],["6934","75","<b>לפניו</b>: שם: לפני הוי'."],["6935","76","<b>מה פשפשת</b>: זהר בהקדמה א, ב."],["6936","77","<b>בו</b>: גו: כו'."],["6937","78","<b>מלה בסלע ושתיקא </b>[ו: משתוקא]<b> בתרין</b>: נסמן לעיל פ' שמות מז, ג."],["6938","79","<b>רעותא דלבא</b>: זהר וירא ק, א."],["6939","80","<b>לגבי</b>: אד: הוא לגבי'. ו: לגבי' כו'."],["6940","81","<b>(וילך. . וד\"ל)</b>: אגו: ליתא. ב: העתיק עד תיבה שלפנ\"ז. ה: כבפנים. וראה להלן בפנים."]]],[2300540308,"<b>וזהו</b><sup data-n=\"6941\">82</sup> עד יעבור עמך הוי' שענין הוי' הוא יו\"ד ה\"א כו', דידוע [ש]ד' אותיות אלו הן רק בשביל ההמשכה והשפע מאצי' לבי\"ע שצ\"ל ע\"י צמצום מתחלה ואח\"כ התפשטות<sup data-n=\"6942\">83</sup> והמשכה בדרך וא\"ו והתפשטות ה\"א אחרונה כו' אבל בעצמות המדות דאצי' שלמעלה מענין ההשפעה להוות בע\"ג כו' נק' פני הוי' ששרשם בכתר דז\"א, וכן עד רום המעלות עד כתר עליון כו' לכך כתיב יראה כל זכורך את פני הוי' כו' בשעה שהשתחו[ו] לפני הוי' בעזרה דוקא וד\"ל. והנה מקודם שבאו לידי השתחואה כזו לפני הוי' בעזרה הוצרכו לעבור בנהר, וזהו בנהר יעברו ברגל כו' פי' כי ההשגה והשכל באלקות נק' נהר שיוצא מעדן<sup data-n=\"6943\">84</sup> כנ\"ל וההעברה בו הוא בחי' הממוצע ב[ין] נקודת הלב שהוא ההשתחואה כו'<sup data-n=\"6944\">85</sup> לפני הוי' ובין ההשגה והתבוננות באלקות כידוע, ומה שיכלו לעבור הנהר היינו לדלג השכל וההשגה לבא לידי ביטול המציאות האמיתי כנ\"ל הוא לפי שכבר הפך ים ליבשה ומאז נקבע להם<sup data-n=\"6945\">86</sup> יכולת זה לדורות שיוכלו לעבור הנהר כו' וד\"ל.\n<b>וביאור</b> הדברים הנה כתיב ויולך הוי' ברוח קדים<sup data-n=\"6946\">87</sup> עזה כל הלילה כו' בהיות כי ענין רוח קדים עזה היינו רוח קדמונו של<sup data-n=\"6947\">89</sup> עולם<sup data-n=\"6948\">88</sup> ופי' הדבר ידוע ומבואר במ\"א שהוא בחי' ה\"ג דחכמה סתימאה דא\"א ששרשם מקדי\"ם בחי' א\"ק בה\"ג דחכמ\"ה שבו, ובכללות ההשתלשלות המזרח שהוא ת\"ת<sup data-n=\"6949\">90</sup> דז\"א כו' כמ\"כ הוא בחי' ת\"ת דא\"ק, והרוח הוא ה\"ג שנובעים ממנו חזקים ומצוקים הם כ\"כ עד שיבקע[\"ו] המי\"ם דחכמה<sup data-n=\"6950\">91</sup> עד שמתחלקת לקווין ימין ושמאל כו', ולכך ביכולת כנ\"י הי' לעבור דרך הים ביבשה והמים להם חומה<sup data-n=\"6951\">92</sup> מימינם ומשמאלם כו' כי אותו רוח הקדי\"ם מקדמונו של עולם נש\"ב בה\"ם והאיר בהם והרי הוא המחלק את הי\"ם כו' ע\"כ כל זמן נשיבת\"ו בהם לא קרבו צדדי הים זא\"ז כו'. וביאור ענין זה ידוע עפ\"י משל משכל אדם שמתחלק לחו\"ג ימין ושמאל לזכות ולחוב כו'<sup data-n=\"6952\">93</sup> וכח הממציא השכל עדיין אין בו התחלקות חו\"ג כ\"א שהוא המקור להתחלקות לבקעו ולחלקו כו' וד\"ל. והנה אותו הכח המשכיל להמציא כל עיקר השכל נק' חוש\"ך כי טבעו להתעלם ולהתכסות בעצמותו ולא לירד לידי גילוי אור החכמה שלכך נק' החכמה אור<sup data-n=\"6953\">94</sup> ע\"ש הגילוי כו', ולמעלה מהגילוי נק' חושך",[["6941","82","<b>וזהו</b>: ע\"כ נמצא בתו\"ח. מכאן ואילך נדפס מבוך ג."],["6942","83","<b>יו\"ד ה\"א. . צמצום. . התפשטות</b>: ראה אגה\"ת פ\"ד. לקמן קנ, ב."],["6943","84","<b>ההשגה. . נהר שיוצא מעדן</b>: ראה לעיל קמא, ב. וש\"נ."],["6944","85","<b>כו'</b>: אדו: הנ\"ל."],["6945","86","<b>להם</b>: ד: ניתוסף: בלבבם."],["6946","87","<b>ויולך הוי' ברוח קדים</b>: בשלח יד, כא [בדילוג]."],["6947","89","<b>קדמונו של עולם</b>: לשון ב\"ר פל\"ח, ז. זהר לך פד, א."],["6948","88","<b>רוח קדים. . קדמונו של עולם</b>: ראה גם לקמן קנג, סע\"ד ואילך. קפא, ב. קצד, א. מאמרי אדה\"ז תקס\"ג כאן (ע' שכב). פרשיות התורה ח\"א ע' רפה. תקס\"ה ח\"א ע' רלט. תקע\"א ס\"ע קנו. מאמרי אדה\"א ויקרא ח\"א ע' קנז. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670565\" data-slug=\"torat-chaim\" data-id=\"2300670565\">תו\"ח בראשית מה, ב</a> ובהערה 16."],["6949","90","<b>המזרח שהוא ת\"ת</b>: ראה זהר בראשית לד, ב ובמ\"מ שם. לך פו, א ובמפרשים שם. רמב\"ן וראב\"ד בפי' ס\"י פ\"א, מ\"ה. ס' מאירת עינים לר\"י דמן עכו פ' אמר (ירושלים תשל\"ה רכב, ב). פרדס (שער מהות והנהגה) ש\"ח, פכ\"א [וכנראה שכצ\"ל ב] (שעה\"כ) שכ\"ג, פי\"ג מערכת מזרח. מערכת מערב. פע\"ח (שער הלולב) שכ\"ט, פ\"ג."],["6950","91","<b>המי\"ם דחכמה</b>: ראה זהר יתרו עט, א ובמ\"מ שם הובא בקהלת יעקב מערכת מים אות ט. <a class=\"ft-cite\" href=\"#/read/tanya/3401310008\" data-slug=\"tanya\" data-id=\"3401310008\">תניא פ\"ג</a> ובהערה לשם במ\"מ הגהות והערות קצרות לסש\"ב. מאמרי אדה\"א בראשית ע' קכג־ דברים ח\"ג ע' תתנה ובהנסמן בהנ\"ל."],["6951","92","<b>והמים להם חומה</b>: בשלח יד, כב. כט."],["6952","93","<b>ולחוב כו'</b>: א: כו'. ד: ולחוב. ו: כבפנים."],["6953","94","<b>נק' החכמה אור</b>: ראה זהר בראשית ל, ב. לקמן פ' תשא שפה, א הערה 62."]]],[2300540333,"והעלם ולא אור. והרי ידוע דדרך הטבע הוא שהאור יאיר ולא החושך כלומר האור הגשמי שרשו באש היסודי הוא עצם חשוך<sup data-n=\"6954\">95</sup> בבחי' העלם כו' הרי לא ידליקו הנר מן החושך הנעלם שבאור היסודי בשרשו אלא ידליקו מהאור הנגלה על הפתילה, וזה מן הנמנע שהחושך ידליק ויאיר הגם שהי' מהראוי בדרך ק\"ו דק\"ו שיאיר מאחר שהאור עצמו נלקח ממנו כידוע, עכ\"ז אין מדרכו וטבעו להאיר כ\"א להתעלם ולהחש[י]ך משלמטה הימנו כו' ולא להאיר ולא מחמת העדר כוחו כי אדרבה יש בכלל מאתים<sup data-n=\"6955\">96</sup> כו' וד\"ל. ועד\"ז ממש יובן בנפש המשכלת חכמה והשגת שכל נק' אור המאיר לאחרים כידוע והמשכיל הנעלם שהמציא השכל [ו]האור הוא הנק' חושך והעלם שאין מטבעו לירד אך לפעמים ירד כו', ואמנם כשירד המשכיל עצמו להאיר אור זה יקרא נפלא שאין כמוהו מחמת שזה פלא שהחושך יאיר כו' ומסתמא יש בהארה זו של החושך ענין נפלא מה שלא ימצא לעולם ע\"י שכל וחכמה כשמאירה כו' וד\"ל.\n<b>ועתה</b> יובן הנמשל כי בהיותם עוברים הים ביבשה והמים להם חומה כו' הרי הי' שלא עפ\"י סדר השתלשלות הקווי\"ן ימין ושמאל דח\"ע דא\"א וע\"י כו' והוצרך להיות בקיע\"ה וההארה חדשה מבחי' חושך הנעלם בעצמות המאציל עד רום המעלות בעצמות והוא הנק' רוח קד[י]\"ם דנשי\"ב גם בחכמה דא\"ק כו' כנ\"ל, והרי החושך האיר להם דהיינו מ\"ש ישת חושך סתרו<sup data-n=\"6956\">97</sup> כו' ולא<sup data-n=\"6957\">98</sup> האור. וזהו ויהי הענן והחושך<sup data-n=\"6958\">99</sup> ויאר את הלילה פי' לא שהאיר בלילה שהוא כח הפועל בנפעל<sup data-n=\"6959\">100</sup> הנק' מדת מל' מאור ח\"ע דאצי' אלא החושך והענן האיר להם מבחי' הקדמות הנעלם בעצמו' וזהו הענן והחושך לפי שהם האירו אור נפלא כנ\"ל במשל וד\"ל. ולהיות כן הרי בשעה שהלכו בים שנשב בגופם ונפשם אותו רוח הקד[י]ם בחי' הארת אור הנעלם בעצמות אור א\"ס שא\"ק הוא בחי' יש מאין ממנו כנ\"ל, לכך מכח זה הנעלם בעצמות שהאיר [ב]הם הוקבע בנפשם לדורי דורות עד שיוכלו לעבור הנה\"ר ברגל בכל פעם שיעלו לרגל<sup data-n=\"6960\">101</sup> לראות פני הוי' כו', בהיות שכבר ראו פני הוי' בעת עברם בים שנשב בהם ממש רו\"ח הקדי\"ם שהוא ג\"כ ענין פני הוי' עד רום המעלות כנ\"ל וד\"ל. וזהו שם נשמחה בו ש\"ם דוקא ברוח קדמונו של עולם הנאצלים כו' כנ\"ל<sup data-n=\"6961\">102</sup> שמשם האיר החושך אור נפלא עד שהוקבע",[["6954","95","<b>באש היסודי הוא עצם חשוך</b>: ראה מו\"נ ח\"ב פ\"ל. רמב\"ן בראשית א, א. מאמרי אדה\"א ויקרא ח\"ב ס\"ע תע ואילך־ דברים ח\"ד ע' א'שעז ובהנסמן בהנ\"ל."],["6955","96","<b>יש בכלל מאתים</b>: בבא קמא עד, א."],["6956","97","<b>ישת חושך סתרו</b>: תהלים יח, יב."],["6957","98","<b>כו' ולא</b>: ד: וד\"ל להאיר להם."],["6958","99","<b>ויהי הענן והחושך</b>: בשלח יד, כ. ראה גם מאמרי אדה\"ז תקס\"ח ח\"א ע' קעו ואילך. ש\"א מג, ב."],["6959","100","<b>כח הפועל בנפעל</b>: נסמן לעיל פ' וארא עה, א."],["6960","101","<b>לעבור הנה\"ר ברגל בכל פעם שיעלו לרגל</b>: ראה גם ד\"ה הפך ים ליבשה תשכ\"ז (סה\"מ מלוקט ח\"א ע' תק)."],["6961","102","<b>כו' כנ\"ל</b>: א: כו' וכנ\"ל. ד: וד\"ל."]]],[2300540356,"בכנ\"י בחי' נקודה חדא הנ\"ל להיות שמחה וטוב לבב הנ\"ל לדורי דורות בכל פעם שיעלו לרגל להשתחוות לפני הוי' כנ\"ל וד\"ל."],[2300540068,"<b>בעזר\"ה</b>\n<b>להבין</b> ענין קי\"ס<sup data-n=\"6962\">1</sup>, כתיב הפך ים ליבשה<sup data-n=\"6963\">2</sup> בנהר יעברו ברגל כו' וידוע הקושי'<sup data-n=\"6964\">3</sup> ברישא אמר לשון עבר הפך ים כו' ובסיפא א' לשון להבא בנהר יעברו שם נשמחה בו. והנה כללות ענין קי\"ס שהפך ים ליבשה הן שני מדריגות דהעלם וגילוי שנק' עלמא דאתכסי'<sup data-n=\"6965\">5</sup> ועלמא דאתגלי'<sup data-n=\"6966\">4</sup> כידוע בכל מקום שא' מן העולם ועד העולם כו', והמשל לזה הוא מח' ודיבור שהמח' היא בהעלם וסתימו ובאה לגילוי בקול ודיבור כל מה שחושב באותיות המח', וא\"כ י\"ל מהו הנס דהפך ים ליבשה שהוא בחי' ההעלם שבא לגילוי כהעלם המח' שבא לגילוי בדיבור שזהו סדר ההשתלשלות דוקא כמו בכל המאמרות כמו מאמר יהי אור יהי רקיע<sup data-n=\"6967\">8</sup> הרי המח' שבמאמר זה הי' בהעלם ובאה לגילוי במאמר זה שנק' מאמר פתוח<sup data-n=\"6968\">9</sup> כידוע, וכך הוא בכל השתלשלות עו\"ע<sup data-n=\"6969\">10</sup> בדרך פרט שהעילה המשפיע הוא בהעלם ובאה לגילוי כשמשפיע לעלול המקבל והעלול הזה כשמשפיע למטה הימנו נעשה בחי' העלם לגבי' לבא לגילוי בעלול שלמטה הימנו וכך משתלשל מעילה לעלול בריבוי המדריגות כמו במלאכי' שא' וקרא זא\"ז ומקבלי' דמ\"ד<sup data-n=\"6970\">11</sup> כידוע, וא\"כ מהו החידוש דהפך ים ליבשה שהוא המשכה מן ההעלם לגילוי' לבד כו'. אלא צ\"ל דמה שבא השפע מעילה לעלול הוא רק בחי' האחרונה שבו שהן בחי' אותיות שבו כמו אותיות המח' שבאי' לגילוי באותיות הדיבור (ונק' עקבי לאה שנכנסים תוך ראש רחל<sup data-n=\"6971\">12</sup> כידוע), והוא בחי' גילוי שבהעלם העליון נעשה העלם בתחתון והעלם שבתחתון",[["6962","1","<b>להבין ענין קרי\"ס</b>: מאמר זה הוא מיוסד על מאמר ד\"ה ואתה הרם את מטך מכ\"ק אדמו\"ר הזקן שנדפס לעיל קלט, א. וראה בהנרשם בריש המאמר שם. וראה עוד ע\"ד המאמר להלן ברשימת הכת\"י."],["6963","2","<b>הפך ים ליבשה</b>: תהלים סו, ו."],["6964","3","<b>וידוע הקושי'</b>: נסמן לעיל קלט, א הערה 4."],["6965","5","<b>עלמא דאתכסי' ועלמא דאתגלי'</b>: נסמן לעיל פ' שמות לג, א."],["6966","4","<b>ים ליבשה. . עלמא דאתכסי'. . דאתגלי'</b>: נסמן לעיל קלח, ג."],["6967","8","<b>יהי אור יהי רקיע</b>: בראשית א, ג. ו."],["6968","9","<b>מאמר פתוח</b>: שבת קד, א. ראה גם לקמן פ' יתרו רסה, א. הנסמן לעיל פ' שמות יב, ב."],["6969","10","<b>עו\"ע</b>: ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381108\" data-slug=\"likkutei-torah\" data-id=\"4001381108\">לקו\"ת ברכה צה, ב</a>: הנזכר בספרים. ראה רמב\"ם הל' יסוה\"ת פ\"ב, ה\"ו."],["6970","11","<b>וקרא זא\"ז ומקבלי' דמ\"ד </b>[ דין מן דין]: ישעי' ו, ג ותרגום יונתן שם. ראה מאמרי אדה\"א ויקרא ח\"א ע' טז. דברים ח\"א ע' קנה וש\"נ. לעיל פ' וארא עו, א. לקמן פ' משפטים רפו, א."],["6971","12","<b>עקבי לאה שנכנסים תוך ראש רחל</b>: נסמן לעיל יח, ג."]]],[2300540106,"אינו רק בחי' גילוי שבעליון (וכמ\"ש בע\"ח דחיצוני' שבעליון<sup data-n=\"6972\">13</sup> נעשה פנימי בתחתון כו'), וכמו וקרא זא\"ז דבחי' דיבור שבעליון נעשה מח' בעלול שלמטה וכאותיו' המח' נק' דיבור שבמח' נעשה מח' שבדיבור<sup data-n=\"6973\">14</sup> בהעלם שלא נתגלה רק בחי' אותיות הדיבור (ולכך נק' המח' מאמ' סתום<sup data-n=\"6974\">15</sup> מב' טעמים הא' מצד בחי' עצם המח' טרם בואה לדיבור שא\"א שיומשך עצם כח המח' לדיבור כ\"א בחי' אותיות שבה שנק' הרהור והב' גם מח' שבדיבור הוא סתום כנ\"ל). וזהו ענין השתלשלות דעו\"ע בפרט שמשתלשל מהעלם לגילוי כשלשלת<sup data-n=\"6975\">16</sup> שטבעת התחתונה קשורה בסוף העליונה דוקא כידוע דהיינו שגילוי העליון לבד נעשה העלם התחתון כנ\"ל, וזהו ענין ים ויבשה בכלל שהים נק' העלם העליון ויבשה נק' גילוי ההעלם ע\"ד הנ\"ל במח' ודיבור כמו וקרא זא\"ז כו' וד\"ל.\n<b>והנה</b> הרבה יותר מדבר זה הוא גם בניסים ונפלאות זולת נס דקי\"ס, כמו ניסים בהפוך הטבע בצירופי אותיו' שנבראו כל הברואים עד טבע דצח\"מ וארמ\"ע כאשר נתהפך סדר הטבע בי' מכות וכה\"ג שנהפך המים לדם<sup data-n=\"6976\">17</sup> וכמו שא' רחב\"ד מי שא' לשמן וידליק<sup data-n=\"6977\">18</sup> הוא יאמר לחומץ וידליק וכה\"ג הרי זה בא האור מעלמא דאתכסי' שלמעלה מן הטבע להפוך הטבע שנק' נפלאות, הנה זהו רק הארה בעלמא מסוף מדריגות דהעלם העליון שמאיר מעט ביותר מכפי המדה והצמצום דהשתלשלות עו\"ע בכלל ובפרט הנ\"ל במשל המח' ודיבור, וכענין הושיט אצבעו קטנה<sup data-n=\"6978\">19</sup> וכו', וכך א' חרטומי מצרים אצבע אלקי' הוא<sup data-n=\"6979\">20</sup>, לפי שהאיר משם הוי' בשם אלקי' המצמצם מעט ביתר מכפי צמצום והסתר הראשון שממילא נעשה היפוך צירופי אותיות דשם אלקי' וז\"ש מי שאמר כו' כידוע (כענין ך\"ו כי ל\"ח<sup data-n=\"6980\">21</sup> בבקיעת החסדים דשם הוי' באלקים כו'). וכך הוא למעלה בענין גילוי אור האלקי המצמצם במלאכים שמתהווי' ברוח פיו ית' כאותיו' הדיבור כאשר מתגלה עליהם מעט מבחי' ההעלם דעליון שהוא שם הוי' בכלל מתבטלי' ממציאותם ואו' קדוש הוי' צבאות<sup data-n=\"6981\">22</sup> וכה\"ג האופנים ברעש או' ברוך<sup data-n=\"6982\">23</sup> כו', וגם בענין גילוי הנבואה בנביאי' הרי כתיב הן במראה אליו אתודע<sup data-n=\"6983\">24</sup> בחלום אדבר בו וכתיב וביד הנביאי' אדמ\"ה<sup data-n=\"6984\">25</sup> שאין אור האלקי",[["6972","13","<b>וכמ\"ש בע\"ח דחיצוני' שבעליון</b>: ראה שם (שער או\"א) שי\"ד, ספ\"ט. מאמרי אדה\"א דברים ח\"ד ס\"ע א'רכ ואילך. וש\"נ. תו\"ח ח\"ש קכב, א ובהערה 10."],["6973","14","<b>דיבור שבמח' נעשה מח' שבדיבור</b>: ראה שעה\"י קלז, ב. מאמרי אדה\"א דברים ח\"א ע' רפג ואילך."],["6974","15","<b>המח' מאמ' סתום</b>: ראה לעיל הערה ד\"ה: מאמר פתוח."],["6975","16","<b>השתלשלות. . כשלשלת</b>: נסמן לעיל פ' שמות כד, ב."],["6976","17","<b>שנהפך המים לדם</b>: וארא ז, כ."],["6977","18","<b>שא' רחב\"ד מי שא' לשמן וידליק</b>: נסמן לעיל כ, א."],["6978","19","<b>הושיט אצבעו קטנה</b>: נסמן לעיל ל, ב."],["6979","20","<b>אצבע אלקי' הוא</b>: וארא ח, טו."],["6980","21","<b>ך\"ו כי ל\"ח </b>[ לעולם חסדו]: ראה לקמן קצא, ב. פ' יתרו רסו, ג. תצוה שכב, ג. שנא, ג. מאמרי אדה\"א בראשית ר\"ע מח וש\"נ. שע\"ת יד, ד הערה 32."],["6981","22","<b>קדוש הוי' צבאות</b>: ישעי' ו, ג."],["6982","23","<b>האופנים. . ברוך</b>: ראה ברכת יוצר. יחזקאל ג, יב."],["6983","24","<b>הן במראה אליו אתודע</b>: בהעלותך יב, ו [בהוספת תיבת ”הן\". — ראה שע\"ת קז, ג ובהערה 11. מאמרי אדה\"א ויקרא ח\"א ע' שכו. לקמן קצד, ג. פ' תצוה שכט, ג [ושם הוגה מגוכתי\"ק]."],["6984","25","<b>וביד הנביאי' אדמ\"ה</b>: הושע יב, יא. ראה שעה\"י קלז, ב."]]],[2300540144,"שופע עליהם רק מבחי' האחרונה דבחי' דמיון מראה דמות כבוד הוי'<sup data-n=\"6985\">26</sup>, והוא ג\"כ לפ\"ע הזדככות החומר<sup data-n=\"6986\">27</sup> שלהם ע\"כ או' כ\"ה אמר ה'<sup data-n=\"6987\">28</sup> כידוע בענין כל הנביאים נתנבאו בכה<sup data-n=\"6988\">29</sup> בכ\"ף הדמיון כו' (וגם גילוי שכינה בהיכל ק\"ק<sup data-n=\"6989\">30</sup> וכה\"ג הי' בדרך לבוש שנתלבש ונתצמצם שם כמאמ' צמצם שכינתו בין ב' בדי ארון<sup data-n=\"6990\">31</sup> ). אבל נס דקי\"ס הי' גדול מכל הנסים ונפלאות והוא במה שהי' גילוי עצם ומהות דהעלם העליון הנק' ים בכלל, וכמ\"ש הפך ים ליבשה ממש וזהו עיקר החידוש היותר נפלא מכל הניסים ונפלאות שנעשו באמ\"ץ<sup data-n=\"6991\">32</sup> והוא מ\"ש זה אלי ואנוהו<sup data-n=\"6992\">33</sup> זה לנוכח ממש שלמעלה מעלה מכל סדר ההשתלשלות דהעלם וגילוי שיש בכל הניסים וגם בנבואה (וגם יותר ממה שנגלה ההעלם בג\"ע העליון מזיווי' עילא' דע\"י<sup data-n=\"6993\">*34</sup> בכל שבת וחודש וכה\"ג, אף גם יותר ממה שנגלה עליהם מלך<sup data-n=\"6994\">34</sup> כו' כמ\"ש במורא גדול זו גילוי שכינה<sup data-n=\"6995\">35</sup> ). וראי' לזה ממאמר ראתה שפחה על הים<sup data-n=\"6996\">36</sup> מה שלא ראה יחזקאל הנביא, ובאמת יש להפלא במאמ' זה מה ענין הנבואה לקי\"ס, אם בא לספר בשבח ומעלה ומדריגה יתירה שהי' בהם שהי' הנבואה על כולם מהו שא' ראתה שפחה על הים דוקא כו' והלא כמה ניסים ונפלאות היו באמ\"ץ ולא נז' שהי' הנבואה עליהם כו'. אך מפני שנס דקי\"ס הוא העולה על כל מדריגו' הנבואה של כל הנביאים שנתנבאו בכ\"ה כנ\"ל ועל הים א' זה אלי ז\"ה ממש שהוא בחי' מהו\"ע א\"ס ב\"ה שלמעלה מעלה מכל ההשתלשלות דהעלם וגילוי גם בנבואה וניסים כו', וע\"כ נהפך הים ליבשה שהוא בחי' ההעלם העליון עצמו נעשה רק בחי' גילוי דיבשה לפי שלגבי עצמו' המאציל בחי' ההעלם עצמו נעשה גילוי וכמ\"ש הים ראה וינוס<sup data-n=\"6997\">37</sup> כו', וע\"כ גם השפחה ראתה מה שלא ראה יחזקאל במראה הנבואה לפי שמראה הנבואה באה רק בבחי' גילוי מן ההעלם במעט יותר מכפי סדר השתלשלות עו\"ע בהעלם וגילוי כנ\"ל בענין ביד הנביאים אדמה כו' ובקי\"ס הי' הגילוי מעצמו' אלקו' ממש שלא ע\"י הכנת המקבלים כלל ע\"כ גם השפחה ראתה מה שלא ראה כו' וד\"ל.\n<b>ולהבין</b> זה בתוס' ביאור יש להקדים תחלה בענין כללות דג' מדריגות מחדו\"מ שהן ג' מדריגות דבי\"ע<sup data-n=\"6998\">38</sup> כמ\"ש כל",[["6985","26","<b>מראה דמות כבוד הוי'</b>: יחזקאל א, כח."],["6986","27","<b>לפ\"ע הזדככות החומר</b>: ראה רמב\"ם הל' יסודי התורה פ\"ז. פ\"ז משמונה פרקים. מורה נבוכים ח\"ב פל\"ב."],["6987","28","<b>כ\"ה אמר ה'</b>: יהושע ז, יג. ועוד."],["6988","29","<b>כל הנביאים נתנבאו בכה</b>: ראה ספרי ר\"פ מטות הובא ברש\"י שם. מאמרי אדה\"ז תקס\"ד ע' קצ ומקבילו ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380650\" data-slug=\"likkutei-torah\" data-id=\"4001380650\">לקו\"ת מטות פב, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381242\" data-slug=\"likkutei-torah\" data-id=\"4001381242\">שם שה\"ש כח, ב</a>. תו\"א מג\"א קיח, ד. מאמרי אדה\"ז תקס\"ח ח\"א ע' צח וע' קפז. תקס\"ב ח\"א ע' רמ. מאמרי אדה\"א ויקרא ח\"א ע' ריא. לקמן קצד, ג. פ' תצוה שע, א."],["6989","30","<b>גילוי שכינה בהיכל ק\"ק</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310058\" data-slug=\"tanya\" data-id=\"3401310058\">תניא פנ\"ג</a>."],["6990","31","<b>צמצם שכינתו בין ב' בדי ארון</b>: נסמן לעיל צט, ב."],["6991","32","<b>באמ\"ץ</b>: בארץ מצרים."],["6992","33","<b>זה אלי ואנוהו</b>: בשלח טו, ב."],["6993","*34","<b>מזיווי' עילא' דע\"י</b>: נסמן לעיל פ' שמות לה, ב."],["6994","34","<b>שנגלה עליהם מלך</b>: הגדה של פסח פיסקא: ”מצה זו\"."],["6995","35","<b>במורא גדול זו גילוי שכינה</b>: תבוא כו, ח [ושם: ובמורא]. ספרי (והגש\"פ פיסקא: ”ביד חזקה\") שם."],["6996","36","<b>ראתה שפחה על הים</b>: מכילתא בשלח טו, ב. ראה גם מאמרי אדה\"א ויקרא ח\"א ע' ריא. וש\"נ."],["6997","37","<b>הים ראה וינוס</b>: תהלים קיד, ג."],["6998","38","<b>מחדו\"מ. . דבי\"ע</b>: ראה מאמרי אדה\"א דברים ח\"א ע' קנא. וש\"נ. בראשית ע' תמא. וש\"נ. נ\"ך ע' שפ. וש\"נ. לעיל פ' שמות ה, א. כט, ד. פרשתינו קלט, ב. לקמן קסה, ג. קצ, ג. רכט, ד."]]],[2300540181,"הנק' בשמי ולכבודי<sup data-n=\"6999\">39</sup> בראתיו יצרתיו אף עשיתיו ואנו או' אתה בראתה<sup data-n=\"7000\">40</sup> יצרת נפחת בי כו' וידוע דהבריא' הוא בבחי' המח' שבהעלם והדיבור ביצי' וזהו שא' יוצר אור ובורא חשך<sup data-n=\"7001\">41</sup> הרי החושך נק' בריאה שהוא העלם המח' והאור שהוא גילוי ההעלם הוא ביצי' כמו הדיבור שמגלה מצפון והעלם המח' כנ\"ל בי' מאמרות כו'. והנה ידוע בענין ג' מדריגות בי\"ע הנ\"ל שהעשי' הוא בחי' נפרד ומרוחק מן היצי' שהוא הדיבור שלא כקירוב הדיבור אל המח' דמה שחושב ממש הוא בא בגילוי הדיבור באופן מח' אעפ\"י שהמח' רוחני' יותר ובהעלם והדיבור אינו רק גילוי אותיות בקול גשמי והברת המבטא מ\"מ מתאחדים זע\"ז וקרובים זא\"ז בדרך עו\"ע עכ\"פ שגילוי הדיבור לא רחוק הוא מהעלם המח' כ\"כ (דה\"ג מנצפ\"ך<sup data-n=\"7002\">42</sup> המחלקות אותיות המח' הן המחלקו' כאופן הצירופי' דמח' גם באותיות הדיבור), אבל פעולת המעשה כבנין וכתיבה זה אינו משתווה בערך כלל אל אותיות הדיבור הרוחני' ונבדל ומרוחק ממנו לגמרי בלתי יש חיבור וקשר זע\"ז כלל כקשר הדיבור עם המח' (רק ע\"י מה שיצוה בדיבור לעשות הרי זהו בא בדילוג מאד<sup data-n=\"7003\">43</sup>. וגם למעלה כמ\"ש כי הוא אמר בדיבור ויהי<sup data-n=\"7004\">44</sup> כן בפ\"מ וכן בדבר ה' שמים נעשו<sup data-n=\"7005\">45</sup> או מ\"ש לכבודי בראתיו יצרתיו אף עשיתיו הרי ידוע דאף זה הפסיק הענין<sup data-n=\"7006\">46</sup> לומר אף כלומר גם עשיתיו במעשה שרחוק מערך היצי' והבריאה שהן מחו\"ד. ונמצא שיש הפרש גדול בג' לבושי' אלה דמח' דו\"מ שנק' בי\"ע בין מו\"ד שהן בבחי' קירוב כשאר עו\"ע ובין דו\"מ שהן רחוקי' זמ\"ז כנ\"ל. ועכ\"ז אנו רואים בכללות ההשתלשלות דג' עולמות בי\"ע ובפרט בכל עו\"ע דמקבלין דין מן דין כמו וקרא זא\"ז כו' שמבחי' חיצוני' דדיבור נמשך לבחי' המעשה וכמו מל' דיצי' נעשה בחי' מוחי' לעשי' (וכמו עשי' שבדיבור שהוא עקימת שפתיים דהוה מעשה<sup data-n=\"7007\">47</sup> נעשה מקור למציא' המעשה בפ\"מ כמ\"ש וברוח פיו כל צבאם<sup data-n=\"7008\">48</sup> וכה\"ג וד\"ל וכמו בכל המאמרו' כמו שא' יהי אור בדיבור ויהי אור בפ\"מ וכה\"ג).\n<b>אך</b> הנה באמת יש ב' מדריגות בג' לבושים דמחדו\"מ שהן בי\"ע א' בבחי' האורות העצמי' שלהם בנפש שהן ג' כחות שנמשכים מן הנפש עצמה וגם הם באים בהשתלשלות מזה לזה, והב' בחי' הכלי' שלהם שנק' בשם לבושים כנ\"ל. והענין הוא כידוע דהמח' טרם בואה לגילוי במוח הנה שרש מציאותה נמשך מן הנפש עצמה דוקא והוא הנק' כח המח' שכלולה בעצם הנפש והוא כח רוחני כרוחניו' עצם הנפש וכשאר כחות מיוחדים",[["6999","39","<b>כל הנק' בשמי ולכבודי</b>: ישעי' מג, ז."],["7000","40","<b>ואנו או' אתה בראתה</b>: ראה ברכת השחר (אלקי נשמה)."],["7001","41","<b>יוצר אור ובורא חשך</b>: ישעי' מה, ז. ראה פע\"ח (שער הק\"ש) ש\"ח, פ\"א. מאמרי אדה\"ז תקס\"ב ח\"א ע' ב. לעיל טז, א. קלט, ב. לקמן רז, ב. אמרי בינה שער הק\"ש מב, סע\"ב ואילך. מאמרי אדה\"א דברים ח\"א ע' ריא. שמות ח\"א ע' כג וש\"נ."],["7002","42","<b>דה\"ג מנצפ\"ך</b>: ראה שער היחוד והאמונה ספ\"ד. מאמרי אדה\"א ויקרא ח\"א ע' רלז וש\"נ. דברים ח\"ג ע' א'כג ואילך."],["7003","43","<b>מאד</b>: אוצ\"ל: מאד)."],["7004","44","<b>כי הוא אמר. . ויהי</b>: תהלים לג, ט."],["7005","45","<b>בדבר ה' שמים נעשו</b>: תהלים שם, ו."],["7006","46","<b>דאף זה הפסיק הענין</b>: ראה לעיל קלט, ב. לקמן פ' יתרו רנב, ד. מאמרי אדה\"ז תקס\"ג ח\"ב ע' תרא (נוסחא שני'). ומקבילו ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380586\" data-slug=\"likkutei-torah\" data-id=\"4001380586\">לקו\"ת בלק סז, סע\"א</a>. מאמרי אדה\"א במדבר ח\"ג ע' א'רנה. דברים ח\"ג ע' תתקכו. שע\"ת קז, ד."],["7007","47","<b>עקימת שפתיים דהוה מעשה</b>: ראה בבא מציעא צ, סע\"ב. הנסמן בלקו\"ת דרושים לשמ\"ע פד, ג. אוה\"ת נח כרך ג ע' 1232. מאמרי אדה\"א דברים ח\"ג ע' תתקכו."],["7008","48","<b>וברוח פיו כל צבאם</b>: תהלים לג, ו."]]],[2300540218,"הנמשכי' מן הנפש כמו כח השכל וכח המדות, רק שהמח' באה בבחי' לבוש שנק' אותיות המח' להלביש לשכל ולמדות כו' והן כמו אותיות מח' השכל שבמוח והרהור האוי\"ר וכה\"ג, וזהו בבחי' אותיות המח' שנק' לבוש וכלי לבד כמו שאנו רואים מיד שישכיל איזה שכל מיד מתהווי' אותיו' במח' להלביש השכל והן ערך גשמי' לגבי רוחניו' השכל, וכן לגילוי הרצון ותענוג ג\"כ יש אותיו' מח' להרהר בתענוג ורצון פרטי וכך בהתפעלות אוי\"ר במוח מתהווי' אותיו' מח' לחשוב ולהרהר בהן וכך הוא גם לצייר דבר מה במח' יש כח הדמיון אשר במח' לדמות ולצייר דבר מה וכן לחשוב מה שידבר או לשמוע במח' בדיבור זולתו שכל זה פרטי חלקי כחות שנמצאו במח' אבל מקור מציאות המח' נמשך מעצם הנפש ממש. ויובן זה יותר בדיבור שנק' לבוש חיצוני יותר גם הוא יש בו אור וכלי בכלל והוא מה שנק' הנפש רוח ממללא<sup data-n=\"7009\">49</sup> הרי הוא בחי' כח מקור מציאו' הדיבור ברוחניו' (כמו ב' רוחות מספרים זע\"ז<sup data-n=\"7010\">50</sup> וקרא זא\"ז במלאכי' רוחניי' כו'), וכמ\"ש במ\"א באריכות בענין כלי המבטא דה' מוצאות<sup data-n=\"7011\">51</sup> הפה אחה\"ע<sup data-n=\"7012\">52</sup> מהגרון כו' עד בומ\"ף מהשפתים שאין השפתים כמו כלי חומר לצורה לאותיו' בומ\"ף עד שמחמת הנעת השפתיי' יוצאי' האותיו' הללו שא\"כ הי' ראוי שיהי' קמיצת השפתיי' אחרי גילוי אותיו' בומ\"ף ככלי העין לגילוי כח הראי' וכאזן לשמוע וכה\"ג ולא נקמצו השפתיי' מיד שיוצאים, ואין זה כמו התנועה בכלי כינור ג\"כ כו' שאם הי' זה בבחי' כלי לאור מדוע לא ידבר התינוק מיד בהולדו והבהמה תדבר. אך הענין הוא דכח הדיבור כבר ישנו ברוחניו' הנפש ונק' רוח ממללא וכל האותיו' כמו אות ב' דבומ\"ף יוצא ברוחניו' מן הנפש המדברת ומתלבש בשפתיי' לקומצם שעושה אותם כלי שע\"י ישמע אות הב' בהברת מבטא גשמי ועד\"ז בכל הך\"ב אותיות שהמה בנפש עצמה כלולים בבחי' רוחניו' שנק' רוח ממללא והוא כח הדיבור שבנפש עצמה, ומה שתוכל לדבר בה' מוצאות במבטא גשמי זהו רק בחי' התלבשות חיצוני' ונק' לבוש חיצוני' ביותר כי אין ערך כלל לקול דיבור המבטא הגשמי' לדיבור הרוחני' שבנפש כנ\"ל. ועד\"ז יובן ג\"כ באותיו' המח' שהן כמו בחי' לבוש חיצוני' למח' הרוחני' שבנפש עצמה שנק' כח ומקור המח' הגשמי' כנ\"ל (רק שאותיו' המח' בכלי המוח הם רוחניי' יותר וקרובי' יותר לערך הכח מח' רוחני' שבנפש עצמה משא\"כ הדיבור הגשמי המורכב במורגש דאמ\"ר<sup data-n=\"7013\">53</sup> הגשמיי' רחוק ערכם יותר לגבי ערך הרוחני' דאותיו' הדיבור בנפש (וכמ\"ש במ\"א בהפרש שבין נשמות דמח' בחי' ה' ראשונה דהוי' שז\"ש שם הא' שפרה ובין נשמות דדיבור",[["7009","49","<b>שנק' הנפש רוח ממללא</b>: ראה תרגום אונקלוס בראשית ב, ז."],["7010","50","<b>ב' רוחות מספרים זע\"ז</b>: ברכות יח, ב. ראה מאמרי אדה\"א ויקרא ח\"ב ע' תתקכג. דברים ח\"ג ע' תתפ. במדבר ח\"ג ר\"ע א'קעה ובהנסמן שם."],["7011","51","<b>וכמ\"ש במ\"א באריכות. . דה' מוצאות</b>: נסמן לעיל קלט, ב."],["7012","52","<b>אחה\"ע</b>: נסמן לעיל פ' שמות מז, ב."],["7013","53","<b>הדיבור. . המורכב. . דאמ\"ר </b>[ דאש מים רוח]: נסמן לעיל פ' בא קו, ד הערה 435."]]],[2300540250,"בחי' ה\"א אחרונה כו' שהוא בחי' עלמין סתימין ועלמין דאתגליין ונק' מילדות העבריו'<sup data-n=\"7014\">54</sup> בחי' הכח ומקור המוציא לב' מיני אותיו' דמו\"ד מעצמות המאציל כנ\"ל). וזהו מ\"ש בראתי\"ו יצרתי\"ו בראתי\"ו בבחי' העלם המח' הרוחני' שבעצמו' אלקו' יצרתיו בגילוי כח הדיבור דבחי' יצי' שהיצי' גילוי העלם הבריאה כמו שמכח המח' דנפש נמשך ובא לכח הדיבור וממילא נתלבשו אותיות המח' שבמוח באותיו' מבטא הדיבור שהן בחי' הכלי שלהם כו' וד\"ל. ועפי\"ז יובן ג\"כ בענין לבוש הג' שהוא לבוש המעשה שיש בו ג\"כ בחי' אור וכלי כמו במח' ודיבור והענין הוא שבחי' כח המעשה לעשות כל תנועה ופעולה הוא כח רוחני מיוחד שנמשך מעצם הנפש כמו כח המו\"ד הנ\"ל רק שנמשך מחיצוניו' הנפש יותר מכח של מו\"ד (וכידוע שהן ג' מדריגו' דנר\"נ בנפש נשמה במוח שם כח המח' ורוח בלב שם משכן הכח של הדיבור שנק' רוח ממללא שהבל הלב בוקע בה' מוצאות הפה ונפש בכבד<sup data-n=\"7015\">55</sup> שהוא כח המעשה והתנועה שבכל האברי' ונפש מרכבה לגבי רוח<sup data-n=\"7016\">56</sup> ורוח מרכבה לגבי נשמה וע\"כ נק' ב' מדריגות דמו\"ד ב' לבושי' לנר\"נ בכללות וד\"ל.\n<b>ולפי\"ז</b> הרי ההשתלשלות מכח המח' לכח הדיבור וכח הדיבור לכח המעשה בהשתלשלות א' הכל בבחי' הרוחניו' שבנפש עצמה ולא רחוק ערך המעשה לגבי כח הדיבור רק כריחוק ערך כח הדיבור לגבי כח המח' מאחר שכולם בבחי' הרוחניו' דנפש עצמה רק שזה למטה מזה בהדרג' המעלה בעצם מהותן כמו שכח השכל רוחני יותר בעצם מכח המדות וכח הרצון והתענוג רוחני יותר מן כח השכל כו' (ואף בחי' הכלי דמו\"ד גם שם אינו רחוק ערך כלי המעשה שהוא ענין הפעולה והתנועה בעצמה לגבי רוחניו' דמבטא בדיבור גשמי כ\"כ רק כערך ריחוק הגשמת הדיבור לגבי אותיות המח' שכל זה לפ\"ע הדרגת המעלות בעצם כח הפנימי דמחוד\"מ לבד (ומ\"ש<sup data-n=\"7017\">57</sup> אף עשיתיו קאי על הפעולה דמעשה ממש דגם שאינו רחוק כ\"כ מבחי' הדיבור הגשמי מ\"מ זהו דילוג גדול יותר, להיות שבפנימי' הכחות בא ההשתלשלו' מכח המח' עד כח המעשה בהשתוות בערך עד שמיד שירצה במח' יניע בידו ורגלו וכאלו הן מהות א' ממש כו' אבל בחיצוני' הכלים דמחוד\"מ הרי יכול להיות שאין המח' בא בגילוי הדיבור ואין גילוי הדיבור בא לידי מעשה כי המעשה לבנות ולכתוב הוא כמו דבר בפ\"ע וכן הדיבור במהות בפ\"ע נבדל מן המח' שמה שהמח' בא בדיבור זהו רק דרך התלבשות לבד בלתי חיבור וקשר עצמי כלל וכך מן הדיבור אל המעשה כנ\"ל משא\"כ באורות דמחוד\"מ מקושרי'",[["7014","54","<b>שם הא' שפרה. . מילדות העבריו'</b>: שמות א, טו. ראה לעיל פ' שמות כה, ג ואילך. לב, ג ואילך. לג, ד. הנסמן במאמרי אדה\"א ויקרא ח\"א ע' ריג. במדבר ח\"ג ס\"ע תתקמא."],["7015","55","<b>נשמה במוח. . ורוח בלב. . ונפש בכבד</b>: ראה אבן עזרא משפטים כג, כה. יסוד מורא — להנ\"ל — ש\"ז. ע\"ח (שער אח\"פ) ש\"ד, פ\"א. מאמרי אדה\"א דברים ח\"ג ע' תתקיז וש\"נ. בראשית ע' שסה וש\"נ. קונטרסים ע' שכא. וש\"נ. אמ\"ב שער התפילין קכד, א. וש\"נ."],["7016","56","<b>ונפש מרכבה לגבי רוח. . נשמה</b>: זהר לך פג, ב."],["7017","57","<b>לבד (ומ\"ש</b>: אוצ\"ל: לבד) ומ\"ש."]]],[2300540281,"זע\"ז מתחלת כח הרצון שבמח' עד כח המעשה והתנועה (מצד ג' מדריגות דנר\"נ שבמוח ולב וכבד כנ\"ל, וזהו ההפרש בכלל בין כלים ולבושים דכלי' דנר\"נ שהן כח המודו\"מ הן מקושרים זע\"ז והיו לאחדים כנ\"ל ונק' גופי' והלבושי' בחיצוניות דמודו\"מ מופרדי' ומחולקי' זמ\"ז כנ\"ל). וראי' לזה ממה שגם בכלי' פרטי' נמצאי' ג' מדריגות הללו דבי\"ע כמו בכלי היד לעשו' מלאכה יש בה ג' פרקין שהן לנגד ג' מדריגות דחב\"ד וחג\"ת נה\"י כו', כמו בחי' החסד שביד נשתלשל ע\"י ג' מדריגות דג' מיני כלים דהיינו הזרוע וקיבורת ופיסת היד, וכן ברגל<sup data-n=\"7018\">58</sup> יש ג' פרקין שוק וירך ועקב הרגל כו', וגם בראש ומוחין יש ג' כלים פנימי' ואמצעי' וחיצוני' כו', והכל באו כאחד בהיות כולם במהות אחד ממש יחשב כמו היד שגם שכלולה מג' מדריגות בג' פרקין שבה מ\"מ לא נחשב רק אבר יד אחת לבד הגם שיש בה חילוקי מדריגות בג' פרקין הרי כולם ממהות אחד ועושי' כ\"א פעולה אחת רק שיורד בהדרגה בג' כלים רת\"ס שבהן, משא\"כ בלבושי' דמחדו\"מ הגם שיש בכאו\"א ג' כלים דמדו\"מ וכמ\"ש במ\"א דבחי' עשי' דמח' נעשה מח' בדיבור<sup data-n=\"7019\">59</sup> כו' מ\"מ הרי הדיבור נבדל ומופרד מן המח' וכש\"כ המעשה שנפרדת יותר מן הדיבור כנ\"ל לפי שאין מודו\"מ רק בבחי' לבוש בלבד ולא בבחי' כלי ואבר כאברי הגוף כיד ורגל הנ\"ל, רק בבחי' הכלים ואברים יש קשר וחיבור יותר לקו האמצעי דת\"י מן ההרהור המח' שאין קישוי אלא לדעת<sup data-n=\"7020\">60</sup> כו' משא\"כ ביד ורגל שאינם קשורים כ\"כ כמ\"ש במ\"א).\n<b>והנה</b> הדוגמא מכל הנ\"ל יובן למעלה בסדר ההשתלשלות דאבי\"ע שכל עולם כלול מג' מדריגות דבי\"ע דגם האצי' כלול מבי\"ע<sup data-n=\"7021\">61</sup> בכלל ובפרט בכל ספי' כו' שכ\"ז יובן עפ\"י משל המודו\"מ שיש בזה ב' אופנים, א' בבחי' הכוחות דמוד\"מ עצמן כך במע\"ב נק' בג' מדריגות דבי\"ע כמו בראשית ברא<sup data-n=\"7022\">62</sup> וכן יצר ועשה<sup data-n=\"7023\">63</sup> וכך בנשמות שהן בבחי' פנימי' העולמות נק' בג' מדריגות הללו כמ\"ש בראתיו יצרתיו אף עשיתיו, שיש בכללות ב' אופני' דאורו' דבי\"ע וכלים ולבושים החיצוני' כמו בכלל נק' עולם הבריאה עלמין סתימין דלא אתגליין שהן נבראי' מבחי' אותיו' המח' עליונה ועולם היצי' נק' עלמין דאתגליין שנברא מן הדבור שמגלה העלם המח' כמו ברוח פיו כל צבאם וכמ\"ש בס\"י וקבען בפה<sup data-n=\"7024\">64</sup> בכ\"ב אותיו' הדבור והרי יש בזה מדריגה הפנימי' דמו\"ד נמשכו מעצמו' הנפש כנ\"ל, ומדריגה הב' בחיצוני' הכלים דמו\"ד בבחי' אותיות וקרובי' זא\"ז בהשתלשלות וגם בבחי' המעשה בחי' כח העשי' שלזה נק' מע\"ב בכלל ומתאחד עם כח",[["7018","58","<b>היד. . יש בה ג' פרקין. . וכן ברגל</b>: נסמן לעיל פ' שמות מה, א."],["7019","59","<b>דבחי' עשי' דמח' נעשה מח' בדיבור </b>[אוצ\"ל: שבדיבור]: ראה גם לעיל קמד, א ובהנסמן לשם."],["7020","60","<b>שאין קישוי אלא לדעת</b>: יבמות נג, סע\"ב. ראה לקמן פ' יתרו עדר, ג. תצוה שנח, ב. מאמרי אדה\"ז תקס\"ב ח\"ב ע' שלו. תקס\"ו ע' קכ [וכן צ\"ל ב]מאמרי אדה\"א במדבר ח\"ג ע' א'קמה וש\"נ. ח\"ד ע' א'תקכד. וש\"נ."],["7021","61","<b>האצי' כלול מבי\"ע</b>: ראה ע\"ח (שער כללות אבי\"ע) שמ\"ב, פ\"ד. לקמן קצ, ג. וראה גם לעיל פ' שמות כד, ד הערה 63."],["7022","62","<b>בראשית ברא</b>: בראשית א, א."],["7023","63","<b>יצר ועשה</b>: שם ב, ז. ח. יט. שם א, ז."],["7024","64","<b>וכמ\"ש בס\"י וקבען בפה</b>: ראה שם פ\"ב, מ\"ג."]]],[2300540309,"המו\"ד בקירוב כנ\"ל, אבל בחי' המעשה עצמה נבדל ומופרד מאותיות הדבור (וכמו הגלגלי' דעשי' שהן בבחי' עשי' נבדלת מכח הפועל האלקי), ואמנם בבחי' עשי' שנזכר בפועל אברי' כמו אף ידי יסדה ארץ<sup data-n=\"7025\">65</sup> וימיני טפחה כו' ובכלל נק' מעשה ידיו<sup data-n=\"7026\">66</sup> וכו' שזהו כמו כח המעשה ביד ורגל שמתאחד המו\"ד וגם בכח המדות ורצון כו' וכמו כל אשר חפץ ה' עשה<sup data-n=\"7027\">67</sup> כמשל הרצון במוח שינוע הרגל כו' וד\"ל. ועד\"ז יובן גם למעלה מעלה באצי' שכלול מבי\"ע שהן בחי' מחוד\"מ דאצי' עד עשי' דאצי' יש ב' אופנים הללו בפנימי' וחיצוני' וגם בכללות כל ההשתלשלות שיש ג' מיני אדם<sup data-n=\"7028\">68</sup> א\"ק אדם דבריאה וע\"י נק' אדם דיצי' וז\"א נק' אדם דעשי' יובן ג\"כ ע\"ד הנ\"ל בב' אופנים וד\"ל.\n<b>והנה</b> להבין בתוס' ביאור ענין ג' מדריגות דמחודו\"מ הנק' בי\"ע באופן שגם בבחי' לבושים חיצוני' שלהם מתקשרים כא' כאלו הן מהות א' רק שיורד בהדרגה כנ\"ל באברי היד שכלול מג' פרקין כו', דהנה מבואר למעלה בענין ברי' ויצי' שנק' העלם וגילוי כחושך ואור כו'. הנה יובן עד\"מ אומן העושה כלי הרי תחלה יעלה במחשבתו כללות מעשה הכלי באופן ציורה ותוכה וגבה כו' ואח\"כ יצוייר במח' כל פרטי אופני מעשיה איך לעשותה בפועל ידיו ממש ואח\"כ עושה כל ציור מעשיה בפועל ידיו, הרי ודאי לא נתחדש דבר בכל פרט ופרט במעשה הכלי הכל כמו שכבר ציירה הכל במח' דוקא לא יוסיף ולא יגרע כי בכל רגע פועל בידיו רק כפי הציור במחשבתו כידוע רק שבמח' הציור בבחי' רוחניו' דמח' שהוא בהעלם ובציור בפועל ידיו בא לידי גילוי. והנה הכלי עצמה שעושה אותה בציור הרי אין הציור שבה דבר נוסף ומחודש על עצם מהות ממשות שלה כמו הכסף הגולמא שנק' חומר שממנו עושה הכלי שמוכן לעשות בו כל ציור שירצה, כאשר נעשה בו הציור זהו הכל בגופו של כסף עצמו ואינו מחדש בו דבר ע\"י הציור כ\"א רק כמו בחי' גילוי ההעלם לבד והצורה בחומר אינו רק בחי' הגילוי שלו באופן צורתו ותוארו לבד ואין שינוי וחידוש מזה הציור או כשיצייר בצורה אחרת בגוף החומר כלל, וה\"ז כמו הדבור שמצייר בגילוי אופן התחלקות העלם המח' שאין התחדשו' כלל בגוף הדיבור ומהותו רק שהדיבור עושה הציור שלו (וכמו הכסף שהוא החומר הפשוט שבו נעשה הציור כך במח' עדיין זה ברוחניו' והעלם כללי' מעשה הכלי (כמו שיצייר במח' איזה דבר מה כגון בנין או אילן שנסקר כולו כא' ואח\"כ בראותו מקרוב רואה בו כל פרטיו, כך הפרט של התחלקות של הדבור כלול במח' שהרי המח' א' יתחלק בדיבור לריבוי צירופי' כו' וגם מה שמצייר במח' פרטי אופני הבנין או הכלי נסקר הכל כא' בבחי' הרוחניו' עדיין). והמדריגה הג' הוא גמר מעשה הכלי באופן ציורה בתוך",[["7025","65","<b>אף ידי יסדה ארץ</b>: ישעי' מח, יג."],["7026","66","<b>מעשה ידיו</b>: ראה ישעי' ה, יב. תהלים יט, ב. כח, ה. ועוד."],["7027","67","<b>כל אשר חפץ ה' עשה</b>: תהלים קלה, ו."],["7028","68","<b>ג' מיני אדם</b>: ראה הערה בספר המאמרים תש\"ח ע' 113. מאמרי אדה\"ז ענינים בתחלתו ובהנסמן לשם. אוה\"ת ענינים ע' עז ואילך."]]],[2300540334,"ובית קיבול שיהי' נק' בשם כלי תשמיש שזהו עיקר בחי' העשי' שהוא התיקון כמו לעשות לתקן<sup data-n=\"7029\">69</sup> וכמו ועשתה את צפרניה ות\"א ותתקן<sup data-n=\"7030\">70</sup> כו', והוא ענין א' עם הציור רק שבא לפועל תכלית מעשה הציור ולא מצד עצם הציור והתואר כמו הגביע שאין ציורו עצם ותכלית רק כאשר פועלים ומשתמשים בו והוא החלל בית קיבול שלו דוקא, וכן כל כלי מעשה המכוון שבו הוא התשמיש שמשתמשין בו ולא עצם הציור רק לתפארת למראה מייפין הציור ולא לתכלית התועלת שבו, וכן בציור כל הברואי' דחי ומדבר כל הפרטי' שבציור הכל לתכלי' הפעולה שפועל בהן בציור הכלי של העין<sup data-n=\"7031\">71</sup> וכלי האוזן לשמוע והיד לעשות מלאכה והרגל להילוך ובלא פעולות הללו אין ציור האברים כלום. ונמצא פעולת הראי' והשמיע' והילוך הוא שלימות מעשה הציור שלהם וכך התועלת של תוך בית קיבול לקבלת המשקה בכוס הוא ענין שלימות ותיקון של הכלי משא\"כ כשלא נשלם בתיקון זה שאין ציורו עיקר כידוע.\n<b>וכך</b> יובן בכללות כל התהוות דבר מה במציאות מיש ליש שיש בו ג' מדריגות הנ\"ל במעשה הכלי' שכלולי' כא' ממש שהרי מה שהכלי בא תחלה במח' בהעלם ונצטייר בפועל ונתקן למעשה תשמישו ונעשה כלי ממש הכל כדבר א' חשובים שהרי גופו של כסף וממשו עדיין ישנו כמו שהוא גם אחר שנצטיירו בפועל ונעשה כלי בית קיבול ולא נשתנה בזה כלל וכלל, לפי שכל מדריגה הבאה מיש ליש ולא יש מאין אין בזה שינוי המהו' למהות אחר כלל רק באותו המהות עצמו כ\"א שבא בהדרגה וירידה לבד, כמו בענין פעולת היד שכלול מג' פרקין שגם שחלקו לג' מדריגו' הכל כדבר א' ממש חשיבא רק שיורד בהדרגה עד שיוכל להיות פעולת המלאכה שביד, וכך הוא בענין ג' מדריגות דמח' דו\"מ שמן המח' אל הדיבור הרי הוא בא מיש ליש שאין כל חדש כלל בדבור רק מה שהי' במח' שזהו נק' יש מיש ע\"כ אין בדבור שינוי המהות כלל רק אותה מהות המח' ממש באה ויצאה לגילוי בכח הדיבור ונצטייר בציור אותיו' הדבור, וכן מן הדבור אל המעשה בפועל הרי ציור אותיו' הדבור הוא שבא לפועל המעשה רק שהוא ציור המעשה בהגשמה יותר, ונמצא המעשה עצמה היא מהות המח' ממש ומה שירדה במדריגה מעילה לעלול הוא במהות ועצמות הדבר שבמח' בלי שינוי מהות כלל וכלל. ונמצא מובן שגם בג' לבושים דמח' דו\"מ הנ\"ל מתקשרי' ובאי' כא' מפני שמהות א' הן רק שירד בהדרגה כו' כנ\"ל וד\"ל (רק שאין משל חומר הכסף שהוא רק הגולמא שלמטה מן הציור דומה עם ענין המח' שבהעלם שהוא למעלה מן הציור כו', אך מבואר במ\"א שיש ב' מיני חומר<sup data-n=\"7032\">72</sup> א' חומר הגשמי שנק' גולמא ושרשו חומר הב' שהוא",[["7029","69","<b>לעשות לתקן</b>: בראשית ב, ג. ראה ב\"ר פי\"א, ו ובפרש\"י שם. הנסמן במאמרי אדה\"א ויקרא ח\"ב ע' תתסח. דברים ח\"ד ע' א'רט. סה\"מ תרצ\"ז ע' 214."],["7030","70","<b>ועשתה את צפרניה ות\"א ותתקן</b>: תצא כא, יב. ראה רש\"י בראשית א, ז. מובא בשם ”הת\"א\" גם בסה\"מ תרס\"ב ע' שנז. תער\"ב ח\"ג ע' א'שפט. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300251343\" data-slug=\"likkutei-sichot\" data-id=\"1300251343\">לקו\"ש תולדות (כרך כה) ע' 343</a> בהערה 30."],["7031","71","<b>העין</b>: אוצ\"ל: העין לראות."],["7032","72","<b>שיש ב' מיני חומר</b>: ראה מאמרי אדה\"ז נביאים ע' קג בשם הע\"ח."]]],[2300540357,"חומר ההיולי שנק' חומר הפשוט שלמעלה מן הצורה, וכך הוא ענין משל המח' שבהעלם שבא לציור הדבר ושלימותו הוא בא דוקא בבחי' המעשה בתיקון כלי דוקא שהוא עיקר התועלת מן הציור הזה וכמו שהגולמא דחומר הגוף דאדה\"ר שנעשה בו הצורה דאדם אין זה שלימותו עדיין עד שנעשה כלי גמור בתיקון פעולת האברי' כמו בראי' ושמיע' והילוך כו'. וז\"ש לכבודי בראתיו במח' בהעלם שזהו הנשמה כמו שהיא בהעלם עדיין ובאה לגילוי ביצי' בציור החומר שהוא הגולם והיינו יצרתי\"ו אף עשיתי\"ו אף זה רבותא ולא להקטין הענין אדרבה אף עשיתיו בבחי' תיקון כלי גמור כנ\"ל בבחי' פעולת מעשה הכלי שהוא שלימות דמח' שבהעלם כו'). וכך הוא בכל ההשתלשלות דברואי' מיש ליש בכל עולם ועולם בכללות ובפרט בכל דבר ברי' והתהוות, שגם שא\"א בלא ג' מדריגו' דמח' ודו\"מ שהן בי\"ע בהעלם וגילוי ומעשה מ\"מ הכל כדבר א' ממש שזהו הנק' השתלשלות יש מיש עו\"ע בבחי' העלם וגילוי ומעשה עד רום המעלות גם באצי' ולמעלה מן האצי' במקור הראשון דע\"ס באורות וכלים כמו בחי' א\"ק שנק' אדם דבריאה בכללות ההשתלשלות שזהו כמו בעולם הבריאה שלמטה מן האצי' שבא בבחי' ההשתלשלות יש מיש מח' ודו\"מ הרי א\"ק הוא נק' אדם דבריאה שהוא בחי' המח', וע\"י וא\"א נק' אדם דיצי' בחי' הדבור וז\"א בבחי' עשי' כו' וד\"ל (ולפי המובן מהנ\"ל בג' מדריגות הרי בחי' העשי' דאצי' שרשו במח' דבריא' דאצי' באופן שהוא שלימות של המח' וכמאמ' סוף מעשה עבמ\"ת<sup data-n=\"7033\">73</sup> וכמשי\"ת בע\"ה<sup data-n=\"7034\">*74</sup>.\n<b>והנה</b> יש עוד מדריגה רביעית שלמעלה מן ג' מדריגות המח' ודו\"מ הנק' בי\"ע והוא הנק' יש מאין ולא יש מיש, דהנה מח' שנמשך לדבור ומדבור למעשה נק' יש מיש כו' אבל המח' עצמה שיצאה מן השכל או הרצון לא נק' יש מיש אלא יש מאין דוקא, דהיינו שמציא' המח' באה מבחי' אין דשכל בבחי' שינוי המהות לגמרי שלא הי' מציאת המח' תחלה כלל גם לא בהעלם בשכל שהרי מהות המח' כמו דבר זר נחשב לגבי עצם אור השכל הרוחני בלתי יש שום ערך והשתוות זע\"ז כלל עד שנאמר שגופו ומהותו של השכל הוא שנעשה במהות מח' בירידת המדריגו' (כמח' עצמה שנעשה במהות הדיבור או ככסף המצטייר הנ\"ל), אלא המח' היא בריאה חדשה ממש במהות שלא הי' לה מציאו' בתחלה כלל רק כמו שיוצא ונמשך יש מאין ממש שאין ערך ויחוס כלל למציאו' היש עם בחי' האין הרוחני שאינו בסוג מציאת דיש כלל ולא הי' מציא' היש באין<sup data-n=\"7035\">74</sup> כלל לומר שיצא משם מן ההעלם לגילוי רק שיצא מחודש ממש והוא הנק' יש מאין כמ\"ש במ\"א<sup data-n=\"7036\">75</sup> (כמו שאנו רואי' בחוש שמח' דאותיו' השכל אינם נמצאי' במהות אור השכל כלל רק נתחדשו מציאותן",[["7033","73","<b>סוף מעשה עבמ\"ח</b>: פיוט לכה דודי."],["7034","*74","<b>בע\"ה</b>: כנצ\"ל: בע\"ה)."],["7035","74","<b>ולא הי' מציא' היש באין</b>: ראה לעיל קלט, ד. מאמרי אדה\"ז תקס\"ג ח\"א ע' רצב ואילך (ב' הנוסחאות). שער האמונה נ, א."],["7036","75","<b>כמ\"ש במ\"א</b>: ראה גם לעיל פ' בא קלא, ג ובהנסמן לשם."]]],[2300540379,"ממש<sup data-n=\"7037\">76</sup> (וגם החכ' שנק' מח' סתימא' מאין תמצא שהוא עיקר א\"ק כו'). והנמשל מזה יובן מזה<sup data-n=\"7038\">*77</sup> בכללות בין באצי' בין בבריאה ולמעלה מעלה דכלולי' מג' מדריגות דבי\"ע שהן נקודים עקודים וברודי' כו' שכל זה נק' יש מיש אבל בחי' א\"ק עצמו שנק' אדם דבריאה בכלל הגם שהוא נק' ג\"כ יש אבל התהוות מציאות' מעצמו' א\"ס הוא בבחי' יש מאין ממש בשינוי המהות לגמרי כמו המח' לגבי השכל כנ\"ל ואין לו ערך כלל לגבי העצמו' כו', וע\"כ נק' אדם דבריאה ע\"ש שנברא מאין ליש כמו אדה\"ר למטה שנברא מאין ליש ממש הגם שכלול מג' מדריגות דבי\"ע שהן מח' ודו\"מ הנ\"ל וכמ\"ש בראתיו יצרתיו אף עשיתיו זהו בבחי' ההשתלשלות דיש מיש שיש להן ערך והשתוות מזה לזה כנ\"ל (והיינו ענין וכל קומה דא\"ק לפניך לבד תשתחוה<sup data-n=\"7039\">77</sup> כו').\n<b>והנה</b> ג' מדריגו' הנ\"ל בבחי' מח' ודו\"מ שהן בי\"ע הנ\"ל יובן ג\"כ ע\"ד הנ\"ל בעבודה שבלב ומוח בתפלה, ויובן זה תחלה במילי דעלמא בנה\"ט שכלולה ג\"כ ממדו\"מ שהן בי\"ע ושכל ומדו\"מ<sup data-n=\"7040\">78</sup> כידוע, דהנה כאשר האדם חושק ומתאוה לאיזה דבר טוב שנוגע לחיי נפשו ממש כמו העסק במו\"מ שימצא טרף מזונו להחיות נפשו באיזה ריוח שיגיע לו מן העסק מו\"מ הזה, הרי תחלה יתחיל להעמיק דעתו ושכלו להשכיל ולהתחכם בכמה מיני שכליי' ותחבולות שונות איך שיגיע לו ריוח וכל שיתחכם יותר יותר ימצא אופני הריוח וכמו והחכ' תחי' בעלי'<sup data-n=\"7041\">79</sup> תחי' ממש כידוע, משא\"כ כשעושה העסק מו\"מ בלא דעת ושכל כלל יוכל לבא לידי הפסד לגמרי כו'. אך יש עוד עסק פרנסה שמפרנס אדם א\"ע שהוא בלא יגיעה ושכל בדעת כלל וכלל והוא כמו המלאכ' הגשמי' שא\"צ רק לעסוק בגופו כמו החרישה וזריעה בעבודה שבשדה וכחוטב עצים וכה\"ג שיוכל לעשות גם החסר דיעה לגמרי וימצא לו פרנסתו בשלימו' מעבודה זו, ויש שיתפרנס מאומנו' כאומני' במלאכתם שיש בזה שכל וחכ' עכ\"פ רק שנק' שכל שבעשי' לבד וזהו המתפרנס מיגיע כפו, ואעפ\"י שרחוק ערך האומנו' בכלי ביגיע כפיו וכל עבודת גופו בגשמיו' לגבי השכל והתחכמו' שימצא לענין פרנסתו במו\"מ, עכ\"ז הכל ענין א' הוא שהרי עיקר ריוח הפרנסה להחיות נפשו לבד רק שזה ירויח וימצא טרף מזונו ע\"י שכלו וחכמתו בהתחכמו' המח' ביותר או ע\"י מידותיו בלבו בחשק וזירוז טוב לתכלית העסק בהנהגה טובה וישרה כו' וזה ירויח ע\"י עבודתו בגופו ויגיע כפו בכשרון מעשה מלאכתו, ושניהם אינם רק בחי' לבושי' לבד לפנימי' ועיקר הדבר שהוא הריוח שיגיע לו לפרנסת ביתו, רק שהשכל והתחכמו' הוא בחי' לבוש פנימי המלביש לפנימי' המכוון הזה שהוא הריוח והענין דמלאכה בגופו מיגיע כפו הוא לבוש חיצוני יותר בהגשמה וכן העסק בפרנסתו בשכל ומדות וגם ע\"י יגיע כפיו ועבודה שבגופו ממש ה\"ז לבושים דלבושים,",[["7037","76","<b>ממש</b>: אוצ\"ל: ממש)."],["7038","*77","<b>מזה</b>: אולי תיבה זו מיותרת."],["7039","77","<b>וכל קומה. . לפניך. . תשתחוה</b>: תפלת (שחרית לשוי\"ט) נשמת. וראה גם לקמן רה, ד. פ' תרומה שיד, ב. תצוה שלו, ב. ויקהל שפט, ב. מאמרי אדה\"ז תק\"ע ע' מו. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670026\" data-slug=\"torat-chaim\" data-id=\"2300670026\">תו\"ח בראשית ל, א</a> ובהערה 5. שעה\"י קמו, א."],["7040","78","<b>ומדו\"מ</b>: אוצ\"ל: ומדות."],["7041","79","<b>והחכ' תחי' בעלי'</b>: קהלת ז, יב [ושם: החכמה — נסמן לעיל פ' שמות ב, ב]."]]],[2300540399,"דלבוש חיצוני דעבודה שמלביש ללבוש הפנימי של שכלו ומח' ושכלו ומח' מלביש לפנימי' הדבר שהוא הריוח, וכך הוא בכל עסק מו\"מ כשמעמיק מחשבתו ודעתו וגם לבבו עד שבא לכלל עבודה בגופו שכל זה רק לבושים שהוא בחי' ג' לבושים דמוד\"מ שכולם נחשבות כא' ממש להיותם בבחי' יש מיש לבד כנ\"ל כשזה מלביש לזה שהוא בחי' העלם וגילוי כו' כנ\"ל, אבל פנימי' הדבר עצמו שהוא הריוח שהגיע מן העסק במחדו\"מ זהו בא בלתי לבושים כלל ואין ללבושי' דמחדו\"מ ערוך לו כלל כי הוא נקודה הפנימי' שאינו נתפס בלבושי' כמו שהוא בעצם מהותו רק שמוכרח הוא להתלבש במחדו\"מ כדי שימצא הריוח מפני שבלעדם לא יגיע הריוח, אבל אם הי' יכול להיות ריוח פרנסה בלא יגיעה בשכל ולא בעבודה לא הי' מתייגע כלל לא בשכל ולא בעבודה שבגופו כי אינם רק דרך מעבר ולבוש כו'. אך בזה הוא נתפס ממש כמו שהוא הנה זהו נתפס רק בבחי' פנימי' נקודת הלב שהוא פנימי' נקודת הרצון העצמי' שבנפשו שלמעלה לגמרי מן השכל והמעשה כו', כי הרי כל נקודת הרצון שבלבבו אינו רק שיגיע לו הריוח שהוא הפיקוח לנפשו להחיותה שלזאת נושא את נפשו ממש כי בנפשו ממש יביא לחמו<sup data-n=\"7042\">80</sup> וטרף מזונו שהוא רק ענין הריוח מעות שימצא, והוא מחמת שאוהב חיי נפשו ורוצה בקיומה לחיות ולא למות ברעב כו', ונקודת רצונו זה הרי אינו בא בלבושי' דשכל ומדות כלל כמו שהוא ממש רק ע\"י מעבר ולבוש שמתלבש בהן כדי שימצא רצון נפשו רק הוא בהעלם בעצמיו' הנפש שיחפוץ לחיות יהי' איך שיהי' כו', ואח\"כ יבא זה לגילוי בלבושי' וכלי' שעל ידם ימצא זה החיות אם ע\"י התחכמות שכלו אם ע\"י מלאכה ועבודה אין הפרש לו כלל בין זה לזה יהי' איך שיהי' רק שימצא טרף לנפשו להחיותה כו' וד\"ל.\n<b>והנה</b> הדוגמא מכל זה יובן ג\"כ בנפש האלקי' בעבודת ה' בתפלה כידוע שבאמת כל מה שיגיע האדם להתפעלות אלקו' באה\"ר במס\"נ אמיתי ע\"י ההתבוננות בגדולת הבורא בהשגה והבנה ביח\"ע ויח\"ת וכה\"ג זהו הכל רק בבחי' לבושים בלבד שמלביש לנקודת פנימי' הרצון כמו שהוא בעצם מהותו שהוא אינו בא ונתפס כמו שהוא ממש בשום לבוש, כי ההשגה האלקי' הגם שמתפעל על ידה אין זה רק כמו שע\"י התחכמו' במו\"מ ישיג הריוח שאינו אלא לבוש לריוח כנ\"ל, כך ההתחכמות בהשגה אלקי' נק' לבוש ומעבר בעלמא שעי\"ז יבא לפנימי' המכוון שהוא להחיות חיי נפשו בחיי החיים<sup data-n=\"7043\">81</sup> עצמו' אא\"ס ב\"ה כמו שנקודת לב האדם לחיו' בחיי הגשמיי' וכמ\"ש כי הוא חייך<sup data-n=\"7044\">82</sup> ממש וכמו ובחרת בחיים<sup data-n=\"7045\">83</sup> כו' וכידוע, ונקודת הפנימי' הזאת היא בהעלם בעצמו' הנה\"א שבא במס\"נ ממש עד כלות כו' וכמו נכספה וגם כלתה נפשי<sup data-n=\"7046\">84</sup> כו' וכן כלה שארי ולבבי<sup data-n=\"7047\">85</sup> כו' צמאה",[["7042","80","<b>בנפשו. . יביא לחמו</b>: פיוט (לימים נוראים — קודם קדושת כתר) כי כשמך."],["7043","81","<b>בחיי החיים</b>: יומא עא, א."],["7044","82","<b>כי הוא חייך</b>: נצבים ל, כ."],["7045","83","<b>ובחרת בחיים</b>: נצבים שם, יט."],["7046","84","<b>נכספה וגם כלתה נפשי</b>: תהלים פד, ג."],["7047","85","<b>כלה שארי ולבבי</b>: שם עג, כו."]]],[2300540419,"לך נפשי<sup data-n=\"7048\">86</sup> כו' וכה\"ג, והוא בלתי מתלבש בלבוש דשכל וטעם כלל וכלל רק רצון פשוט ועצמי מעצמו' הנפש ממש והוא הנק' נקודה רעותא דלבא<sup data-n=\"7049\">87</sup> מעומקא דעומקא כו' שהוא בבחי' אין ממש ליכלל באין האלקי כניצוץ הנמשך אחר מקורו כו' כמו משכני אחריך נרוצה<sup data-n=\"7050\">88</sup> ממילא ומאיליו כידוע, ומה שישכיל וישיג בהשגה אא\"ס וכל ההשתלשלות איך דקמי' כולא כלא כו' ויתפעל מזה ביותר הכל הוא בא מחמת בחי' נקודת הלב הפנימי' הנ\"ל שחפצה למצא טרף להחיות נפשה באור החיים ורוצה מאוד בקיומה והתקשרותה בעצמו' אא\"ס דוקא ע\"כ הוא מעמיק דעתו וחכמתו ועי\"ז ימצא טרף מזונו ויחי' בחיי החיים כמו ע\"י התחכמו' המו\"מ וכנ\"ל, וכמו ענין טעמו וראו כי טוב ה'<sup data-n=\"7051\">89</sup> ע\"י בחי' טעם ודעת כו', או אם אין בו דעת וחכ' להשכיל בהשג' אלקות בגדולת ה' כו' דלאו בר הכי הוא כלל, אז ימצא חיות נפשו האלקי' ע\"י מלאכה ועבודה גשמיו' כמו ע\"י העבודה דמעשה המצות דכתי' אלה המצות כו' וחי בהם<sup data-n=\"7052\">90</sup> ממש כמו ע\"י החכ' והשגה האלקי' (שע\"ז א' והחכ' תחי' בעליה דחכ' שהוא עצם הנשמה האלקי') אין הפרש כלל בין שיחי' נפשו מחכ' או ע\"י העבודה יהי' איך שיהי' רק שיחי' בחיי אלקות ולא ימות בבחי' הפירוד מאלקות שנק' מות ברוחניו' דנשמה כמ\"ש נתתי לפניך החיים והטוב<sup data-n=\"7053\">91</sup> והמות והרע ובחרת בחיים כו' וכן א' שובו כו' ולמה תמותון<sup data-n=\"7054\">92</sup> כו' כידוע, וגם ע\"י עסק התו' במחדו\"מ המצוה נק' גם הם לבושים לנשמה שהוא בחי' יש מיש וכא' באי' כנ\"ל בעסק המו\"מ במחדו\"מ כו' שזה מלביש לזה כנ\"ל וכולם מלבישים לפנימי' הנקודה של הלב להדבק ולהכלל בחיי החיים כו' רק שזהו לבוש פנימי וזהו לבוש חיצוני יותר (ועכ\"ז בסוף מעשה דמצוה דוקא שם הוא שלימות דלבוש המח' שהוא בבחי' יש מאין ג\"כ כנ\"ל). אך סדר התחלת עבודת ה' צריך להיות מלמטה למעלה שהוא העבודה והיגיעה בהתבוננות ומדות אוי\"ר וע\"י עבודה במעשה המצוה עד שיגיע לנקודה הפנימי' דמס\"נ מצד העצמו' דא\"ס ב\"ה ממש, אבל כשמגיע לזה המכוון הפנימי הרי כל מה שקדם לזה הכל הוא רק בחי' לבושים וכלים מכלים שוני' שהן רק בדרך מעבר בעלמא כנ\"ל וד\"ל. וזהו ענין ההפרש בין בי\"ע שהן ג' מדריגות דשכל ומדות ומעשה שנק' יש מיש ובין בחי' הבריאה עצמה שהוא החכ' ומח' הרי הוא יש מאין דוקא כנ\"ל, והיינו בחי' נקודת הלב דרצון הפנימי הנ\"ל שהוא בבחי' אין ממש והוא בחי' אין של היש דחכ' ומח' כמ\"ש והחכ' מאין תמצא<sup data-n=\"7055\">93</sup> (כך החכ' שתחי' בעלי' בהשגה אלקי' נמצא מאין דנקודת הרצון העצמי כו' וד\"ל).\n<b>ונמצא</b> מובן מכ\"ז דעצמו' אוא\"ס ממש אינו שורה כ\"א בבחי' נקודת הרצון שבלב שהוא בבחי' אין ולא בלבושים",[["7048","86","<b>צמאה לך נפשי</b>: תהלים סג, ב."],["7049","87","<b>רעותא דלבא</b>: זהר וירא ק, א."],["7050","88","<b>משכני אחריך נרוצה</b>: שה\"ש א, ד."],["7051","89","<b>טעמו וראו כי טוב ה'</b>: תהלים לד, ט. ראה מאמרי אדה\"א בראשית ע' קיט."],["7052","90","<b>אלה המצות. . וחי בהם</b>: נסמן לקמן קעה, ד."],["7053","91","<b>נתתי לפניך החיים והטוב</b>: נצבים ל, טו [בשינוי — ראה גם לקמן ריא, ג. פ' יתרו רעו, ד. מאמרי אדה\"א שמות ח\"ב ע' תקעג. וש\"נ. ש\"א נב, א. לקמן פ' תצוה שסג, ד]."],["7054","92","<b>שובו. . ולמה תמותון</b>: יחזקאל ג, יא [ושם: תמותו]."],["7055","93","<b>והחכ' מאין תמצא</b>: איוב כח, יב."]]],[2300540439,"דשכל ומדות דאוי\"ר ודו\"מ שהן בבחי' יש מפני שהוא ית' עצמו אינו נתפס כלל בבחי' לבושים דמוחי' ומדו' עליונו' דאצי' דלמתב\"כ<sup data-n=\"7056\">94</sup> (אפי' מח' דא\"ק שנק' אדם דבריאה בכלל הרי הוא עכ\"פ בבחי' יש רק שהוא מאין כנ\"ל), ומובן ממילא מזה דעיקר מהות התפעלות נקודת פנימי' הלב לא תהי' באדם כ\"א לעצמו' אא\"ס ב\"ה הפשוט בתכלית שלמעלה מן ההשתלשלות דחכ' ומדות כו' דאבי\"ע כמו שהוא טרם שיתלבש בלבושי' דהשתלשלות, משא\"כ התפעלות השכל והדעת והמדות אוי\"ר שנולדים מהן הוא ביח\"ע ויח\"ת<sup data-n=\"7057\">95</sup> דאבי\"ע שנק' בחי' לבושים לבד לגבי מהו\"ע דלמתב\"כ כו', וזהו שדקדק לומר לית מח' תפיסא בך ממש מח' דוקא אבל רעותא דלבא הנ\"ל יש לו תפיסא<sup data-n=\"7058\">96</sup> בך ממש מטעם הנ\"ל וד\"ל (גם סוף מעשה המצות שהוא בחי' התיקון דכלי המעשה מגיע לבחי' האין ממש שלמעלה מן המח' כנ\"ל, וז\"ש במצות דוקא וחי בהם מעצמות חיי החיים ממש כמו שהוא בנקוד' הרצון הפנימי ונעוץ תחילתן בסופן<sup data-n=\"7059\">97</sup> דוקא וכמ\"ש סוף דבר כו' כי זה כל האדם<sup data-n=\"7060\">98</sup> כו'). וזהו קרוב ה' לכל<sup data-n=\"7061\">99</sup> כו' פי' הקריא' היא בפנימי' נקודת הלב דוקא הוא שיקראוהו באמת בבחי' אמיתית עצמו' ית' כמו שהוא ממש (או באותיות דתו\"מ מטעם הנ\"ל) שזהו בחי' האין של היש שלמעלה גם מבחי' א\"ק שנק' אדם דבריא' בכלל הנ\"ל, ואעפ\"י שקרוב לכל קוראיו ע\"י בחי' הדעת והשגה ומדות דאוי\"ר אבל הכל הוא כדי שיקראוהו באמת מתוך נקודת פנימי' הלב ששם שורה עצמותו ית' ממש שלמעלה מבחי' לבושים (אפי' מבחי' לבוש דמקיפי' העליוני' כמ\"ש השמים ושמי השמים מקיף למקיף לא יכלכלוך<sup data-n=\"7062\">100</sup> וכמ\"ש כי גאה גאה<sup data-n=\"7063\">101</sup> על גיאות דלבוש המקיף למקיף הוא רם ונבדל כנ\"ל מפני שבעצמו' ממש לא שייך לומר גם בחי' התנשאות על העלול ממנה דכולא קמי' כלא כו', ומה שנק' עילות העילות<sup data-n=\"7064\">102</sup> זהו בחי' אין של היש דא\"ק כו'). ונמצא מובן מכל הנ\"ל דאין עצמו' א\"ס ממש שורה כ\"א בעצמו' נקודת הרצון או בסוף מעשה דבחי' התיקון הכלי' כמ\"ש לעשו\"ת לתקן כו' שהוא דוקא שנק' אדם אדמ\"ה לעליון<sup data-n=\"7065\">103</sup> ממש (וזהו אף עשיתי\"ו לרבותא יתירה מבראתיו דמח' כנ\"ל).\n<b>ובכ\"ז</b> יובן שרש ענין קי\"ס שבבחי' ההעלם דים עצמו נעשה בחי' גילוי כנ\"ל שזהו למעלה מסדר ההשתלשלות דעו\"ע דחיצוני' העילה משפיע לעלול כו' כאותיות המח' בדיבור",[["7056","94","<b>דלמתב\"כ</b>: ראה ת\"ז בהקדמה (יז, א)."],["7057","95","<b>ביח\"ע ויח\"ת</b>: זהר בהקדמה (יב, א)."],["7058","96","<b>אבל רעותא דלבא. . יש לו תפיסא</b>: ראה זהר (אד\"ז) האזינו רפט, ב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680128\" data-slug=\"torat-chaim\" data-id=\"2300680128\">תו\"ח וישב קצט, ג</a> ובהערה 56. שע\"ת קכה, א."],["7059","97","<b>ונעוץ תחילתן בסופן</b>: ראה ס\"י פ\"א, מ\"ז."],["7060","98","<b>סוף דבר. . כי זה כל האדם</b>: קהלת יב, יג."],["7061","99","<b>קרוב ה' לכל</b>: תהלים קמה, יח."],["7062","100","<b>השמים ושמי השמים. . לא יכלכלוך</b>: מלכים-א ח, כז."],["7063","101","<b>כי גאה גאה</b>: בשלח טו, א. ראה גם לעיל קמ, א. וש\"נ."],["7064","102","<b>עילות העילות</b>: ת\"ז בהקדמה (יז, א)."],["7065","103","<b>אדם אדמ\"ה לעליון</b>: נסמן לעיל פ' שמות מו, ב."]]],[2300540459,"ובכאן בקי\"ס הרי בחי' העצמו' דהעלם המח' נעשה בחי' גילוי לבד, שא\"א להיות זה כ\"א למעלה ממקור ההשתלשלות דעו\"ע דמחדו\"מ, והיינו למעלה גם ממקור ההשפעה דאין ליש דמח' וחכ' הנ\"ל, והוא בעצמו' אא\"ס ב\"ה ממש וד\"ל.\n<b>וזהו</b> ואתה הרם את מטך<sup data-n=\"7066\">104</sup> ונטה את ידך על הים ובקעהו כו', דהנה ידוע בפי' מטה<sup data-n=\"7067\">105</sup> לשון הטי' כמו מטה כלפי חסד<sup data-n=\"7068\">106</sup>, כי מה שהשבט מן האילן נק' מטה הוא ע\"ש ההטי' שנוטה חוץ להלאה מגופו של אילן לכאן או לכאן וגם ע\"ש התפשטות נק' שבט<sup data-n=\"7069\">107</sup> כמו כוכבא דשביט<sup data-n=\"7070\">108</sup>, וכשהוא מתקשה וראשו העב למעלה להטות בו בידו ולהורידו בארץ למשענת והילוך נק' מטה כידוע. והדוגמא מזה בשרש כנ\"י שנק' שבטי י\"ה<sup data-n=\"7071\">109</sup> כשבט מגופא דאילנא דחיי שהוא חו\"ב ומדות דז\"א דאצי' ויש בה י\"ב גב\"א<sup data-n=\"7072\">110</sup> כידוע ע\"כ נק' הטיות אלה בשם מטות, וכאשר מטה כלפי חסד הוא שרש שבט דגל מחנה ראובן לדרום<sup data-n=\"7073\">111</sup> כו' ועכשיו הוא בחי' גילוי אלקות שנמשך למטה ע\"י העבודה באהבה וכן במדות היראה משבט ומטה כלפי גבו' וכה\"ג.\n<b>והנה</b> מ\"ש הרם את מטך דוקא שהוא מטה משה שנק' מטה האלקי'<sup data-n=\"7074\">112</sup> הוא בחי' מקור כל ההטיות דחו\"ב גם ברצון העליון שבחו\"ב ומדות כו' והוא בבחי' ד\"ע שרש משה<sup data-n=\"7075\">113</sup>, וכידוע ההפרש בין ד\"ע לד\"ת<sup data-n=\"7076\">114</sup> שד\"ת הוא המתפשט במדות להטות לחסד או לדין ולממוצע כו' וכמו\"כ בהטיי' השכל והטעם לזכות וחסד או להטות לחו\"ב כו', שזהו מלמטה למעלה ע\"י ההתקשרו' התחתון בעליון שנק' ד\"ת לעורר בחי' המשכה דמשפיע להטות כלפי חסד ורחמים, כמו עד\"מ המקשר עצמו בשכל ואהבה להמשיך לחסד וטוב כו' כמו יהי חסדך עלינו<sup data-n=\"7077\">115</sup> כאשר יחלנו לך וכן אנו או' יהי רצון מלפניך<sup data-n=\"7078\">116</sup> כו' וכמו רצה ה' אלקינו בעמך כו' ולתפלתם שעה ותהי לרצון<sup data-n=\"7079\">117</sup> כו' (כענין השבטי' שבאילן שפוני' כלפי מעלה ועי\"ז נק' מטות להטות השפע מלמעלה למטה כנ\"ל ששם עלו שבטי<sup data-n=\"7080\">118</sup> כו'). אבל בחי' ד\"ע הוא בחי' התקשרות המשפיע אל המקבל מלמעלה למטה להטות לרצונו וחכ' לחסד טוב<sup data-n=\"7081\">119</sup> מצד עצמו להכריע לזכות וחסד יותר, ונמצא הוא מקור כל ההכרעה שמכריע הרצון ושכל לזכות וחסד והיינו מקור של ההכרעה לימין כמו ענין קו המשקולת שהקו זהו מקור להכריע כו', כך מי הוא המכריע לשכל שיהי' נוטה לזכות וכן לרצון",[["7066","104","<b>ואתה הרם את מטך</b>: בשלח יד, טז."],["7067","105","<b>בפי' מטה</b>: ראה גם לקו\"א להה\"מ סקל\"ד [לא, ד במהדורת קה\"ת תשל\"ג]. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380650\" data-slug=\"likkutei-torah\" data-id=\"4001380650\">לקו\"ת מטות פב, א</a>. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' עדר. תקס\"ד ע' קצ. תקס\"ז ע' רצד. תקס\"ב ח\"א ע' רלז ואילך. ביאורי הזהר במדבר פה, ב. לעיל לז, ג. מב, א. קמ, ב."],["7068","106","<b>מטה כלפי חסד</b>: ראש השנה יז, א."],["7069","107","<b>ע\"ש התפשטות נק' שבט</b>: ראה גם לעיל קמ, ב ובהערה 55."],["7070","108","<b>כוכבא דשביט</b>: ברכות נח, ב."],["7071","109","<b>שבטי י\"ה</b>: תהלים קכב, ד."],["7072","110","<b>י\"ב גב\"א</b>: נסמן לעיל פ' בא קכז, ד."],["7073","111","<b>דגל מחנה ראובן לדרום</b>: במדבר ב, י."],["7074","112","<b>שנק' מטה האלקי'</b>: שמות ד, כ. וראה גם לעיל פ' שמות מב, ד. וש\"נ."],["7075","113","<b>ד\"ע שרש משה</b>: ראה זהר פקודי רכא, א. תניא פמ\"ב. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061254\" data-slug=\"likkutei-sichot\" data-id=\"1300061254\">לקוטי שיחות שמות (כרך ו) ע' 244</a> ואילך. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670131\" data-slug=\"torat-chaim\" data-id=\"2300670131\">תו\"ח וירא קי, ב</a> ובהערה 27. לעיל קמ, ב. לקמן פ' ויקהל תיא, ג."],["7076","114","<b>ההפרש בין ד\"ע לד\"ת</b>: ראה גם לעיל שם."],["7077","115","<b>יהי חסדך עלינו</b>: תהלים לג, כב (בהשמטת השם)."],["7078","116","<b>אנו או' יהי רצון מלפניך</b>: בברכות השחר."],["7079","117","<b>רצה. . ולתפלתם שעה ותהי לרצון</b>: תפלת העמידה ברכת רצה (בדילוג)."],["7080","118","<b>ששם עלו שבטי</b>: אוצ\"ל שבטי' — תהלים קכב, ד. וראה גם לעיל הערה 109."],["7081","119","<b>טוב</b>: אוצ\"ל: וטוב."]]],[2300540478,"שלמעלה מן הטעם שירצה לחסד, כמו מן הרצון ושכל וטעם לרצון יכול להיות לזכות ולחוב בשוה ממש, ומי הוא המכריע את כח המשכיל ההיולי להשכיל שכל לזכות או להטות הרצון שלמעלה מן הטעם לחסד יותר מחוב כו' הרי זהו בחי' ד\"ע דמשפיע שמקשר א\"ע להשפיע חסד ע\"כ מכריע כח השכל וכח הרצון להטות לזכות וחסד שירד השפע לחסד דוקא ולא לדין והרי ד\"ע זה הוא עיקר המקשר ומחבר לאור הרצון וחכ' לנטות כלפי חסד או להיפך כו' (וז\"ש יהי רצון מלפניך בבחי' ד\"ע מצד עצמו שלא ע\"י אתעדל\"ת כלל כו'). והנמשל מכ\"ז יובן בבחי' מטה משה שא' לו הרם את מטך כו' דמטה זה הוא בחי' מקור כל הטיי' רצה\"ע וחכ' וממילא נסתעף הטיי' זו במדות דחג\"ת דאצי' כו' (שנק' ד\"ת כנ\"ל) להיות שהוא בא מבחי' העצמו' ממש שלמעלה גם ממקור הרצון וחכ' כו' ע\"כ בכחו לנטות אותם לימין כו', והיינו להיותו למעלה גם מבחי' אין של היש דחכ' דא\"ק שנק' אדם דבריאה שגם הוא בא בבחי' השתלשלות דאין ליש עכ\"פ כמו התהוות השכל מלמעלה מן השכל כנ\"ל וכאשר יבא בזה בחי' התחדשות שלא כפי השתלשלות דאין ליש ה\"ז צריך לבא מבחי' ד\"ע דעצמו' ממש (שהוא המקשר לנטות הרצון וחכ' גם לבריאה דא\"ק מאין ליש כו'), להיותם<sup data-n=\"7082\">120</sup> למעלה מרצון וחכ' לגמרי להטות ולהפך סדר ההשתלשלות מאין ליש והוא להפוך הים ליבשה שהוא בחי' ההעלם עצמו יהי' בחי' גילוי שזה בא רק מצד בחי' גילוי העצמו' ממש שלמעלה מבחי' העלם וגילוי ע\"כ ההעלם נעשה גילוי לפניו, ולכך א' הרם את מטך דוקא לפי שבו תלוי עיקר הטיי' הרצון להיות היפוך ההשתלשלות דאין ויש עד בחי' העלם העצמו' דמשפיע נעשה בבחי' גילוי בכל המדריגות שזהו ענין קי\"ס כנ\"ל וד\"ל.\n<b>ומעתה</b> יש להבין ענין ההרמה שא' הרם את מטך מהו ענין הרמה זו למעלה דוקא, הענין הוא משום דגם בחי' ד\"ע הנ\"ל המקשר להטות הרצון הנעלם הנ\"ל כו' גם הוא צריך שיעלה בעליי' המדריגה לגבי בחי' מהו\"ע דאא\"ס ב\"ה ממש שהוא למעלה גם ממקור ההכרעה הזאת ברצון וחכ' כי הוא ית' אחד\"פ בתכלית לאו מכל אינון מדות כלל<sup data-n=\"7083\">121</sup> וכלל אפי' להיות מקור דמקור לרצון כידוע, וע\"כ אחר העלי' דבחי' ד\"ע שבפנימי' הכתר בעצמו' ממש משם יכול להוריד בירידה וצמצום מן העצמו' להיות ההטיי' ע\"י בחי' ד\"ע דשרש משה שהוא ענין המטה לנטות הרצון להפוך הים ליבשה כמ\"ש ונטה את ידך על הים ובקעהו. ומה שבשביל היפוך הים ליבשה דוקא צריך שירים את מטהו זה למעלה כו', הענין הוא משום דבהיפוך זו מים ליבשה מוכרח להיות מבחי' העצמו' ממש שלמעלה מים ויבשה גם בשרש שרשן עד רום המעלות דהיינו במהו\"ע הא\"ס שאין שם שרש לשרש לים ויבשה שנק' העלם וגילוי בכלל ובפרט ע\"כ",[["7082","120","<b>להיותם</b>: אוצ\"ל: להיותו."],["7083","121","<b>לאו מכל אינון מדות כלל</b>: ראה ת\"ז בהקדמה (יז, ב)."]]],[2300540496,"משם דוקא יהופך ההעלם עצמו לגילוי. והענין הוא כידוע דכל בחי' ההשתלשלות מאין ליש ומיש ליש הנ\"ל הכל הוא ע\"י צמצום הראשון שנק' מקו\"פ<sup data-n=\"7084\">122</sup> כו' וכמ\"ש ישת חשך סתרו<sup data-n=\"7085\">123</sup> ואח\"כ יצא האור דקו\"ח כו' ונק' בריא' ויצי' בכלל, וע\"כ יש גם בע\"ס דאצי' העלם וגילוי כמ\"ש אפיקת יו\"ד תיקונין<sup data-n=\"7086\">124</sup> וקרית להון י\"ס לאנהגא בהון עלמין כו', שי\"ס הללו כבר היו בבחי' ההעלם העצמו' כמו שלהבת הקשורה בגחלת<sup data-n=\"7087\">125</sup> בהעלם גדול ויצאו לגילוי במציאות או\"כ כמו חכ' מוחא חסד דרועא<sup data-n=\"7088\">126</sup> כו', וז\"ש אפיק מן ההעלם לגילוי לבד כדי לאנהגא בהון שיהי' מקור לעלמין סתימין ועלמין דאתגליין<sup data-n=\"7089\">127</sup> שזהו בחי' העלם וגילוי בעולמות דבי\"ע כידוע, עד שזה הסדר דהעלם וגילוי ישנו בכל עולם בפרט בכל עו\"ע כידוע, ובכל מקום ומדריגה בראש ובסוף כל דרגין א\"א שיבא מעצמו' ההעלם לגילוי כמו שעצם המח' וחכ' כמו שהוא נמשך מבחי' אין ממש אינו מתגלה בדיבור כלל רק בחי' האחרונה שבה שהן האותיו' דמח' ושכל כנ\"ל, וכמו בשרש לשרש בהעלם וגילוי הכללי בצמצום דקו\"ח א\"א שיתגלה העלם העצמיו' ממש כמו שהוא כו' (וכ\"ש שא\"א שיהי' הגילוי במדריגה דהעלם העילה עצמו בדרך עלי' מלמטה למעלה כמו שא\"א שיהי' גילוי הדיבור במדריגה דפנימי' עצמי' המח' כנ\"ל), אבל למעלה ממקור ושרש לשרש דהעלם וגילוי הכללי הנ\"ל שהוא במהו\"ע דא\"ס ממש אין הכרח כלל לבחי' סדר הזה דהעלם וגילוי שיהי' מוכרח שלא יתגלה עצמו' ההעלם לגילוי מאחר שהוא למעלה מבחי' השפע דעו\"ע גם מבחי' השתלשלות דאין ויש כו', א\"כ משם דוקא יוכל להיות היפוך ההעלם עצמו כמו בחי' חשך סתרו הנ\"ל להיות בבחי' גילוי ובחי' הגילוי דקו\"ח יהי' במדריגת ההעלם דעצמו' המשפיע כו' (שהוא להשפיל הגבוה ולהגביה הנמוך שיהי' משפיע המקבל והמקבל משפיע כמו לע\"ל דכתי' א\"ח עט\"ב<sup data-n=\"7090\">128</sup>, וכבר הי' כן בוימ\"ב דכתי' יקוו המים כו' ותראה היבשה<sup data-n=\"7091\">129</sup> למעלה מן הים כו' אלא שלא נהפוך הים עצמו ליבשה רק שירדו המים למטה כו' כמ\"ש במ\"א). וזהו ענין ההרמה שא' לו הרם את מטך פי' הרם כח מטך דהיינו לבחי' ד\"ע שרש משה למעלה מעלה כלפי בחי' העצמיו' ממש שלמעלה ממקור למקור דבחי' השתלשלות דהעלם וגילוי בכלל ובפרט כנ\"ל, כדי שמשם יומשך ענין היפוך ההשתלשלות להיות מהעלם עצמו בחי' גילוי שהוא היפוך הים ליבשה וכמ\"ש הים ראה וינוס<sup data-n=\"7092\">130</sup> כו' וד\"ל.\n<b>אך</b> מ\"ש עוד ונטה את ידך על הים כו' אחר שכבר א' הרם את מטך כו', הענין הוא דפי' נטי' זאת שא' נטה את ידך הוא בחי' הירידה והמשכה מגבוה לנמוך מלמעלה למטה אחר בחי' ההעלא' דהרם את מטך כו', לפי שצריך להמשיך ולהוריד שפע חדשה שיהי' ים יבשה בגשמיו' ממש שצריך להיות שינוי צירוף",[["7084","122","<b>צמצום. . שנק' מקו\"פ</b>: ראה עץ חיים (דרוש עגולים ויושר), ש\"א, ענף ב."],["7085","123","<b>ישת חשך סתרו</b>: נסמן לעיל פ' בא קכג, ג."],["7086","124","<b>אפיקת יו\"ד תיקונין</b>: ראה ת\"ז בהקדמה (יז, א)."],["7087","125","<b>שי\"ס. . כמו שלהבת הקשורה בגחלת</b>: ספר יצירה פ\"א, מ\"ז."],["7088","126","<b>חכ' מוחא חסד דרועא</b>: ראה ת\"ז שם."],["7089","127","<b>לעלמין סתימין ועלמין דאתגליין</b>: ת\"ז שם."],["7090","128","<b>א\"ח עט\"ב</b>: משלי יב, ד."],["7091","129","<b>יקוו המים. . ותראה היבשה</b>: בראשית א, ט. ראה גם שער האמונה פס\"ו. דרך חיים שער התפלה פנ\"א."],["7092","130","<b>הים ראה וינוס</b>: תהלים קיד, ג."]]],[2300540514,"חדש דים ליבשה בפ\"מ בבקיעת הים ע\"כ הוצרך לבא זה ג\"כ בבחי' ההשתלשלות דיו\"ד דחכ'<sup data-n=\"7093\">131</sup> מאין ליש בירידה וצמצום כשאר דרך השתלשלות עו\"ע רק שבא בשינוי הצירופי' (כמו מי שא' לשמן הוא יאמר דוקא לחומץ כו' וכהנ\"ל בכל הניסי' לשנות הטבע בפ\"מ), ע\"כ אמר עוד ונטה את ידך על הים שיבא השפע חדשה זו מבחי' החכ' דיו\"ד שזהו פי' יד\"ך<sup data-n=\"7094\">132</sup>, או ידך ממש שהוא ירידת המשכת השפע מגבוה לנמוך אחר ההרמה של המטה למעלה מטעם הנ\"ל וד\"ל.\n<b>ולהבין</b> כ\"ז בתוס' ביאור הנה יש להקדים ענין א' הידוע עד\"מ בנפש האדם שכלולה מה' מדריגות נר\"נ ח\"י<sup data-n=\"7095\">133</sup> שיש בכ\"א בחי' אותיו' וכידוע שגם הנפש עצמה מלאה אותיות<sup data-n=\"7096\">134</sup> והוא בחי' גילוי האור של עצם הנפש ממש כמו שהוא (והן כ\"ב אותיו' הקבועי' בנפש עצמה כמ\"ש בלק\"א<sup data-n=\"7097\">135</sup> ). ויש להבין תחלה שרש בחי' האותיות שהוא בחי' הגילוי של כל דבר ודבר מה במציאות שיש בנפש ולכל כח וכח הנמשך מעצמות הנפש כמו האותיו' שנגלה במציאות כח הדיבור ומח' שהוא רק בחי' התגלות של הכח דמו\"ד עצמן שמראי' על עצם המהות דכחות המו\"ד ממש וכן כח המעשה נגלה באותיות המעשה כאותיו' הכתב וכה\"ג בכל מלאכה ופעולה גשמי' כך יש אותיו' ג\"כ במדות שבלב באוי\"ר וכהנ\"ל שמתגלים בלב וכן יש אותיו' השכל ואותיו' הרצון והתענוג כו' וגם למעלה מן הרצון ותענוג שהוא עצם הנפש יש אותיו' דבחי' יחידה כו'.\n<b>וביאור</b> הדברים הנה ידוע בפי' אותיו' מלשון אתא<sup data-n=\"7098\">136</sup> שהוא תרגום של בא<sup data-n=\"7099\">137</sup> כמו אתא בוקר<sup data-n=\"7100\">138</sup> כו' וגם לשון אות<sup data-n=\"7101\">139</sup> וסימן שהוא כמו ציון לבד כמשי\"ת, וכמו הרצון ותענוג שהי' כלול בהעלם עצמו' הנפש ממש כאשר באו לידי גילוי נק' בשם אותיו' הרצון והתענוג כלו' שבא מהעלם בשכל וכן אותיו' מו\"ד כאשר מתגלי' במח' ודיבור. והנה כ\"ז נק' אותיו' משפיעים שע\"י נמשך מעילה לעלול שאם לא בחי' אותיו' הללו הרי לא הי' קירוב וחיבור לרצון עם השכל ושכל עם המדות מו\"ד כו', רק ע\"י גילוי אותיו' הרצון נמשך להיות השכל וטעם לרצון וכן ע\"י אותיו' השכל נמשך ומתחבר שפע השכל במדו' וכן ממדות למח' ודיבור כו', והרי אנו רואי' שתומ\"י שיעלה ברצונו דבר מה יבא לכלל שכל וטעם לרצון ומשכל למדות ומח' דו\"מ כו' אבל אין זה רק בחי' התגלות של כל עילה מבחי' האחרונה שבה לבד, כי א\"א שיבא עצם כח הרצון והתענוג כמו שהוא באותיות הללו שא\"כ הי' הכל בבחי' רצון שלמעלה מן הטעם כי אין טעם לרצון כלל<sup data-n=\"7102\">140</sup> וכלל, וכן משכל למדות אם הי' מתגלה עצם מהות השכל לא הי' נמשך להתפעלות המדות, וכן ממדות למח' ודיבור, אלא",[["7093","131","<b>ההשתלשלות דיו\"ד דחכ'</b>: ראה גם לעיל קמ, ג. ובהנסמן לשם."],["7094","132","<b>שזהו פי' יד\"ך</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370215\" data-slug=\"torah-or\" data-id=\"3901370215\">תו\"א ויחי מז, רע\"ג</a>. מאמרי אדה\"ז תקס\"ה ח\"א ע' קע. וראה גם מאמרי אדה\"א הנחות תקע\"ז ס\"ע יב. וש\"נ."],["7095","133","<b>נר\"נ ח\"י</b>: ראה ב\"ר פי\"ד, ט. מאמרי אדה\"א דברים ח\"ב ע' תכח. וש\"נ."],["7096","134","<b>הנפש עצמה מלאה אותיות</b>: ראה ע\"ח (שער טנת\"א) ש\"ה, פ\"ג. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תרלט וע' תשל ובהנסמן במ\"מ לשם. הנסמן במאמרי אדה\"א במדבר ח\"א ס\"ע שט."],["7097","135","<b>כ\"ב אותיו'. . כמ\"ש בלק\"א</b>: ראה שער היחוד והאמונה פי\"א. אגרת הקדש ס\"ה."],["7098","136","<b>אותיו' מלשון אתא</b>: נסמן לעיל פ' שמות כה, ג."],["7099","137","<b>אתא. . תרגום של בא</b>: ת\"א ות\"י לך יד, ה."],["7100","138","<b>אתא בוקר</b>: ישעי' כא, יב."],["7101","139","<b>אותיו' מלשון. . אות</b>: ראה לעיל לב, א. וש\"נ."],["7102","140","<b>אין טעם לרצון כלל</b>: נסמן לעיל פ' בא פט, ד."]]]]});
